use std::num::ParseIntError;

fn parse_numbers(text: &str) -> Result<Vec<i32>, ParseIntError> {
    let mut numbers = Vec::new();
    for token in text.split(',') {
        let value = token.trim().parse::<i32>()?;
        numbers.push(value);
    }
    Ok(numbers)
}

fn parse_entry(entry: &str) -> Result<(String, Vec<i32>), String> {
    let (label, values) = entry
        .split_once('=')
        .ok_or_else(|| format!("entry `{}` is missing an `=` separator", entry))?;
    let numbers = parse_numbers(values).map_err(|e| format!("bad numbers in `{}`: {}", label, e))?;
    Ok((label.trim().to_string(), numbers))
}

fn sum_even_numbers(numbers: &[i32]) -> i32 {
    numbers.iter().filter(|n| *n % 2 == 0).sum()
}

fn even_average(numbers: &[i32]) -> Option<i32> {
    let count = numbers.iter().filter(|n| *n % 2 == 0).count() as i32;
    sum_even_numbers(numbers).checked_div(count)
}

fn largest_even(numbers: &[i32]) -> Option<i32> {
    numbers.iter().copied().filter(|n| n % 2 == 0).max()
}

fn format_entry(label: &str, numbers: &[i32]) -> String {
    let average = match even_average(numbers) {
        Some(avg) => avg.to_string(),
        None => String::from("n/a"),
    };
    let largest = match largest_even(numbers) {
        Some(max) => max.to_string(),
        None => String::from("n/a"),
    };
    format!(
        "{:<6} values={:?} sum_even={} avg_even={} max_even={}",
        label,
        numbers,
        sum_even_numbers(numbers),
        average,
        largest
    )
}

fn report_entry(entry: &str) -> Result<String, String> {
    let (label, numbers) = parse_entry(entry)?;
    Ok(format_entry(&label, &numbers))
}

fn summarize_all(entries: &[&str]) -> Result<String, String> {
    let mut lines = Vec::new();
    let mut grand_total = 0;
    for entry in entries {
        let (label, numbers) = parse_entry(entry)?;
        grand_total += sum_even_numbers(&numbers);
        lines.push(format_entry(&label, &numbers));
    }
    lines.push(format!("total even sum across entries: {}", grand_total));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), String> {
    println!("{}", sum_even_numbers(&[1, 2, 3, 4, 5]));
    println!("{}", sum_even_numbers(&[10, 20, 31]));

    let entries = ["small=1, 2, 3, 4, 5", "tens=10, 20, 31", "odds=1, 3, 5"];
    println!("{}", summarize_all(&entries)?);
    println!("{}", report_entry("mixed=-4, 7, 8, 9, 12")?);
    Ok(())
}

