fn is_palindrome(s: &str) -> bool {
    let cleaned: String = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .collect();

    let lowercased: String = cleaned.to_lowercase();

    let reversed: String = lowercased.chars().rev().collect();

    lowercased == reversed
}

