fn celsius_to_fahrenheit(celsius: f64) -> f64 {
    celsius * 9.0 / 5.0 + 32.0
}

#[derive(Debug)]
struct Reading {
    station: String,
    celsius: f64,
}

fn parse_celsius(text: &str) -> Result<f64, String> {
    let trimmed = text.trim().trim_end_matches(|c| c == 'C' || c == 'c');
    let value: f64 = trimmed
        .trim()
        .parse()
        .map_err(|_| format!("not a number: {:?}", text.trim()))?;
    if value < -273.15 {
        return Err(format!("{} C is below absolute zero", value));
    }
    Ok(value)
}

fn parse_reading(line: &str) -> Result<Reading, String> {
    let (station, temperature) = line
        .split_once(',')
        .ok_or_else(|| format!("missing comma in {:?}", line))?;
    let station = station.trim();
    if station.is_empty() {
        return Err(format!("empty station name in {:?}", line));
    }
    let celsius = parse_celsius(temperature)?;
    Ok(Reading {
        station: station.to_string(),
        celsius,
    })
}

fn parse_report(input: &str) -> Result<Vec<Reading>, String> {
    let mut readings = Vec::new();
    for (index, line) in input.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let reading = parse_reading(line).map_err(|e| format!("line {}: {}", index + 1, e))?;
        readings.push(reading);
    }
    Ok(readings)
}

fn format_reading(line: &str) -> Result<String, String> {
    let reading = parse_reading(line)?;
    Ok(format!(
        "{:<10} {:>7.1} C = {:>7.1} F",
        reading.station,
        reading.celsius,
        celsius_to_fahrenheit(reading.celsius)
    ))
}

fn warmest(input: &str) -> Result<String, String> {
    let readings = parse_report(input)?;
    let hottest = readings
        .into_iter()
        .max_by(|a, b| a.celsius.total_cmp(&b.celsius))
        .ok_or_else(|| "no readings in report".to_string())?;
    Ok(format!(
        "warmest: {} at {:.1} F",
        hottest.station,
        celsius_to_fahrenheit(hottest.celsius)
    ))
}

fn run(input: &str) -> Result<(), String> {
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        println!("{}", format_reading(line)?);
    }
    println!("{}", warmest(input)?);
    Ok(())
}

fn main() {
    let report = "Oslo, -8.5\nCairo, 38\nQuito, 21.4C\nReykjavik, 0\n";
    if let Err(err) = run(report) {
        eprintln!("error: {}", err);
    }
    match parse_celsius("-400") {
        Ok(c) => println!("{:.1} F", celsius_to_fahrenheit(c)),
        Err(err) => eprintln!("error: {}", err),
    }
}

