use std::cmp::Ordering;
use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum StatsError {
    MissingLabel(String),
    BadNumber(ParseFloatError),
    NoMeasurements(String),
}

impl fmt::Display for StatsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StatsError::MissingLabel(record) => write!(f, "record has no ':' separator: {record}"),
            StatsError::BadNumber(err) => write!(f, "invalid measurement: {err}"),
            StatsError::NoMeasurements(label) => write!(f, "no measurements for {label}"),
        }
    }
}

impl From<ParseFloatError> for StatsError {
    fn from(err: ParseFloatError) -> Self {
        StatsError::BadNumber(err)
    }
}

fn calculate_average(numbers: &[f64]) -> Option<f64> {
    if numbers.is_empty() {
        return None;
    }
    Some(numbers.iter().sum::<f64>() / numbers.len() as f64)
}

fn median(numbers: &[f64]) -> Option<f64> {
    let mut sorted = numbers.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
    let mid = sorted.len() / 2;
    if sorted.len() % 2 == 1 {
        return sorted.get(mid).copied();
    }
    let upper = *sorted.get(mid)?;
    let lower = *sorted.get(mid - 1)?;
    Some((lower + upper) / 2.0)
}

fn spread(numbers: &[f64]) -> Option<f64> {
    let min = numbers.iter().copied().reduce(f64::min)?;
    let max = numbers.iter().copied().reduce(f64::max)?;
    Some(max - min)
}

fn parse_measurements(list: &str) -> Result<Vec<f64>, StatsError> {
    let mut values = Vec::new();
    for field in list.split(',').filter(|s| !s.trim().is_empty()) {
        values.push(field.trim().parse::<f64>()?);
    }
    Ok(values)
}

fn format_record(record: &str) -> Result<String, StatsError> {
    let (label, list) = record
        .split_once(':')
        .ok_or_else(|| StatsError::MissingLabel(record.to_string()))?;
    let label = label.trim();
    let values = parse_measurements(list)?;
    let missing = || StatsError::NoMeasurements(label.to_string());
    let mean = calculate_average(&values).ok_or_else(missing)?;
    let mid = median(&values).ok_or_else(missing)?;
    let range = spread(&values).ok_or_else(missing)?;
    Ok(format!(
        "{label}: n={} mean={mean:.3} median={mid:.3} spread={range:.3}",
        values.len()
    ))
}

fn main() -> Result<(), StatsError> {
    for record in ["morning: 1.0, 2.0, 3.0", "evening: 4.5, 0.5, 2.0, 7.0"] {
        println!("{}", format_record(record)?);
    }
    match format_record("noon: ") {
        Ok(line) => println!("{line}"),
        Err(err) => println!("skipped: {err}"),
    }
    Ok(())
}

