    Some(numbers.iter().sum::<f64>() / numbers.len() as f64)
}

fn median(numbers: &[f64]) -> Option<f64> {
    let mut sorted = numbers.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
    let mid = sorted.len() / 2;
    if sorted.len() % 2 == 1 {
        return sorted.get(mid).copied();
    }
    let upper = *match sorted.get(mid) {
        Some(v) => v,
        None => return None,
    };
    let lower = *match sorted.get(mid - 1) {
        Some(v) => v,
        None => return None,
    };
    Some((lower + upper) / 2.0)
}

fn spread(numbers: &[f64]) -> Option<f64> {
    let min = match numbers.iter().copied().reduce(f64::min) {
        Some(v) => v,
        None => return None,
    };
    let max = match numbers.iter().copied().reduce(f64::max) {
        Some(v) => v,
        None => return None,
    };
    Some(max - min)
}

fn parse_measurements(list: &str) -> Result<Vec<f64>, StatsError> {
    let mut values = Vec::new();
    for field in list.split(',').filter(|s| !s.trim().is_empty()) {
        values.push(match field.trim().parse::<f64>() {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(values)
}

fn format_record(record: &str) -> Result<String, StatsError> {
    let (label, list) = match record
        .split_once(':')
        .ok_or_else(|| StatsError::MissingLabel(record.to_string()))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let label = label.trim();
    let values = match parse_measurements(list) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let missing = || StatsError::NoMeasurements(label.to_string());
    let mean = match calculate_average(&values).ok_or_else(missing) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let mid = match median(&values).ok_or_else(missing) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let range = match spread(&values).ok_or_else(missing) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(format!(
        "{label}: n={} mean={mean:.3} median={mid:.3} spread={range:.3}",
        values.len()
    ))
}

fn main() -> Result<(), StatsError> {
    for record in ["morning: 1.0, 2.0, 3.0", "evening: 4.5, 0.5, 2.0, 7.0"] {
        println!("{}", match format_record(record) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    match format_record("noon: ") {
        Ok(line) => println!("{line}"),
        Err(err) => println!("skipped: {err}"),
    }
    Ok(())
}

