use std::fmt;
use std::str::Split;

#[derive(Debug)]
enum ParseError {
    MissingField(&'static str),
    BadAge(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingField(name) => write!(f, "missing field `{}`", name),
            ParseError::BadAge(raw) => write!(f, "`{}` is not a valid age", raw),
        }
    }
}

struct Person {
    name: String,
    city: String,
    age: u32,
}

fn next_field<'a>(parts: &mut Split<'a, char>, name: &'static str) -> Result<&'a str, ParseError> {
    let raw = parts.next().ok_or(ParseError::MissingField(name))?;
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(ParseError::MissingField(name));
    }
    Ok(trimmed)
}

fn parse_person(line: &str) -> Result<Person, ParseError> {
    let mut parts = line.split(',');
    let name = title_case(next_field(&mut parts, "name")?);
    let city = title_case(next_field(&mut parts, "city")?);
    let age_raw = next_field(&mut parts, "age")?;
    let age = age_raw
        .parse::<u32>()
        .map_err(|_| ParseError::BadAge(age_raw.to_string()))?;
    Ok(Person { name, city, age })
}

fn describe(line: &str) -> Result<String, ParseError> {
    let person = parse_person(line)?;
    Ok(format!(
        "{} ({}) lives in {}",
        person.name, person.age, person.city
    ))
}

fn build_report(data: &str) -> Result<String, ParseError> {
    let mut report = String::new();
    for line in data.lines().filter(|l| !l.trim().is_empty()) {
        report.push_str(&describe(line)?);
        report.push('\n');
    }
    Ok(report)
}

fn capitalize_first(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(first) => {
            let mut out: String = first.to_uppercase().collect();
            out.extend(chars.as_str().to_lowercase().chars());
            out
        }
        None => String::new(),
    }
}

fn title_case(phrase: &str) -> String {
    phrase
        .split_whitespace()
        .map(capitalize_first)
        .collect::<Vec<String>>()
        .join(" ")
}

fn main() -> Result<(), ParseError> {
    let data = "ada LOVELACE, london, 36\nGRACE hopper, NEW york city, 85\nalan turing,MANCHESTER, 41\n";
    print!("{}", build_report(data)?);
    Ok(())
}

