use std::fmt::Write as _;

/// Dot product of two equal-length, non-empty vectors.
fn dot_product(v1: &[f64], v2: &[f64]) -> f64 {
    v1.iter().zip(v2.iter()).map(|(a, b)| a * b).sum()
}

fn norm(v: &[f64]) -> f64 {
    dot_product(v, v).sqrt()
}

/// Cosine similarity; `None` when either vector has zero magnitude.
fn cosine_similarity(v1: &[f64], v2: &[f64]) -> Option<f64> {
    let denom = norm(v1) * norm(v2);
    if denom == 0.0 {
        return None;
    }
    Some(dot_product(v1, v2) / denom)
}

fn parse_vector(text: &str) -> Result<Vec<f64>, String> {
    let mut components = Vec::new();
    for token in text.split(',') {
        let value: f64 = token
            .trim()
            .parse()
            .map_err(|_| format!("`{}` is not a number", token.trim()))?;
        components.push(value);
    }
    Ok(components)
}

fn parse_pair(line: &str) -> Result<(Vec<f64>, Vec<f64>), String> {
    let mut halves = line.split(';');
    let left = halves.next().ok_or("missing first vector")?;
    let right = halves.next().ok_or("missing second vector")?;
    let v1 = parse_vector(left)?;
    let v2 = parse_vector(right)?;
    Ok((v1, v2))
}

fn validated_pair(line: &str) -> Result<(Vec<f64>, Vec<f64>), String> {
    let (v1, v2) = parse_pair(line)?;
    if v1.is_empty() {
        return Err("vectors must be non-empty".to_string());
    }
    if v1.len() != v2.len() {
        return Err(format!("length mismatch: {} vs {}", v1.len(), v2.len()));
    }
    Ok((v1, v2))
}

fn format_report(line: &str) -> Result<String, String> {
    let (v1, v2) = validated_pair(line)?;
    let product = dot_product(&v1, &v2);
    let similarity = cosine_similarity(&v1, &v2).ok_or("zero-magnitude vector")?;
    let mut out = String::new();
    write!(out, "dot = {:.3}, cosine = {:.3}", product, similarity)
        .map_err(|e| e.to_string())?;
    Ok(out)
}

fn total_dot(lines: &[&str]) -> Result<f64, String> {
    let mut sum = 0.0;
    for line in lines {
        let (v1, v2) = validated_pair(line)?;
        sum += dot_product(&v1, &v2);
    }
    Ok(sum)
}

fn main() {
    let inputs = ["1,2; 3,4", "1,1,1; 2,2,2", "0,0; 1,1", "1,2; 3", "1,x; 2,3"];
    for line in &inputs {
        match format_report(line) {
            Ok(report) => println!("{:<14} -> {}", line, report),
            Err(err) => println!("{:<14} -> error: {}", line, err),
        }
    }

    let good = ["1,2; 3,4", "1,1,1; 2,2,2"];
    match total_dot(&good) {
        Ok(sum) => println!("sum of dot products = {}", sum),
        Err(err) => println!("could not total: {}", err),
    }
}

