        words.push(match validate_word(trimmed) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    if words.is_empty() {
        return Err(AppError::NoWords);
    }
    Ok(words)
}

fn build_report(text: &str, words: &[String]) -> String {
    let mut out = String::new();
    let mut total = 0usize;
    for word in words {
        let count = count_word_occurrences(text, word);
        total += count;
        out.push_str(&format!("{:<20}{}\n", word, count));
    }
    out.push_str(&format!("{:<20}{}\n", "TOTAL", total));
    out
}

fn run() -> Result<(), AppError> {
    let mut args = env::args().skip(1);
    let text_path = match args.next().ok_or(AppError::Usage) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let words_path = match args.next().ok_or(AppError::Usage) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let text = match fs::read_to_string(&text_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let words = match load_words(&words_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    print!("{}", build_report(&text, &words));
    Ok(())
}

fn describe(err: &AppError) -> String {
    match err {
        AppError::Usage => "usage: wordcount <text-file> <word-list-file>".to_string(),
        AppError::Io(e) => format!("i/o error: {}", e),
        AppError::BadWord(w) => format!("invalid word entry: {:?}", w),
        AppError::NoWords => "word list contains no entries".to_string(),
    }
}

fn main() {
    if let Err(e) = run() {
        eprintln!("{}", describe(&e));
        std::process::exit(1);
    }
}

