fn simple_interest(principal: f64, rate: f64, time: f64) -> f64 {
    principal + principal * rate * time
}

#[derive(Debug)]
struct Loan {
    label: String,
    principal: f64,
    rate: f64,
    time: f64,
}

fn parse_amount(text: &str, field: &str) -> Result<f64, String> {
    let value: f64 = text
        .trim()
        .parse()
        .map_err(|_| format!("field `{}` is not a number: {:?}", field, text.trim()))?;
    if value.is_finite() && value >= 0.0 {
        Ok(value)
    } else {
        Err(format!("field `{}` must be finite and non-negative", field))
    }
}

fn next_amount<'a, I: Iterator<Item = &'a str>>(parts: &mut I, field: &str) -> Result<f64, String> {
    let text = parts.next().ok_or_else(|| format!("missing `{}`", field))?;
    parse_amount(text, field)
}

fn parse_loan(line: &str) -> Result<Loan, String> {
    let (label, rest) = line
        .split_once(',')
        .ok_or_else(|| format!("record {:?} has no separated fields", line))?;
    let mut parts = rest.split(',');
    let principal = next_amount(&mut parts, "principal")?;
    let rate = next_amount(&mut parts, "rate")?;
    let time = next_amount(&mut parts, "time")?;
    if parts.next().is_some() {
        return Err(format!("too many fields in record {:?}", line));
    }
    Ok(Loan { label: label.trim().to_string(), principal, rate, time })
}

fn format_row(loan: &Loan) -> String {
    let total = simple_interest(loan.principal, loan.rate, loan.time);
    format!(
        "{:<10} {:>10.2} {:>6.2}% {:>5.1}y -> {:>10.2} (interest {:>9.2})",
        loan.label,
        loan.principal,
        loan.rate * 100.0,
        loan.time,
        total,
        total - loan.principal
    )
}

fn format_loan(line: &str) -> Result<String, String> {
    let loan = parse_loan(line)?;
    Ok(format_row(&loan))
}

fn report(records: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    let mut grand_total = 0.0;
    for record in records {
        let loan = parse_loan(record)?;
        out.push_str(&format_row(&loan));
        out.push('\n');
        grand_total += simple_interest(loan.principal, loan.rate, loan.time);
    }
    out.push_str(&format!("{:<10} {:>44.2}\n", "TOTAL", grand_total));
    Ok(out)
}

fn main() -> Result<(), String> {
    let records = [
        "alpha, 1000.0, 0.05, 2.0",
        "beta, 500.0, 0.10, 1.0",
        "gamma, 2500.0, 0.035, 4.5",
    ];
    print!("{}", report(&records)?);
    println!("{}", format_loan("delta, 750, 0.08, 3")?);
    match report(&["bad, 100, oops, 1"]) {
        Ok(text) => print!("{}", text),
        Err(message) => println!("rejected: {}", message),
    }
    Ok(())
}

