fn calculate_bmi(weight_kg: f64, height_m: f64) -> f64 {
    weight_kg / (height_m * height_m)
}

#[derive(Debug)]
struct Person {
    name: String,
    weight_kg: f64,
    height_m: f64,
}

fn parse_measure(raw: &str, label: &str) -> Result<f64, String> {
    let value: f64 = raw
        .parse()
        .map_err(|_| format!("{} is not a number: {:?}", label, raw))?;
    if value <= 0.0 {
        return Err(format!("{} must be positive, got {}", label, value));
    }
    Ok(value)
}

fn parse_person(line: &str) -> Result<Person, String> {
    let fields: Vec<&str> = line.split(',').map(str::trim).collect();
    if fields.len() != 3 {
        return Err(format!(
            "expected 3 fields (name,weight,height), got {} in {:?}",
            fields.len(),
            line
        ));
    }
    if fields[0].is_empty() {
        return Err(format!("missing name in record: {:?}", line));
    }
    let weight_kg = parse_measure(fields[1], "weight")?;
    let height_m = parse_measure(fields[2], "height")?;
    Ok(Person {
        name: fields[0].to_string(),
        weight_kg,
        height_m,
    })
}

fn classify(bmi: f64) -> &'static str {
    if bmi < 18.5 {
        "underweight"
    } else if bmi < 25.0 {
        "normal"
    } else if bmi < 30.0 {
        "overweight"
    } else {
        "obese"
    }
}

fn format_row(line: &str) -> Result<String, String> {
    let person = parse_person(line)?;
    let bmi = calculate_bmi(person.weight_kg, person.height_m);
    Ok(format!("{:<8} {:6.3}  {}", person.name, bmi, classify(bmi)))
}

fn average_bmi(records: &[&str]) -> Result<f64, String> {
    if records.is_empty() {
        return Err("no records to average".to_string());
    }
    let mut total = 0.0;
    for line in records {
        let person = parse_person(line)?;
        total += calculate_bmi(person.weight_kg, person.height_m);
    }
    Ok(total / records.len() as f64)
}

fn main() -> Result<(), String> {
    let records = ["Ann,70.0,1.75", "Bob,90.0,1.80", "Cleo,52.5,1.68"];
    for line in &records {
        println!("{}", format_row(line)?);
    }
    println!("average BMI: {:.3}", average_bmi(&records)?);
    Ok(())
}

