use std::fmt;
use std::num::ParseIntError;
use std::process::ExitCode;

#[derive(Debug)]
enum SpecError {
    Syntax(String),
    Length(ParseIntError),
    EmptyList,
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SpecError::Syntax(line) => write!(f, "malformed spec, expected \"words | n\": {:?}", line),
            SpecError::Length(err) => write!(f, "invalid minimum length: {}", err),
            SpecError::EmptyList => write!(f, "spec contains no words"),
        }
    }
}

fn filter_long_words(words: &[&str], min_length: usize) -> Vec<String> {
    words
        .iter()
        .filter(|w| w.len() > min_length)
        .map(|w| w.to_string())
        .collect()
}

fn split_words(field: &str) -> Result<Vec<String>, SpecError> {
    let words: Vec<String> = field.split_whitespace().map(str::to_string).collect();
    if words.is_empty() {
        return Err(SpecError::EmptyList);
    }
    Ok(words)
}

fn parse_spec(line: &str) -> Result<(Vec<String>, usize), SpecError> {
    let (list, bound) = line
        .split_once('|')
        .ok_or_else(|| SpecError::Syntax(line.to_string()))?;
    let min_length = bound.trim().parse::<usize>().map_err(SpecError::Length)?;
    let words = split_words(list)?;
    Ok((words, min_length))
}

fn format_report(kept: &[String], min_length: usize) -> String {
    match kept.iter().max_by_key(|w| w.len()) {
        Some(longest) => format!(
            "{} word(s) longer than {}: {:?} (longest: {})",
            kept.len(),
            min_length,
            kept,
            longest
        ),
        None => format!("no word longer than {}", min_length),
    }
}

fn run_spec(line: &str) -> Result<String, SpecError> {
    let (words, min_length) = parse_spec(line)?;
    let borrowed: Vec<&str> = words.iter().map(String::as_str).collect();
    let kept = filter_long_words(&borrowed, min_length);
    Ok(format_report(&kept, min_length))
}

fn process_all(specs: &[&str]) -> Result<Vec<String>, SpecError> {
    let mut reports = Vec::with_capacity(specs.len());
    for line in specs {
        reports.push(run_spec(line)?);
    }
    Ok(reports)
}

fn main() -> ExitCode {
    let specs = ["a apple banana | 3", "cat dog bird | 5", "one two three four | 2"];
    match process_all(&specs) {
        Ok(reports) => {
            for report in reports {
                println!("{}", report);
            }
            ExitCode::SUCCESS
        }
        Err(err) => {
            eprintln!("error: {}", err);
            ExitCode::FAILURE
        }
    }
}

