use std::f64::consts::PI;
use std::fmt::{self, Write as _};

#[derive(Debug)]
enum AreaError {
    Parse(String),
    Negative(f64),
    NotFinite(String),
    Format(fmt::Error),
}

impl fmt::Display for AreaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AreaError::Parse(text) => write!(f, "`{}` is not a number", text),
            AreaError::Negative(r) => write!(f, "radius {} is negative", r),
            AreaError::NotFinite(text) => write!(f, "`{}` is not a finite radius", text),
            AreaError::Format(e) => write!(f, "formatting failed: {}", e),
        }
    }
}

impl From<fmt::Error> for AreaError {
    fn from(e: fmt::Error) -> Self {
        AreaError::Format(e)
    }
}

fn circle_area(radius: f64) -> f64 {
    PI * radius * radius
}

fn parse_radius(text: &str) -> Result<f64, AreaError> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|_| AreaError::Parse(trimmed.to_string()))?;
    if !value.is_finite() {
        return Err(AreaError::NotFinite(trimmed.to_string()));
    }
    if value < 0.0 {
        return Err(AreaError::Negative(value));
    }
    Ok(value)
}

fn area_from_str(text: &str) -> Result<f64, AreaError> {
    Ok(circle_area(parse_radius(text)?))
}

fn total_area(inputs: &[&str]) -> Result<f64, AreaError> {
    let mut sum = 0.0;
    for text in inputs {
        sum += area_from_str(text)?;
    }
    Ok(sum)
}

fn format_row(text: &str) -> Result<String, AreaError> {
    let radius = parse_radius(text)?;
    let mut row = String::new();
    write!(row, "r = {:<6} area = {}", radius, circle_area(radius))?;
    Ok(row)
}

fn report(inputs: &[&str]) -> Result<String, AreaError> {
    let mut out = String::new();
    for text in inputs {
        let row = format_row(text)?;
        writeln!(out, "{}", row)?;
    }
    let total = total_area(inputs)?;
    write!(out, "total area = {}", total)?;
    Ok(out)
}

fn main() -> Result<(), AreaError> {
    println!("{}", report(&["1.0", "2.0", " 0.5 "])?);
    let doubled = area_from_str("2")?;
    println!("circle_area(2.0) = {}", doubled);
    match parse_radius("-1.5") {
        Ok(radius) => println!("accepted radius {}", radius),
        Err(e) => println!("rejected input: {}", e),
    }
    Ok(())
}

