use std::env;
use std::fmt;
use std::io::{self, BufRead};
use std::process;

#[derive(Debug)]
enum Error {
    Parse(String),
    Io(io::Error),
    NoNumbers,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Parse(msg) => write!(f, "bad integer {msg}"),
            Error::Io(e) => write!(f, "input failure: {e}"),
            Error::NoNumbers => write!(f, "no numbers found in input"),
        }
    }
}

fn parse_numbers(spec: &str) -> Result<Vec<i32>, Error> {
    let mut numbers = Vec::new();
    for token in spec.split(|c: char| c == ',' || c.is_whitespace()) {
        if token.is_empty() {
            continue;
        }
        let value = token.parse::<i32>().map_err(|e| Error::Parse(format!("{token:?}: {e}")))?;
        numbers.push(value);
    }
    if numbers.is_empty() {
        return Err(Error::NoNumbers);
    }
    Ok(numbers)
}

fn remove_duplicates(numbers: Vec<i32>) -> Vec<i32> {
    let mut unique = Vec::new();
    for n in numbers {
        if !unique.contains(&n) {
            unique.push(n);
        }
    }
    unique
}

fn format_list(numbers: &[i32]) -> String {
    let parts: Vec<String> = numbers.iter().map(|n| n.to_string()).collect();
    format!("[{}]", parts.join(", "))
}

fn dedup_line(spec: &str) -> Result<String, Error> {
    let numbers = parse_numbers(spec)?;
    let original = numbers.len();
    let unique = remove_duplicates(numbers);
    let removed = original - unique.len();
    Ok(format!("{} (removed {removed})", format_list(&unique)))
}

fn run_args(args: &[String]) -> Result<(), Error> {
    for arg in args {
        let report = dedup_line(arg)?;
        println!("{report}");
    }
    Ok(())
}

fn run_stdin<R: BufRead>(reader: R) -> Result<(), Error> {
    for line in reader.lines() {
        let line = line.map_err(Error::Io)?;
        if line.trim().is_empty() {
            continue;
        }
        let report = dedup_line(&line)?;
        println!("{report}");
    }
    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let outcome = if args.is_empty() {
        run_stdin(io::stdin().lock())
    } else {
        run_args(&args)
    };
    if let Err(e) = outcome {
        eprintln!("error: {e}");
        process::exit(1);
    }
}

