use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Write};

const MIN: u32 = 1;
const MAX: u32 = 100;

#[derive(Debug)]
enum GameError {
    Syntax(String),
    NotANumber(String),
    OutOfRange(u32),
}

impl fmt::Display for GameError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GameError::Syntax(line) => write!(f, "expected \"target,guess\" but got {line:?}"),
            GameError::NotANumber(field) => write!(f, "{field:?} is not a number"),
            GameError::OutOfRange(n) => write!(f, "{n} is outside {MIN}..={MAX}"),
        }
    }
}

impl Error for GameError {}

fn check_guess(target: u32, guess: u32) -> &'static str {
    if guess < target {
        "Too low"
    } else if guess > target {
        "Too high"
    } else {
        "Correct"
    }
}

fn parse_bounded(field: &str) -> Result<u32, GameError> {
    let text = field.trim();
    let value: u32 = match text.parse().map_err(|_| GameError::NotANumber(text.to_string())) { Ok(v) => v, Err(e) => return Err(e.into()) };
    if value < MIN || value > MAX {
        return Err(GameError::OutOfRange(value));
    }
    Ok(value)
}

fn parse_round(line: &str) -> Result<(u32, u32), GameError> {
    let (left, right) = match line
        .split_once(',')
        .ok_or_else(|| GameError::Syntax(line.to_string())) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let target = match parse_bounded(left) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let guess = match parse_bounded(right) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok((target, guess))
}

fn describe_round(line: &str) -> Result<String, GameError> {
    let (target, guess) = match parse_round(line) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(format!("target {target}, guess {guess} -> {}", check_guess(target, guess)))
}

fn report_round(line: &str, out: &mut impl Write) -> io::Result<bool> {
    match describe_round(line) {
        Ok(text) => {
            let correct = text.ends_with("Correct");
            match writeln!(out, "{text}") { Ok(v) => v, Err(e) => return Err(e.into()) };
            Ok(correct)
        }
        Err(err) => {
            match writeln!(out, "skipped: {err}") { Ok(v) => v, Err(e) => return Err(e.into()) };
            Ok(false)
        }
    }
}

fn run(input: impl BufRead, out: &mut impl Write) -> Result<(), Box<dyn Error>> {
    let mut rounds = 0u32;
    let mut correct = 0u32;
    for line in input.lines() {
        let line = match line { Ok(v) => v, Err(e) => return Err(e.into()) };
        if line.trim().is_empty() {
            continue;
        }
        rounds += 1;
        if match report_round(&line, out) { Ok(v) => v, Err(e) => return Err(e.into()) } {
            correct += 1;
        }
    }
    match writeln!(out, "{correct}/{rounds} rounds guessed correctly") { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let stdin = io::stdin();
    let mut out = io::stdout().lock();
    match run(stdin.lock(), &mut out) { Ok(v) => v, Err(e) => return Err(e.into()) };
    match out.flush() { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(())
}

