type Result<T> = std::result::Result<T, String>;

#[derive(Debug)]
struct Record {
    id: u32,
    name: String,
    active: bool,
    score: f64,
}

fn parse_csv_line(line: &str) -> Vec<String> {
    line.split(',').map(|field| field.trim().to_string()).collect()
}

fn field<'a>(fields: &'a [String], index: usize, name: &str) -> Result<&'a str> {
    let value = fields
        .get(index)
        .ok_or_else(|| format!("missing field `{}`", name))?;
    Ok(value.as_str())
}

fn parse_bool(text: &str) -> Result<bool> {
    match text {
        "true" => Ok(true),
        "false" => Ok(false),
        other => Err(format!("`{}` is not a boolean", other)),
    }
}

fn parse_record(line: &str) -> Result<Record> {
    let fields = parse_csv_line(line);
    let id_text = field(&fields, 0, "id")?;
    let id = id_text
        .parse::<u32>()
        .map_err(|e| format!("id `{}`: {}", id_text, e))?;
    let name = field(&fields, 1, "name")?.to_string();
    let active_text = field(&fields, 2, "active")?;
    let active = parse_bool(active_text)?;
    let score_text = field(&fields, 3, "score")?;
    let score = score_text
        .parse::<f64>()
        .map_err(|e| format!("score `{}`: {}", score_text, e))?;
    Ok(Record { id, name, active, score })
}

fn check_header(header: &str) -> Result<()> {
    let fields = parse_csv_line(header);
    for (index, expected) in ["id", "name", "active", "score"].iter().enumerate() {
        let got = field(&fields, index, expected)?;
        if got != *expected {
            return Err(format!("header column {} is `{}`, expected `{}`", index, got, expected));
        }
    }
    Ok(())
}

fn parse_records(text: &str) -> Result<Vec<Record>> {
    let mut lines = text.lines().filter(|line| !line.trim().is_empty());
    let header = lines.next().ok_or_else(|| "input is empty".to_string())?;
    check_header(header)?;
    let mut records = Vec::new();
    for (offset, line) in lines.enumerate() {
        let record = parse_record(line).map_err(|e| format!("line {}: {}", offset + 2, e))?;
        records.push(record);
    }
    Ok(records)
}

