use std::env;

fn is_leap_year(year: u16) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

fn parse_year(text: &str) -> Result<u16, String> {
    let value: u32 = text
        .trim()
        .parse()
        .map_err(|e| format!("bad year {text:?}: {e}"))?;
    if value == 0 || value > 9999 {
        return Err(format!("year {value} outside supported range 1..=9999"));
    }
    Ok(value as u16)
}

fn parse_month(text: &str) -> Result<u8, String> {
    let value: u8 = text
        .trim()
        .parse()
        .map_err(|e| format!("bad month {text:?}: {e}"))?;
    if !(1..=12).contains(&value) {
        return Err(format!("month {value} outside 1..=12"));
    }
    Ok(value)
}

fn days_in_month(year: u16, month: u8) -> Result<u8, String> {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Ok(31),
        4 | 6 | 9 | 11 => Ok(30),
        2 => Ok(if is_leap_year(year) { 29 } else { 28 }),
        other => Err(format!("month {other} outside 1..=12")),
    }
}

fn parse_date(text: &str) -> Result<(u16, u8, u8), String> {
    let mut parts = text.trim().split('-');
    let year_txt = parts.next().ok_or_else(|| format!("no year in {text:?}"))?;
    let year = parse_year(year_txt)?;
    let month_txt = parts.next().ok_or_else(|| format!("no month in {text:?}"))?;
    let month = parse_month(month_txt)?;
    let day_txt = parts.next().ok_or_else(|| format!("no day in {text:?}"))?;
    let day: u8 = day_txt
        .trim()
        .parse()
        .map_err(|e| format!("bad day {day_txt:?}: {e}"))?;
    let limit = days_in_month(year, month)?;
    if day == 0 || day > limit {
        return Err(format!("day {day} outside 1..={limit} for {year}-{month:02}"));
    }
    Ok((year, month, day))
}

fn day_of_year(text: &str) -> Result<u16, String> {
    let (year, month, day) = parse_date(text)?;
    let mut total = u16::from(day);
    for earlier in 1..month {
        total += u16::from(days_in_month(year, earlier)?);
    }
    Ok(total)
}

fn describe_year(text: &str) -> Result<String, String> {
    let year = parse_year(text)?;
    let leap = is_leap_year(year);
    let length = if leap { 366 } else { 365 };
    Ok(format!("{year}: leap={leap}, {length} days"))
}

fn report(text: &str) -> Result<String, String> {
    let (year, month, day) = parse_date(text)?;
    let length = days_in_month(year, month)?;
    let ordinal = day_of_year(text)?;
    Ok(format!(
        "{year}-{month:02}-{day:02}: day {ordinal} of the year, month has {length} days, leap={}",
        is_leap_year(year)
    ))
}

fn main() -> Result<(), String> {
    let args: Vec<String> = env::args().skip(1).collect();
    let inputs = if args.is_empty() {
        vec![
            "2000".to_string(),
            "1900".to_string(),
            "2024".to_string(),
            "2024-02-29".to_string(),
        ]
    } else {
        args
    };
    for input in &inputs {
        if input.contains('-') {
            println!("{}", report(input)?);
        } else {
            println!("{}", describe_year(input)?);
        }
    }
    Ok(())
}

