use std::env;
use std::fmt::{self, Write as FmtWrite};

const MAX_LIMIT: u32 = 10_000;

#[derive(Debug)]
enum AppError {
    BadNumber(String, std::num::ParseIntError),
    TooLarge(u32),
    OutOfRange(u32, u32),
    Format(fmt::Error),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::BadNumber(text, cause) => write!(f, "bad number {:?}: {}", text, cause),
            AppError::TooLarge(n) => write!(f, "limit {} exceeds maximum of {}", n, MAX_LIMIT),
            AppError::OutOfRange(pos, n) => write!(f, "term #{} is outside 1..={}", pos, n),
            AppError::Format(cause) => write!(f, "could not build report: {}", cause),
        }
    }
}

fn parse_limit(text: &str) -> Result<u32, AppError> {
    let trimmed = text.trim();
    let n: u32 = trimmed
        .parse()
        .map_err(|cause| AppError::BadNumber(trimmed.to_string(), cause))?;
    if n > MAX_LIMIT {
        return Err(AppError::TooLarge(n));
    }
    Ok(n)
}

fn term(i: u32) -> String {
    let fizz = i % 3 == 0;
    let buzz = i % 5 == 0;
    if fizz && buzz {
        "FizzBuzz".to_string()
    } else if fizz {
        "Fizz".to_string()
    } else if buzz {
        "Buzz".to_string()
    } else {
        i.to_string()
    }
}

fn fizzbuzz(n: u32) -> Vec<String> {
    (1..=n).map(term).collect()
}

fn term_at(n: u32, text: &str) -> Result<String, AppError> {
    let position = parse_limit(text)?;
    let index = position
        .checked_sub(1)
        .ok_or(AppError::OutOfRange(position, n))?;
    let terms = fizzbuzz(n);
    let value = terms
        .get(index as usize)
        .ok_or(AppError::OutOfRange(position, n))?;
    Ok(value.clone())
}

fn report(n: u32) -> Result<String, AppError> {
    let terms = fizzbuzz(n);
    let mut out = String::new();
    writeln!(out, "FizzBuzz for 1..={}", n).map_err(AppError::Format)?;
    for row in terms.chunks(5) {
        writeln!(out, "  {}", row.join(" ")).map_err(AppError::Format)?;
    }
    let words = terms.iter().filter(|t| !t.chars().all(|c| c.is_ascii_digit()));
    let fizzbuzzes = words.clone().filter(|t| t.as_str() == "FizzBuzz").count();
    writeln!(out, "words: {}, of which FizzBuzz: {}", words.count(), fizzbuzzes)
        .map_err(AppError::Format)?;
    Ok(out)
}

fn main() -> Result<(), AppError> {
    let args: Vec<String> = env::args().skip(1).collect();
    let limit = parse_limit(args.first().map(String::as_str).unwrap_or("15"))?;
    print!("{}", report(limit)?);
    if let Some(raw) = args.get(1) {
        println!("term #{} is {}", raw.trim(), term_at(limit, raw)?);
    }
    Ok(())
}

