fn parse_int(s: &str) -> Option<i32> {
    let cleaned = s.trim().replace('_', "");
    cleaned.parse::<i32>().ok()
}

fn parse_field(name: &str, text: &str) -> Result<i32, String> {
    parse_int(text).ok_or_else(|| format!("{}: {:?} is not a valid i32", name, text.trim()))
}

fn parse_pair(s: &str) -> Result<(i32, i32), String> {
    let (low_text, high_text) = s
        .split_once(',')
        .ok_or_else(|| format!("{:?} is not a comma-separated pair", s))?;
    let low = parse_field("low bound", low_text)?;
    let high = parse_field("high bound", high_text)?;
    Ok((low, high))
}

fn parse_list(s: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for token in s.split(',') {
        values.push(parse_field("item", token)?);
    }
    Ok(values)
}

fn sum_checked(values: &[i32]) -> Result<i32, String> {
    let mut total: i32 = 0;
    for value in values {
        total = total
            .checked_add(*value)
            .ok_or_else(|| String::from("sum overflows i32"))?;
    }
    Ok(total)
}

fn parse_sum(s: &str) -> Result<i32, String> {
    let values = parse_list(s)?;
    sum_checked(&values)
}

fn parse_average(s: &str) -> Result<i32, String> {
    let values = parse_list(s)?;
    let total = sum_checked(&values)?;
    let count = values.len() as i32;
    total
        .checked_div(count)
        .ok_or_else(|| String::from("cannot average an empty list"))
}

fn parse_largest(s: &str) -> Result<i32, String> {
    let values = parse_list(s)?;
    values
        .into_iter()
        .max()
        .ok_or_else(|| String::from("cannot take the largest of an empty list"))
}

fn range_span(s: &str) -> Result<i32, String> {
    let (low, high) = parse_pair(s)?;
    high.checked_sub(low)
        .ok_or_else(|| String::from("span overflows i32"))
}

fn parse_setting(line: &str) -> Result<(&str, i32), String> {
    let (name, text) = line
        .split_once('=')
        .ok_or_else(|| format!("{:?} is missing '='", line))?;
    let value = parse_field(name.trim(), text)?;
    Ok((name.trim(), value))
}

fn describe_setting(line: &str) -> Result<String, String> {
    let (name, value) = parse_setting(line)?;
    Ok(format!("{} -> {}", name, value))
}

fn show(label: &str, result: Result<i32, String>) {
    match result {
        Ok(value) => println!("{}: {}", label, value),
        Err(message) => println!("{}: {}", label, message),
    }
}

fn main() {
    for text in ["123", "abc", " -42 ", "1_000", "99999999999"] {
        println!("parse_int({:?}) = {:?}", text, parse_int(text));
    }
    show("sum of 1,2,3", parse_sum("1,2,3"));
    show("sum of 1,x,3", parse_sum("1,x,3"));
    show("average of 4,8,15", parse_average("4,8,15"));
    show("largest of 7,2,9", parse_largest("7,2,9"));
    show("span of 3,10", range_span("3,10"));
    show("span of 3;10", range_span("3;10"));
    for line in ["width = 80", "height=24", "depth"] {
        match describe_setting(line) {
            Ok(text) => println!("setting {}", text),
            Err(message) => println!("bad setting: {}", message),
        }
    }
}

