use std::env;

fn fibonacci_sequence(n: u32) -> Vec<u64> {
    let mut out = Vec::with_capacity(n as usize);
    let (mut current, mut next) = (0u64, 1u64);
    for _ in 0..n {
        out.push(current);
        let following = current.saturating_add(next);
        current = next;
        next = following;
    }
    out
}

fn parse_count(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    let value: u32 = trimmed
        .parse()
        .map_err(|e| format!("bad term count {:?}: {}", trimmed, e))?;
    if value > 93 {
        return Err(format!("Fibonacci term {} does not fit in u64", value));
    }
    Ok(value)
}

fn parse_limit(text: &str) -> Result<u64, String> {
    let trimmed = text.trim();
    let value: u64 = trimmed
        .parse()
        .map_err(|e| format!("bad limit {:?}: {}", trimmed, e))?;
    if value == 0 {
        return Err("the limit must be positive".to_string());
    }
    Ok(value)
}

fn parse_spec(spec: &str) -> Result<(u32, Option<u64>), String> {
    match spec.split_once(':') {
        Some((head, tail)) => {
            let count = parse_count(head)?;
            let limit = parse_limit(tail)?;
            Ok((count, Some(limit)))
        }
        None => Ok((parse_count(spec)?, None)),
    }
}

fn checked_sum(values: &[u64]) -> Result<u64, String> {
    let mut total = 0u64;
    for value in values {
        total = total
            .checked_add(*value)
            .ok_or_else(|| format!("the running sum overflows u64 at {}", value))?;
    }
    Ok(total)
}

fn largest_below(limit: u64) -> u64 {
    let mut best = 0u64;
    for value in fibonacci_sequence(94) {
        if value >= limit {
            break;
        }
        best = value;
    }
    best
}

fn format_report(spec: &str) -> Result<String, String> {
    let (count, limit) = parse_spec(spec)?;
    let extended = fibonacci_sequence(count + 1);
    let terms = &extended[..count as usize];
    let total = checked_sum(terms)?;
    let mut out = format!("first {} Fibonacci numbers: {:?}\n", count, terms);
    out.push_str(&format!("sum: {}\n", total));
    out.push_str(&format!("next term: {}\n", extended[count as usize]));
    if let Some(limit) = limit {
        out.push_str(&format!(
            "largest Fibonacci number below {}: {}\n",
            limit,
            largest_below(limit)
        ));
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    let spec = env::args()
        .nth(1)
        .ok_or_else(|| "usage: fibonacci <count>[:limit]".to_string())?;
    print!("{}", format_report(&spec)?);
    Ok(())
}

