fn is_valid_email(email: &str) -> bool {
    split_address(email).is_some()
}

/// Splits an address at its '@' provided a '.' follows somewhere in the domain,
/// which is exactly the "very basic" rule: '@' present, '.' present, '@' first.
fn split_address(email: &str) -> Option<(&str, &str)> {
    let (local, domain) = match email.split_once('@') {
        Some(v) => v,
        None => return None,
    };
    if domain.contains('.') {
        Some((local, domain))
    } else {
        None
    }
}

fn domain_of(email: &str) -> Option<&str> {
    let (_, domain) = match split_address(email) {
        Some(v) => v,
        None => return None,
    };
    Some(domain)
}

/// The label after the final '.', when there is one; `None` for "a@b.".
fn tld_of(email: &str) -> Option<&str> {
    let domain = match domain_of(email) {
        Some(v) => v,
        None => return None,
    };
    let last_dot = match domain.rfind('.') {
        Some(v) => v,
        None => return None,
    };
    let tld = &domain[last_dot + 1..];
    if tld.is_empty() {
        None
    } else {
        Some(tld)
    }
}

struct Contact {
    name: String,
    email: String,
    local: String,
    domain: String,
}

fn parse_contact(line: &str) -> Result<Contact, String> {
    let (name, addr) = match line
        .split_once(',')
        .ok_or_else(|| format!("no ',' separating name and address in {:?}", line))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let name = name.trim();
    let addr = addr.trim();
    let (local, domain) =
        match split_address(addr).ok_or_else(|| format!("not a valid email: {:?}", addr)) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    if name.is_empty() {
        return Err(format!("empty name in {:?}", line));
    }
    Ok(Contact {
        name: name.to_string(),
        email: addr.to_string(),
        local: local.to_string(),
        domain: domain.to_string(),
    })
}

fn format_contact(line: &str) -> Result<String, String> {
    let contact = match parse_contact(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let tld = match tld_of(&contact.email)
        .ok_or_else(|| format!("no top level domain in {:?}", contact.domain))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(format!(
        "{} <{}>  local={}  domain={}  tld={}",
        contact.name, contact.email, contact.local, contact.domain, tld
    ))
}

fn report(lines: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    for line in lines {
        let formatted = match format_contact(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        out.push_str(&formatted);
        out.push('\n');
    }
    Ok(out)
}

