use rand::Rng;
use std::env;
use std::error::Error;
use std::fmt::{self, Write as _};
use std::num::{NonZeroU32, ParseIntError};

/// Simulate one throw of a standard six-sided die.
fn roll_die() -> u8 {
    rand::thread_rng().gen_range(1..=6)
}

#[derive(Debug)]
enum ConfigError {
    NotANumber { raw: String, source: ParseIntError },
    Zero,
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::NotANumber { raw, source } => {
                write!(f, "`{raw}` is not a roll count: {source}")
            }
            ConfigError::Zero => f.write_str("the number of rolls must be at least 1"),
        }
    }
}

impl Error for ConfigError {}

fn parse_count(args: &[String]) -> Result<NonZeroU32, ConfigError> {
    let raw = args.first().map(String::as_str).unwrap_or("1000");
    let count: u32 = raw.parse().map_err(|source| ConfigError::NotANumber {
        raw: raw.to_owned(),
        source,
    })?;
    NonZeroU32::new(count).ok_or(ConfigError::Zero)
}

fn tally(rolls: NonZeroU32) -> [u32; 6] {
    let mut counts = [0u32; 6];
    for _ in 0..rolls.get() {
        counts[usize::from(roll_die()) - 1] += 1;
    }
    counts
}

fn mean(counts: &[u32; 6], total: NonZeroU32) -> f64 {
    let pips: u32 = counts
        .iter()
        .enumerate()
        .map(|(index, hits)| (index as u32 + 1) * hits)
        .sum();
    f64::from(pips) / f64::from(total.get())
}

fn most_frequent(counts: &[u32; 6]) -> (u8, u32) {
    let mut best = (1u8, counts[0]);
    for (index, hits) in counts.iter().enumerate().skip(1) {
        if *hits > best.1 {
            best = (index as u8 + 1, *hits);
        }
    }
    best
}

fn fairness_verdict(counts: &[u32; 6], total: NonZeroU32) -> &'static str {
    let expected = f64::from(total.get()) / 6.0;
    let worst = counts
        .iter()
        .map(|hits| (f64::from(*hits) - expected).abs())
        .fold(0.0_f64, f64::max);
    if worst <= 0.1 * expected {
        "plausibly fair"
    } else {
        "suspicious"
    }
}

fn render_report(counts: &[u32; 6], total: NonZeroU32, average: f64) -> Result<String, fmt::Error> {
    let total = total.get();
    let mut out = String::new();
    writeln!(out, "{total} rolls of a six-sided die")?;
    writeln!(out, "face  count   share")?;
    for (index, hits) in counts.iter().enumerate() {
        let share = 100.0 * f64::from(*hits) / f64::from(total);
        writeln!(out, "{:>4} {hits:>6} {share:>6.2}%", index + 1)?;
    }
    writeln!(out, "average pips: {average:.3} (expected 3.500)")?;
    Ok(out)
}

fn append_summary(out: &mut String, face: u8, hits: u32, verdict: &str) -> Result<(), fmt::Error> {
    writeln!(out, "most frequent face: {face} ({hits} times)")?;
    writeln!(out, "verdict: {verdict}")
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().skip(1).collect();
    let rolls = parse_count(&args)?;
    let counts = tally(rolls);
    let (face, hits) = most_frequent(&counts);
    let mut report = render_report(&counts, rolls, mean(&counts, rolls))?;
    append_summary(&mut report, face, hits, fairness_verdict(&counts, rolls))?;
    print!("{report}");
    Ok(())
}

