/// Returns the median of the given values, sorting the slice in place.
fn calculate_median(numbers: &mut [f64]) -> Option<f64> {
    if numbers.is_empty() {
        return None;
    }
    numbers.sort_by(|a, b| a.total_cmp(b));
    let mid = numbers.len() / 2;
    if numbers.len() % 2 == 1 {
        Some(numbers[mid])
    } else {
        Some((numbers[mid - 1] + numbers[mid]) / 2.0)
    }
}

/// Parses whitespace- or comma-separated numbers, rejecting anything unusable.
fn parse_values(line: &str) -> Result<Vec<f64>, String> {
    let mut values = Vec::new();
    for token in line.split(|c: char| c == ',' || c.is_whitespace()) {
        if token.is_empty() {
            continue;
        }
        let value: f64 = token
            .parse()
            .map_err(|_| format!("`{token}` is not a number"))?;
        if value.is_nan() {
            return Err("NaN cannot be ordered".to_string());
        }
        values.push(value);
    }
    Ok(values)
}

/// Lower quartile, median and upper quartile of the values.
fn quartiles(numbers: &mut [f64]) -> Result<(f64, f64, f64), String> {
    let q2 = calculate_median(numbers).ok_or_else(|| "empty data set".to_string())?;
    let len = numbers.len();
    let (lower, upper) = numbers.split_at_mut(len / 2);
    let q1 = calculate_median(lower).ok_or_else(|| "quartiles need two values".to_string())?;
    let q3 = calculate_median(&mut upper[len % 2..])
        .ok_or_else(|| "quartiles need two values".to_string())?;
    Ok((q1, q2, q3))
}

/// Distance between the smallest and the largest value of a sorted slice.
fn range_width(sorted: &[f64]) -> Result<f64, String> {
    let lo = sorted.first().ok_or_else(|| "empty data set".to_string())?;
    let hi = sorted.last().ok_or_else(|| "empty data set".to_string())?;
    Ok(hi - lo)
}

/// Builds a one-line report for a textual list of numbers.
fn summarize(line: &str) -> Result<String, String> {
    let mut values = parse_values(line)?;
    let (q1, q2, q3) = quartiles(&mut values)?;
    let spread = range_width(&values)?;
    Ok(format!(
        "n={} median={q2} iqr={} range={spread}",
        values.len(),
        q3 - q1
    ))
}

fn main() {
    println!("{:?}", calculate_median(&mut [1.0, 5.0, 2.0]));
    println!("{:?}", calculate_median(&mut [1.0, 2.0, 3.0, 4.0]));
    println!("{:?}", calculate_median(&mut []));

    let inputs = ["1 5 2", "1, 2, 3, 4", "7.5 2.25 9 4 -3", "3 x 4", "5", ""];
    for input in inputs {
        match summarize(input) {
            Ok(report) => println!("[{input}] -> {report}"),
            Err(error) => println!("[{input}] -> error: {error}"),
        }
    }
}

