use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum SpecError {
    MissingSeparator(String),
    BadNumber(ParseFloatError),
    NotPositive(f64),
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SpecError::MissingSeparator(s) => write!(f, "no 'x' separator in {:?}", s),
            SpecError::BadNumber(e) => write!(f, "bad number: {}", e),
            SpecError::NotPositive(v) => write!(f, "dimension must be positive, got {}", v),
        }
    }
}

fn rectangle_area(width: f64, height: f64) -> f64 {
    width * height
}

fn parse_dimension(text: &str) -> Result<f64, SpecError> {
    let value: f64 = text.trim().parse().map_err(SpecError::BadNumber)?;
    if value <= 0.0 {
        return Err(SpecError::NotPositive(value));
    }
    Ok(value)
}

fn parse_spec(spec: &str) -> Result<(f64, f64), SpecError> {
    let (left, right) = spec
        .split_once('x')
        .ok_or_else(|| SpecError::MissingSeparator(spec.to_string()))?;
    let width = parse_dimension(left)?;
    let height = parse_dimension(right)?;
    Ok((width, height))
}

fn area_of_spec(spec: &str) -> Result<f64, SpecError> {
    let (width, height) = parse_spec(spec)?;
    Ok(rectangle_area(width, height))
}

fn describe(spec: &str) -> Result<String, SpecError> {
    let (width, height) = parse_spec(spec)?;
    let area = rectangle_area(width, height);
    Ok(format!("{:.2} x {:.2} -> {:.2}", width, height, area))
}

fn total_area(specs: &[&str]) -> Result<f64, SpecError> {
    let mut total = 0.0;
    for spec in specs {
        total += area_of_spec(spec)?;
    }
    Ok(total)
}

fn report(specs: &[&str]) -> Result<String, SpecError> {
    let mut out = String::new();
    for spec in specs {
        out.push_str(&describe(spec)?);
        out.push('\n');
    }
    Ok(out)
}

fn main() -> Result<(), SpecError> {
    let specs = ["5.0 x 10.0", "2.5 x 4.0", "3 x 3"];
