const MONTHS: [&str; 12] = [
    "January", "February", "March", "April", "May", "June", "July", "August", "September",
    "October", "November", "December",
];

struct Record {
    id: String,
    date: String,
    note: String,
}

fn parse_block(part: &str, len: usize, label: &str) -> Result<u32, String> {
    if part.len() != len || !part.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("{label} {part:?} must be exactly {len} digits"));
    }
    let value = part.parse::<u32>().map_err(|e| format!("bad {label}: {e}"))?;
    Ok(value)
}

fn parse_date_parts(s: &str) -> Result<(u32, u32, u32), String> {
    let mut fields = s.split('-');
    let year_field = fields.next().ok_or_else(|| format!("empty date {s:?}"))?;
    let month_field = fields.next().ok_or_else(|| format!("no month in {s:?}"))?;
    let day_field = fields.next().ok_or_else(|| format!("no day in {s:?}"))?;
    if fields.next().is_some() {
        return Err(format!("too many dash-separated fields in {s:?}"));
    }
    let year = parse_block(year_field, 4, "year")?;
    let month = parse_block(month_field, 2, "month")?;
    let day = parse_block(day_field, 2, "day")?;
    Ok((year, month, day))
}

fn is_valid_date_format(s: &str) -> bool {
    parse_date_parts(s).is_ok()
}

fn month_name(month: u32) -> Result<&'static str, String> {
    let index = (month as usize)
        .checked_sub(1)
        .ok_or_else(|| "month 00 has no name".to_string())?;
    let name = MONTHS.get(index).ok_or_else(|| format!("no month number {month}"))?;
    Ok(name)
}

fn human_date(s: &str) -> Result<String, String> {
    let (year, month, day) = parse_date_parts(s)?;
    let name = month_name(month)?;
    Ok(format!("{name} {day}, {year}"))
}

fn parse_record(line: &str) -> Result<Record, String> {
    let (id, rest) = line.split_once(',').ok_or_else(|| format!("no date field in {line:?}"))?;
    let (date, note) = rest.split_once(',').ok_or_else(|| format!("no note field in {line:?}"))?;
    let date = date.trim();
    if !is_valid_date_format(date) {
        return Err(format!("date {date:?} is not in YYYY-MM-DD format"));
    }
    Ok(Record {
        id: id.trim().to_string(),
        date: date.to_string(),
        note: note.trim().to_string(),
    })
}

fn summarize(lines: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    for line in lines {
        let record = parse_record(line)?;
        let pretty = human_date(&record.date)?;
        out.push_str(&format!("[{}] {} - {}\n", record.id, record.date, record.note));
        out.push_str(&format!("  scheduled for {pretty}\n"));
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    let good = ["A1, 2023-01-15, kickoff", "A2, 2023-11-20, review"];
    print!("{}", summarize(&good)?);
    for candidate in ["2023-01-15", "2023/01/15", "2023-13-01", "23-01-15", "2023-1-15"] {
        println!("{candidate:>12} -> {}", is_valid_date_format(candidate));
    }
    match summarize(&["B1, 2023-02-30-01, oops"]) {
        Ok(text) => print!("{text}"),
        Err(err) => println!("rejected: {err}"),
    }
    Ok(())
}

