use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Move {
    Rock,
    Paper,
    Scissors,
}

#[derive(Debug)]
enum GameError {
    UnknownChoice(String),
    MalformedRound(String),
}

impl fmt::Display for GameError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GameError::UnknownChoice(c) => write!(f, "unknown choice: {c:?}"),
            GameError::MalformedRound(l) => write!(f, "malformed round: {l:?}"),
        }
    }
}

fn parse_move(text: &str) -> Result<Move, GameError> {
    match text.trim().to_lowercase().as_str() {
        "rock" => Ok(Move::Rock),
        "paper" => Ok(Move::Paper),
        "scissors" => Ok(Move::Scissors),
        other => Err(GameError::UnknownChoice(other.to_string())),
    }
}

fn beats(attacker: Move, defender: Move) -> bool {
    matches!(
        (attacker, defender),
        (Move::Rock, Move::Scissors) | (Move::Paper, Move::Rock) | (Move::Scissors, Move::Paper)
    )
}

fn verdict(p1: Move, p2: Move) -> &'static str {
    if p1 == p2 {
        "It's a tie"
    } else if beats(p1, p2) {
        "Player 1 wins"
    } else {
        "Player 2 wins"
    }
}

fn try_rps_winner(p1_choice: &str, p2_choice: &str) -> Result<&'static str, GameError> {
    let p1 = parse_move(p1_choice)?;
    let p2 = parse_move(p2_choice)?;
    Ok(verdict(p1, p2))
}

fn rps_winner(p1_choice: &str, p2_choice: &str) -> &'static str {
    try_rps_winner(p1_choice, p2_choice).expect("choices must be rock, paper or scissors")
}

fn parse_round(line: &str) -> Result<(Move, Move), GameError> {
    let (left, right) = line
        .split_once(" vs ")
        .ok_or_else(|| GameError::MalformedRound(line.to_string()))?;
    let p1 = parse_move(left)?;
    Ok((p1, parse_move(right)?))
}

fn play_series(lines: &[&str]) -> Result<(u32, u32, u32), GameError> {
    let mut score = (0, 0, 0);
    for line in lines {
        let (p1, p2) = parse_round(line)?;
        if p1 == p2 {
            score.2 += 1;
        } else if beats(p1, p2) {
            score.0 += 1;
        } else {
            score.1 += 1;
        }
    }
    Ok(score)
}

fn series_winner(lines: &[&str]) -> Result<&'static str, GameError> {
    let score = play_series(lines)?;
    Ok(verdict_from_counts(score.0, score.1))
}

fn verdict_from_counts(p1_wins: u32, p2_wins: u32) -> &'static str {
    match p1_wins.cmp(&p2_wins) {
        std::cmp::Ordering::Greater => "Player 1 wins",
        std::cmp::Ordering::Less => "Player 2 wins",
        std::cmp::Ordering::Equal => "It's a tie",
    }
}

fn main() -> Result<(), GameError> {
    println!("{}", rps_winner("rock", "scissors"));
    println!("{}", rps_winner("paper", "rock"));

    let rounds = [
        "rock vs scissors",
        "paper vs scissors",
        "Rock vs paper",
        "scissors vs scissors",
        "paper vs rock",
    ];
    let (p1_wins, p2_wins, ties) = play_series(&rounds)?;
    println!("series: {p1_wins} - {p2_wins} ({ties} tied)");
    println!("overall: {}", series_winner(&rounds)?);
    Ok(())
}

