use std::collections::HashMap;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ParamError {
    Missing(String),
    BadEncoding(String),
    BadNumber(ParseIntError),
}

impl fmt::Display for ParamError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParamError::Missing(k) => write!(f, "missing parameter `{}`", k),
            ParamError::BadEncoding(s) => write!(f, "bad percent-encoding in `{}`", s),
            ParamError::BadNumber(e) => write!(f, "not a number: {}", e),
        }
    }
}

impl From<ParseIntError> for ParamError {
    fn from(e: ParseIntError) -> Self {
        ParamError::BadNumber(e)
    }
}

fn parse_url_params(query_string: &str) -> std::collections::HashMap<String, String> {
    query_string
        .split('&')
        .filter(|pair| !pair.is_empty())
        .map(|pair| match pair.split_once('=') {
            Some((key, value)) => (key.to_string(), value.to_string()),
            None => (pair.to_string(), String::new()),
        })
        .collect()
}

fn percent_decode(text: &str) -> Result<String, ParamError> {
    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'%' => {
                let hex = text
                    .get(i + 1..i + 3)
                    .ok_or_else(|| ParamError::BadEncoding(text.to_string()))?;
                let byte = u8::from_str_radix(hex, 16)
                    .map_err(|_| ParamError::BadEncoding(text.to_string()))?;
                out.push(byte);
                i += 3;
            }
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            other => {
                out.push(other);
                i += 1;
            }
        }
    }
    String::from_utf8(out).map_err(|_| ParamError::BadEncoding(text.to_string()))
}

fn decoded_params(query_string: &str) -> Result<HashMap<String, String>, ParamError> {
    let mut decoded = HashMap::new();
    for (key, value) in parse_url_params(query_string) {
        let clean_key = percent_decode(&key)?;
        let clean_value = percent_decode(&value)?;
        decoded.insert(clean_key, clean_value);
    }
    Ok(decoded)
}

fn get_str<'a>(params: &'a HashMap<String, String>, key: &str) -> Result<&'a str, ParamError> {
    params
        .get(key)
        .map(String::as_str)
        .ok_or_else(|| ParamError::Missing(key.to_string()))
}

fn get_int(params: &HashMap<String, String>, key: &str) -> Result<i64, ParamError> {
    let raw = get_str(params, key)?;
    Ok(raw.trim().parse::<i64>()?)
}

fn describe_user(query_string: &str) -> Result<String, ParamError> {
    let params = decoded_params(query_string)?;
    let name = get_str(&params, "name")?;
    let age = get_int(&params, "age")?;
    Ok(format!("{} is {} years old", name, age))
}

fn format_params(params: &HashMap<String, String>) -> String {
    let mut entries: Vec<String> = params
        .iter()
        .map(|(k, v)| format!("{:?}: {:?}", k, v))
        .collect();
    entries.sort();
    format!("{{ {} }}", entries.join(", "))
}

fn main() -> Result<(), ParamError> {
    println!("{}", format_params(&parse_url_params("name=Alice&age=30")));
    println!("{}", format_params(&parse_url_params("")));
    println!("{}", describe_user("name=Jane+Doe&age=41&city=Bonn")?);
    match describe_user("name=Bob") {
        Ok(text) => println!("{}", text),
        Err(err) => println!("error: {}", err),
    }
    Ok(())
}

