fn is_one_char_different(s1: &str, s2: &str) -> bool {
    if s1.len() != s2.len() {
        return false;
    }

    let mut diff_count = 0;
    let mut s1_chars = s1.chars();
    let mut s2_chars = s2.chars();

    loop {
        let c1_opt = s1_chars.next();
        let c2_opt = s2_chars.next();

        let c1 = match c1_opt {
            Some(c) => c,
            None => break, // End of string
        };

        let c2 = match c2_opt {
            Some(c) => c,
            None => break, // Should not happen if lengths are equal
        };

        if c1 != c2 {
            diff_count += 1;
        }

        if diff_count > 1 {
            return false;
        }
    }

    diff_count == 1
}

