use std::fmt;

#[derive(Debug)]
enum TxError {
    UnknownKind(String),
    InvalidAmount(f64),
    InsufficientFunds { balance: f64, requested: f64 },
    MalformedLine(String),
}

impl fmt::Display for TxError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            TxError::UnknownKind(k) => write!(f, "unknown transaction kind '{}'", k),
            TxError::InvalidAmount(a) => write!(f, "invalid amount {}", a),
            TxError::InsufficientFunds { balance, requested } => {
                write!(f, "insufficient funds: have {:.2}, requested {:.2}", balance, requested)
            }
            TxError::MalformedLine(l) => write!(f, "malformed ledger line '{}'", l),
        }
    }
}

enum Kind {
    Deposit,
    Withdraw,
}

fn parse_kind(kind: &str) -> Result<Kind, TxError> {
    match kind {
        "deposit" => Ok(Kind::Deposit),
        "withdraw" => Ok(Kind::Withdraw),
        other => Err(TxError::UnknownKind(other.to_string())),
    }
}

fn validate_amount(amount: f64) -> Result<f64, TxError> {
    if amount.is_finite() && amount > 0.0 {
        Ok(amount)
    } else {
        Err(TxError::InvalidAmount(amount))
    }
}

fn deposit(balance: f64, amount: f64) -> Result<f64, TxError> {
    Ok(balance + validate_amount(amount)?)
}

fn withdraw(balance: f64, amount: f64) -> Result<f64, TxError> {
    let requested = validate_amount(amount)?;
    if requested > balance {
        return Err(TxError::InsufficientFunds { balance, requested });
    }
    Ok(balance - requested)
}

fn apply(balance: f64, tx: (&str, f64)) -> Result<f64, TxError> {
    match parse_kind(tx.0)? {
        Kind::Deposit => deposit(balance, tx.1),
        Kind::Withdraw => withdraw(balance, tx.1),
    }
}

fn process_transactions(initial_balance: f64, transactions: Vec<(&str, f64)>) -> f64 {
    let mut balance = initial_balance;
    for tx in transactions {
        match apply(balance, tx) {
            Ok(updated) => balance = updated,
            Err(e) => eprintln!("skipping {} {:.2}: {}", tx.0, tx.1, e),
        }
    }
    balance
}

fn parse_line(line: &str) -> Result<(String, f64), TxError> {
    let mut parts = line.split_whitespace();
    let kind = parts.next().ok_or_else(|| TxError::MalformedLine(line.to_string()))?;
    let raw = parts.next().ok_or_else(|| TxError::MalformedLine(line.to_string()))?;
    parse_kind(kind)?;
    let amount = raw.parse::<f64>().map_err(|_| TxError::MalformedLine(line.to_string()))?;
    Ok((kind.to_string(), amount))
}

fn parse_ledger(text: &str) -> Result<Vec<(String, f64)>, TxError> {
    let mut parsed = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        parsed.push(parse_line(line)?);
    }
    Ok(parsed)
}

fn settle(initial_balance: f64, ledger: &str) -> Result<f64, TxError> {
    let parsed = parse_ledger(ledger)?;
    let transactions: Vec<(&str, f64)> = parsed.iter().map(|(k, a)| (k.as_str(), *a)).collect();
    Ok(process_transactions(initial_balance, transactions))
}

fn main() -> Result<(), TxError> {
    println!("{}", process_transactions(100.0, vec![("deposit", 50.0), ("withdraw", 20.0)]));
    println!("{}", process_transactions(50.0, vec![("withdraw", 100.0)]));
    let ledger = "deposit 250.5\nwithdraw 80\nwithdraw 5000\ndeposit 19.5";
    let final_balance = settle(100.0, ledger)?;
    println!("ledger settled at {:.2}", final_balance);
    Ok(())
}

