fn parse_field(text: &str, width: usize) -> Result<i32, String> {
    if text.len() != width || !text.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("expected {} digits, found `{}`", width, text));
    }
    let value = text.parse::<i32>().map_err(|e| e.to_string())?;
    Ok(value)
}

fn is_leap(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn days_in_month(year: i32, month: i32) -> i32 {
    if month == 2 {
        if is_leap(year) { 29 } else { 28 }
    } else if month == 4 || month == 6 || month == 9 || month == 11 {
        30
    } else {
        31
    }
}

fn parse_date(text: &str) -> Result<(i32, i32, i32), String> {
    let parts: Vec<&str> = text.split('-').collect();
    if parts.len() != 3 {
        return Err(format!("malformed date `{}`, expected YYYY-MM-DD", text));
    }
    let year = parse_field(parts[0], 4).map_err(|e| format!("year: {}", e))?;
    let month = parse_field(parts[1], 2).map_err(|e| format!("month: {}", e))?;
    let day = parse_field(parts[2], 2).map_err(|e| format!("day: {}", e))?;
    if month < 1 || month > 12 || day < 1 || day > days_in_month(year, month) {
        return Err(format!("date `{}` is out of range", text));
    }
    Ok((year, month, day))
}

fn to_civil_days(year: i32, month: i32, day: i32) -> i64 {
    let y = if month <= 2 { year - 1 } else { year } as i64;
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (month as i64 + 9) % 12;
    let doy = (153 * mp + 2) / 5 + day as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn days_between_checked(date1_str: &str, date2_str: &str) -> Result<i64, String> {
    let (y1, m1, d1) = parse_date(date1_str)?;
    let (y2, m2, d2) = parse_date(date2_str)?;
    Ok(to_civil_days(y2, m2, d2) - to_civil_days(y1, m1, d1))
}

fn days_between_dates(date1_str: &str, date2_str: &str) -> i64 {
    match days_between_checked(date1_str, date2_str) {
        Ok(days) => days,
        Err(e) => panic!("{}", e),
    }
}

fn main() {
    let spans = [
        ("2023-01-01", "2023-01-05"),
        ("2023-01-05", "2023-01-01"),
        ("2000-02-28", "2000-03-01"),
        ("2023-02-30", "2023-03-01"),
    ];
    for (from, to) in spans {
        match days_between_checked(from, to) {
            Ok(days) => println!("{} -> {}: {} days", from, to, days),
            Err(e) => eprintln!("skipping {} .. {}: {}", from, to, e),
        }
    }
    println!("year 2023 length: {} days", days_between_dates("2023-01-01", "2024-01-01"));
}

