fn merge_sorted_vectors(v1: Vec<i32>, v2: Vec<i32>) -> Vec<i32> {
    let mut merged = Vec::new();

    let mut i = 0;
    let mut j = 0;

    let v1_len = v1.len();
    let v2_len = v2.len();

    loop {
        let v1_val = v1.get(i);
        let v2_val = v2.get(j);

        if v1_val.is_none() && v2_val.is_none() {
            break;
        }

        match (v1_val, v2_val) {
            (Some(&val1), Some(&val2)) => {
                if val1 <= val2 {
                    merged.push(val1);
                    i += 1;
                } else {
                    merged.push(val2);
                    j += 1;
                }
            }
            (Some(&val1), None) => {
                merged.push(val1);
                i += 1;
            }
            (None, Some(&val2)) => {
                merged.push(val2);
                j += 1;
            }
            (None, None) => unreachable!(),
        }
    }
