use std::fmt::{self, Write as FmtWrite};
use std::io::{self, Read};
use std::num::ParseFloatError;

#[derive(Debug)]
enum TriangleError {
    NotANumber(ParseFloatError),
    BadSide(String, f64),
    MissingSide,
    TooManySides,
    Format(fmt::Error),
    Input(io::Error),
}

impl fmt::Display for TriangleError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TriangleError::NotANumber(e) => write!(f, "not a number: {}", e),
            TriangleError::BadSide(name, v) => write!(f, "side {} must be finite and positive, got {}", name, v),
            TriangleError::MissingSide => write!(f, "a triangle needs two short sides"),
            TriangleError::TooManySides => write!(f, "expected exactly two values per line"),
            TriangleError::Format(e) => write!(f, "formatting failed: {}", e),
            TriangleError::Input(e) => write!(f, "cannot read input: {}", e),
        }
    }
}

impl From<ParseFloatError> for TriangleError {
    fn from(e: ParseFloatError) -> Self { TriangleError::NotANumber(e) }
}
impl From<fmt::Error> for TriangleError {
    fn from(e: fmt::Error) -> Self { TriangleError::Format(e) }
}
impl From<io::Error> for TriangleError {
    fn from(e: io::Error) -> Self { TriangleError::Input(e) }
}

fn calculate_hypotenuse(a: f64, b: f64) -> f64 {
    (a * a + b * b).sqrt()
}

fn parse_side(name: &str, text: &str) -> Result<f64, TriangleError> {
    let value: f64 = text.trim().parse()?;
    if !value.is_finite() || value <= 0.0 {
        return Err(TriangleError::BadSide(name.to_string(), value));
    }
    Ok(value)
}

fn parse_pair(line: &str) -> Result<(f64, f64), TriangleError> {
    let mut fields = line.split_whitespace();
    let a_text = fields.next().ok_or(TriangleError::MissingSide)?;
    let b_text = fields.next().ok_or(TriangleError::MissingSide)?;
    if fields.next().is_some() {
        return Err(TriangleError::TooManySides);
    }
    let a = parse_side("a", a_text)?;
    let b = parse_side("b", b_text)?;
    Ok((a, b))
}

fn describe(line: &str) -> Result<String, TriangleError> {
    let (a, b) = parse_pair(line)?;
    let mut row = String::new();
    write!(row, "a = {:.3}, b = {:.3}  ->  c = {:.3}", a, b, calculate_hypotenuse(a, b))?;
    Ok(row)
}

fn total_perimeter(lines: &[&str]) -> Result<f64, TriangleError> {
    let mut sum = 0.0;
    for line in lines {
        let (a, b) = parse_pair(line)?;
        sum += a + b + calculate_hypotenuse(a, b);
    }
    Ok(sum)
}

fn report(lines: &[&str]) -> Result<String, TriangleError> {
    let mut out = String::new();
    for (index, line) in lines.iter().enumerate() {
        let row = describe(line)?;
        writeln!(out, "{:>2}: {}", index + 1, row)?;
    }
    let perimeter = total_perimeter(lines)?;
    writeln!(out, "total perimeter of all triangles: {:.3}", perimeter)?;
    Ok(out)
}

fn main() -> Result<(), TriangleError> {
    let mut raw = String::new();
