use std::fmt;

#[derive(Debug)]
enum ConvError {
    UnknownUnit(String),
    BadNumber(String),
    BadFormat(String),
}

impl fmt::Display for ConvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConvError::UnknownUnit(u) => write!(f, "unknown unit: {u}"),
            ConvError::BadNumber(n) => write!(f, "not a number: {n}"),
            ConvError::BadFormat(l) => write!(f, "malformed request: {l}"),
        }
    }
}

/// Number of metres in one unit of `unit`.
fn unit_factor(unit: &str) -> Result<f64, ConvError> {
    match unit {
        "m" => Ok(1.0),
        "cm" => Ok(0.01),
        "km" => Ok(1000.0),
        other => Err(ConvError::UnknownUnit(other.to_string())),
    }
}

fn try_convert(value: f64, from_unit: &str, to_unit: &str) -> Result<f64, ConvError> {
    let from = unit_factor(from_unit)?;
    let to = unit_factor(to_unit)?;
    Ok(value * from / to)
}

fn convert_length(value: f64, from_unit: &str, to_unit: &str) -> f64 {
    try_convert(value, from_unit, to_unit).expect("units must be one of m, cm, km")
}

/// Parses a request of the form "100 cm -> m" and checks that both units exist,
/// so the resulting triple is safe to hand to `convert_length`.
fn parse_request(line: &str) -> Result<(f64, String, String), ConvError> {
    let (lhs, rhs) = line
        .split_once("->")
        .ok_or_else(|| ConvError::BadFormat(line.trim().to_string()))?;
    let mut parts = lhs.split_whitespace();
    let number = parts
        .next()
        .ok_or_else(|| ConvError::BadFormat(line.trim().to_string()))?;
    let from_unit = parts
        .next()
        .ok_or_else(|| ConvError::BadFormat(line.trim().to_string()))?;
    let value: f64 = number
        .parse()
        .map_err(|_| ConvError::BadNumber(number.to_string()))?;
    let to_unit = rhs.trim();
    unit_factor(from_unit)?;
    unit_factor(to_unit)?;
    Ok((value, from_unit.to_string(), to_unit.to_string()))
}

fn describe(line: &str) -> Result<String, ConvError> {
    let (value, from_unit, to_unit) = parse_request(line)?;
    let result = convert_length(value, &from_unit, &to_unit);
    Ok(format!("{value} {from_unit} = {result} {to_unit}"))
}

fn total_in(lines: &[&str], unit: &str) -> Result<f64, ConvError> {
    unit_factor(unit)?;
    let mut sum = 0.0;
    for line in lines {
        let (value, from_unit, _) = parse_request(line)?;
        sum += convert_length(value, &from_unit, unit);
    }
    Ok(sum)
}

fn main() {
    let requests = ["100 cm -> m", "2 km -> m", "1.5 m -> cm", "7 furlong -> m"];
    for request in &requests {
        match describe(request) {
            Ok(text) => println!("{text}"),
            Err(err) => println!("{request}: {err}"),
        }
    }
    match total_in(&requests[..3], "m") {
        Ok(total) => println!("total: {total} m"),
        Err(err) => println!("total failed: {err}"),
    }
}

