fn mean(values: &[f64]) -> f64 {
    values.iter().sum::<f64>() / values.len() as f64
}

fn simple_linear_regression(x: &[f64], y: &[f64]) -> Option<(f64, f64)> {
    if x.len() != y.len() || x.len() < 2 {
        return None;
    }
    let mx = mean(x);
    let my = mean(y);
    let mut numerator = 0.0;
    let mut denominator = 0.0;
    for (xi, yi) in x.iter().zip(y.iter()) {
        numerator += (xi - mx) * (yi - my);
        denominator += (xi - mx) * (xi - mx);
    }
    if denominator == 0.0 {
        return None;
    }
    let m = numerator / denominator;
    Some((m, my - m * mx))
}

fn r_squared(x: &[f64], y: &[f64], m: f64, b: f64) -> Option<f64> {
    let my = mean(y);
    let mut residual = 0.0;
    let mut total = 0.0;
    for (xi, yi) in x.iter().zip(y.iter()) {
        residual += (yi - (m * xi + b)).powi(2);
        total += (yi - my).powi(2);
    }
    if total == 0.0 {
        return None;
    }
    Some(1.0 - residual / total)
}

