use chrono::{Datelike, Duration, NaiveDate, Weekday};
use std::num::ParseIntError;

#[derive(Debug)]
enum DateError {
    Format(String),
    Number(ParseIntError),
    Invalid(i32, u32, u32),
    Reversed(NaiveDate, NaiveDate),
}

impl From<ParseIntError> for DateError {
    fn from(e: ParseIntError) -> Self {
        DateError::Number(e)
    }
}

fn parse_date(s: &str) -> Result<NaiveDate, DateError> {
    let parts: Vec<&str> = s.trim().split('-').collect();
    if parts.len() != 3 {
        return Err(DateError::Format(s.to_string()));
    }
    let year: i32 = parts[0].parse()?;
    let month: u32 = parts[1].parse()?;
    let day: u32 = parts[2].parse()?;
    NaiveDate::from_ymd_opt(year, month, day).ok_or(DateError::Invalid(year, month, day))
}

fn is_business_day(date: NaiveDate) -> bool {
    !matches!(date.weekday(), Weekday::Sat | Weekday::Sun)
}

// A weekend day is booked on the business day the period was last open, i.e. the
// preceding Friday, so a span that starts on a Saturday still covers that Friday.
fn opening_business_day(mut date: NaiveDate) -> NaiveDate {
    while !is_business_day(date) {
        date -= Duration::days(1);
    }
    date
}

fn count_business_days_checked(start_date_str: &str, end_date_str: &str) -> Result<u32, DateError> {
    let start = parse_date(start_date_str)?;
    let end = parse_date(end_date_str)?;
    if start > end {
        return Err(DateError::Reversed(start, end));
    }
    let from = opening_business_day(start);
    // Every whole week contributes exactly five business days; only the tail of
    // the half-open range [from, end) has to be walked day by day.
    let span = (end - from).num_days();
    let whole_weeks = span / 7;
    let mut count = (whole_weeks * 5) as u32;
    let mut cursor = from + Duration::days(whole_weeks * 7);
    while cursor < end {
        if is_business_day(cursor) {
            count += 1;
        }
        cursor += Duration::days(1);
    }
    Ok(count)
}

pub fn count_business_days(start_date_str: &str, end_date_str: &str) -> u32 {
    count_business_days_checked(start_date_str, end_date_str).unwrap_or(0)
}

fn main() -> Result<(), DateError> {
    let periods = [
        ("2023-11-20", "2023-11-22"),
        ("2023-11-25", "2023-11-27"),
        ("2023-01-01", "2024-01-01"),
    ];
    for (start, end) in periods {
        let opened = parse_date(start)?;
        let days = count_business_days_checked(start, end)?;
        println!(
            "{} ({}) -> {}: {} business day(s)",
            opened,
            opened.weekday(),
            end,
            days
        );
    }
    Ok(())
}

