use rand::seq::SliceRandom;
use std::fmt;

const RANKS: [char; 13] = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'];
const SUITS: [(char, &'static str); 4] =
    [('C', "Clubs"), ('D', "Diamonds"), ('H', "Hearts"), ('S', "Spades")];

#[derive(Debug)]
enum CardError {
    Empty,
    MissingSuit(String),
    BadRank(char),
    BadSuit(char),
    NotEnoughCards(usize),
}

impl fmt::Display for CardError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CardError::Empty => write!(f, "empty card string"),
            CardError::MissingSuit(s) => write!(f, "card {:?} has no suit", s),
            CardError::BadRank(r) => write!(f, "unknown rank {:?}", r),
            CardError::BadSuit(s) => write!(f, "unknown suit {:?}", s),
            CardError::NotEnoughCards(n) => write!(f, "cannot deal {} cards", n),
        }
    }
}

struct Card {
    value: u32,
    suit: &'static str,
}

fn parse_card(text: &str) -> Result<Card, CardError> {
    let mut chars = text.chars();
    let rank = chars.next().ok_or(CardError::Empty)?;
    let suit = chars.next().ok_or_else(|| CardError::MissingSuit(text.to_string()))?;
    let index = RANKS.iter().position(|&r| r == rank).ok_or(CardError::BadRank(rank))?;
    let (_, name) = SUITS.iter().find(|(c, _)| *c == suit).ok_or(CardError::BadSuit(suit))?;
    Ok(Card { value: index as u32 + 2, suit: name })
}

fn rank_label(value: u32) -> String {
    match value {
        10 => "Ten".to_string(),
        11 => "Jack".to_string(),
        12 => "Queen".to_string(),
        13 => "King".to_string(),
        14 => "Ace".to_string(),
        v => v.to_string(),
    }
}

fn describe_card(text: &str) -> Result<String, CardError> {
    let card = parse_card(text)?;
    Ok(format!("{} of {}", rank_label(card.value), card.suit))
}

fn hand_score(hand: &[String]) -> Result<u32, CardError> {
    let mut total = 0;
    for card in hand {
        total += parse_card(card)?.value;
    }
    Ok(total)
}

fn build_deck() -> Vec<String> {
    let mut deck = Vec::with_capacity(RANKS.len() * SUITS.len());
    for (suit, _) in SUITS {
        for rank in RANKS {
            deck.push(format!("{}{}", rank, suit));
        }
    }
    deck
}

fn shuffle_deck(deck: &mut Vec<String>) {
    deck.shuffle(&mut rand::thread_rng());
}

fn deal(deck: &mut Vec<String>, count: usize) -> Option<Vec<String>> {
    let mut hand = Vec::with_capacity(count);
    for _ in 0..count {
        hand.push(deck.pop()?);
    }
    Some(hand)
}

fn report(hand: &[String]) -> Result<String, CardError> {
    let mut lines = Vec::with_capacity(hand.len() + 1);
    for card in hand {
        lines.push(format!("  {}", describe_card(card)?));
    }
    lines.push(format!("  total rank value: {}", hand_score(hand)?));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), CardError> {
    let mut deck = build_deck();
    shuffle_deck(&mut deck);
    let hand = deal(&mut deck, 5).ok_or(CardError::NotEnoughCards(5))?;
    println!("Dealt hand {:?}:", hand);
    println!("{}", report(&hand)?);
    let next = deck.last().ok_or(CardError::NotEnoughCards(1))?;
    println!("Next card off the deck: {}", describe_card(next)?);
    println!("Cards remaining: {}", deck.len());
    Ok(())
}

