        lines.push(format!("  {}", match describe_card(card) { Ok(v) => v, Err(e) => return Err(e.into()) }));
    }
    lines.push(format!("  total rank value: {}", match hand_score(hand) { Ok(v) => v, Err(e) => return Err(e.into()) }));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), CardError> {
    let mut deck = build_deck();
    shuffle_deck(&mut deck);
    let hand = match deal(&mut deck, 5).ok_or(CardError::NotEnoughCards(5)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("Dealt hand {:?}:", hand);
    println!("{}", match report(&hand) { Ok(v) => v, Err(e) => return Err(e.into()) });
    let next = match deck.last().ok_or(CardError::NotEnoughCards(1)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("Next card off the deck: {}", match describe_card(next) { Ok(v) => v, Err(e) => return Err(e.into()) });
    println!("Cards remaining: {}", deck.len());
    Ok(())
}

