use std::fmt;

#[derive(Debug)]
enum PolyError {
    MissingCoordinate(String),
    TrailingData(String),
    BadNumber { field: String, reason: String },
    TooFewVertices(usize),
}

impl fmt::Display for PolyError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            PolyError::MissingCoordinate(p) => write!(f, "point '{}' lacks a y coordinate", p),
            PolyError::TrailingData(p) => write!(f, "point '{}' has more than two coordinates", p),
            PolyError::BadNumber { field, reason } => {
                write!(f, "cannot read '{}' as a number: {}", field, reason)
            }
            PolyError::TooFewVertices(n) => write!(f, "a polygon needs at least 2 vertices, got {}", n),
        }
    }
}

fn parse_coordinate(field: &str) -> Result<f64, PolyError> {
    let value = field.trim().parse::<f64>().map_err(|e| PolyError::BadNumber {
        field: field.trim().to_string(),
        reason: e.to_string(),
    })?;
    Ok(value)
}

fn parse_point(text: &str) -> Result<(f64, f64), PolyError> {
    let mut parts = text.split(',');
    let x_field = parts.next().unwrap_or("");
    let y_field = parts
        .next()
        .ok_or_else(|| PolyError::MissingCoordinate(text.trim().to_string()))?;
    let x = parse_coordinate(x_field)?;
    let y = parse_coordinate(y_field)?;
    if parts.next().is_some() {
        return Err(PolyError::TrailingData(text.trim().to_string()));
    }
    Ok((x, y))
}

fn parse_polygon(text: &str) -> Result<Vec<(f64, f64)>, PolyError> {
    let mut vertices = Vec::new();
    for chunk in text.split(';').filter(|c| !c.trim().is_empty()) {
        let point = parse_point(chunk)?;
        vertices.push(point);
    }
    if vertices.len() < 2 {
        return Err(PolyError::TooFewVertices(vertices.len()));
    }
    Ok(vertices)
}

fn polygon_perimeter(vertices: &[(f64, f64)]) -> f64 {
    let edge = |a: (f64, f64), b: (f64, f64)| ((b.0 - a.0).hypot(b.1 - a.1));
    let mut total: f64 = vertices.windows(2).map(|w| edge(w[0], w[1])).sum();
    if vertices.len() > 2 {
        total += edge(vertices[vertices.len() - 1], vertices[0]);
    }
    total
}

fn describe(text: &str) -> Result<String, PolyError> {
    let vertices = parse_polygon(text)?;
    let perimeter = polygon_perimeter(&vertices);
    Ok(format!("{} vertices -> perimeter {:.4}", vertices.len(), perimeter))
}

fn main() -> Result<(), PolyError> {
    let inputs = [
        "0,0; 3,0; 3,4; 0,4",
        "0,0; 1,0",
        "0,0; 1,0; 1,1; 0,1; -1,0.5",
    ];
    for input in inputs {
        let report = describe(input)?;
        println!("{:<34} {}", input, report);
    }
    match describe("0,0; 2") {
        Ok(report) => println!("unexpected success: {}", report),
        Err(e) => println!("rejected input: {}", e),
    }
    Ok(())
}

