use std::fmt;
use std::io::{self, Write};
use std::num::ParseIntError;

#[derive(Debug)]
enum RequestError {
    MissingCapacity,
    EmptyNeeds,
    RequestOverflow,
    BadNumber(ParseIntError),
}

impl fmt::Display for RequestError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RequestError::MissingCapacity => write!(f, "missing ':' between capacity and needs"),
            RequestError::EmptyNeeds => write!(f, "no resource needs listed"),
            RequestError::RequestOverflow => write!(f, "total requested amount overflows u32"),
            RequestError::BadNumber(e) => write!(f, "invalid number: {e}"),
        }
    }
}

impl std::error::Error for RequestError {}

impl From<ParseIntError> for RequestError {
    fn from(e: ParseIntError) -> Self {
        RequestError::BadNumber(e)
    }
}

fn allocate_resources(capacity: u32, resource_needs: Vec<u32>) -> Vec<u32> {
    let mut remaining = capacity;
    let mut granted = Vec::new();
    for need in resource_needs {
        if need <= remaining {
            remaining -= need;
            granted.push(need);
        }
    }
    granted
}

fn parse_capacity(text: &str) -> Result<u32, RequestError> {
    let capacity = text.trim().parse::<u32>()?;
    Ok(capacity)
}

fn parse_needs(text: &str) -> Result<Vec<u32>, RequestError> {
    if text.trim().is_empty() {
        return Err(RequestError::EmptyNeeds);
    }
    let mut needs = Vec::new();
    for token in text.split(',') {
        needs.push(token.trim().parse::<u32>()?);
    }
    Ok(needs)
}

fn parse_request(line: &str) -> Result<(u32, Vec<u32>), RequestError> {
    let (cap_text, needs_text) = line.split_once(':').ok_or(RequestError::MissingCapacity)?;
    let capacity = parse_capacity(cap_text)?;
    let needs = parse_needs(needs_text)?;
    Ok((capacity, needs))
}

fn summarize(line: &str) -> Result<String, RequestError> {
    let (capacity, needs) = parse_request(line)?;
    let requested = needs
        .iter()
        .try_fold(0u32, |acc, &n| acc.checked_add(n))
        .ok_or(RequestError::RequestOverflow)?;
    let granted = allocate_resources(capacity, needs);
    let used: u32 = granted.iter().sum();
    Ok(format!(
        "capacity {capacity}: requested {requested} -> granted {granted:?} (used {used}, spare {})",
        capacity - used
    ))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdout = io::stdout();
