use std::fmt::{self, Write};
use std::num::ParseIntError;

#[derive(Debug)]
enum EntryError {
    MissingIndex(String),
    BadIndex(ParseIntError),
    EmptySentence(usize),
    Format(fmt::Error),
}

impl fmt::Display for EntryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EntryError::MissingIndex(line) => write!(f, "line {line:?} has no ':' separator"),
            EntryError::BadIndex(e) => write!(f, "bad entry index: {e}"),
            EntryError::EmptySentence(i) => write!(f, "entry {i} carries no words"),
            EntryError::Format(e) => write!(f, "formatting failed: {e}"),
        }
    }
}

impl From<ParseIntError> for EntryError {
    fn from(e: ParseIntError) -> Self {
        EntryError::BadIndex(e)
    }
}

impl From<fmt::Error> for EntryError {
    fn from(e: fmt::Error) -> Self {
        EntryError::Format(e)
    }
}

fn reverse_words_in_sentence(sentence: &str) -> String {
    let mut words: Vec<&str> = sentence.split_whitespace().collect();
    words.reverse();
    words.join(" ")
}

fn parse_entry(line: &str) -> Result<(usize, &str), EntryError> {
    let (index, rest) = line
        .split_once(':')
        .ok_or_else(|| EntryError::MissingIndex(line.to_string()))?;
    let index: usize = index.trim().parse()?;
    let sentence = rest.trim();
    if sentence.is_empty() {
        return Err(EntryError::EmptySentence(index));
    }
    Ok((index, sentence))
}

fn reverse_entry(line: &str) -> Result<String, EntryError> {
    let (index, sentence) = parse_entry(line)?;
    let mut rendered = String::new();
    write!(rendered, "{index}: {}", reverse_words_in_sentence(sentence))?;
    Ok(rendered)
}

fn count_words(line: &str) -> Result<usize, EntryError> {
    let (_, sentence) = parse_entry(line)?;
    Ok(sentence.split_whitespace().count())
}

fn reverse_document(text: &str) -> Result<String, EntryError> {
    let mut out = String::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let reversed = reverse_entry(line)?;
        writeln!(out, "{reversed}")?;
    }
    Ok(out)
}

fn document_summary(text: &str) -> Result<String, EntryError> {
    let mut entries = 0usize;
    let mut words = 0usize;
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        words += count_words(line)?;
        entries += 1;
    }
    let mut summary = String::new();
    write!(summary, "{entries} entries, {words} words total")?;
    Ok(summary)
}

fn main() -> Result<(), EntryError> {
    let document = "1: hello world\n2: Rust is fun\n3:   the quick brown fox  \n";
    let reversed = reverse_document(document)?;
    print!("{reversed}");
    let summary = document_summary(document)?;
    println!("{summary}");
    Ok(())
}

