    fn enqueue(&mut self, item: T);
    fn dequeue(&mut self) -> Option<T>;
    fn peek(&self) -> Option<&T>;
}

impl<T> Queue<T> for Vec<T> {
    fn enqueue(&mut self, item: T) {
        self.push(item);
    }

    fn dequeue(&mut self) -> Option<T> {
        if self.is_empty() {
            None
        } else {
            Some(self.remove(0))
        }
    }

    fn peek(&self) -> Option<&T> {
        self.first()
    }
}

pub fn create_queue() -> Vec<i32> {
    Vec::new()
}

#[derive(Debug)]
pub enum Command {
    Enqueue(i32),
    Dequeue,
    Peek,
}

pub fn parse_command(line: &str) -> Result<Command, String> {
    let mut parts = line.split_whitespace();
    let verb = parts.next().ok_or_else(|| "empty command".to_string())?;
    match verb {
        "enqueue" => {
            let raw = parts.next().ok_or_else(|| format!("`{}` needs a value", verb))?;
            let value = raw.parse::<i32>().map_err(|e| format!("bad value `{}`: {}", raw, e))?;
            Ok(Command::Enqueue(value))
        }
        "dequeue" => Ok(Command::Dequeue),
        "peek" => Ok(Command::Peek),
        other => Err(format!("unknown command `{}`", other)),
    }
}

pub fn apply(queue: &mut Vec<i32>, command: Command) -> Result<Option<i32>, String> {
    match command {
        Command::Enqueue(value) => {
            queue.enqueue(value);
            Ok(None)
        }
        Command::Dequeue => Ok(Some(queue.dequeue().ok_or_else(|| "dequeue on empty queue".to_string())?)),
        Command::Peek => Ok(Some(*queue.peek().ok_or_else(|| "peek on empty queue".to_string())?)),
    }
}

pub fn run_script(queue: &mut Vec<i32>, lines: &[&str]) -> Result<Vec<i32>, String> {
    let mut outputs = Vec::new();
    for line in lines {
        let command = parse_command(line)?;
        if let Some(value) = apply(queue, command)? {
            outputs.push(value);
        }
    }
    Ok(outputs)
}

pub fn sum_of_two(queue: &mut Vec<i32>) -> Result<i32, String> {
    let first = queue.dequeue().ok_or_else(|| "queue is empty".to_string())?;
    let second = queue.dequeue().ok_or_else(|| "queue held only one item".to_string())?;
    Ok(first + second)
}

pub fn report(queue: &Vec<i32>) -> Result<String, String> {
    let front = queue.peek().ok_or_else(|| "queue is empty".to_string())?;
    Ok(format!("front = {}, length = {}", front, queue.len()))
}

fn main() -> Result<(), String> {
    let mut q = create_queue();
    let first_run = run_script(&mut q, &["enqueue 1", "enqueue 2", "dequeue", "dequeue"])?;
    println!("dequeued: {:?}", first_run);

    let second_run = run_script(&mut q, &["enqueue 10", "enqueue 32", "peek"])?;
    println!("peeked: {:?}", second_run);
    println!("{}", report(&q)?);

    let total = sum_of_two(&mut q)?;
    println!("sum of two front items: {}", total);
    println!("{}", report(&q).unwrap_or_else(|e| e));
    Ok(())
}

