use std::collections::HashMap;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ParseError {
    MissingColon(String),
    EmptyKey,
    MissingField(String),
    BadNumber(ParseIntError),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingColon(field) => write!(f, "field `{}` has no colon", field),
            ParseError::EmptyKey => write!(f, "a field has an empty key"),
            ParseError::MissingField(key) => write!(f, "required key `{}` is absent", key),
            ParseError::BadNumber(err) => write!(f, "invalid number: {}", err),
        }
    }
}

impl From<ParseIntError> for ParseError {
    fn from(err: ParseIntError) -> Self {
        ParseError::BadNumber(err)
    }
}

fn parse_pair(field: &str) -> Result<(String, String), ParseError> {
    let (key, value) = field
        .split_once(':')
        .ok_or_else(|| ParseError::MissingColon(field.to_string()))?;
    let key = key.trim();
    if key.is_empty() {
        return Err(ParseError::EmptyKey);
    }
    Ok((key.to_string(), value.trim().to_string()))
}

fn parse_key_value_string(input: &str) -> HashMap<String, String> {
    input
        .split(',')
        .filter(|field| !field.trim().is_empty())
        .filter_map(|field| parse_pair(field).ok())
        .collect()
}

fn parse_strict(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for field in input.split(',').filter(|f| !f.trim().is_empty()) {
        let (key, value) = parse_pair(field)?;
        map.insert(key, value);
    }
    Ok(map)
}

fn field<'a>(map: &'a HashMap<String, String>, key: &str) -> Result<&'a String, ParseError> {
    map.get(key).ok_or_else(|| ParseError::MissingField(key.to_string()))
}

fn describe(input: &str) -> Result<String, ParseError> {
    let map = parse_strict(input)?;
    let name = field(&map, "name")?;
    let age_text = field(&map, "age")?;
    let age: u32 = age_text.parse()?;
    let city = field(&map, "city")?;
    Ok(format!("{} ({}) lives in {}", name, age, city))
}

fn main() -> Result<(), ParseError> {
    let pairs = parse_key_value_string("name:Alice,age:30");
    println!("name={:?} age={:?}", pairs.get("name"), pairs.get("age"));
    println!("{:?}", parse_key_value_string("city:London"));
    println!("{}", describe("name:Alice,age:30,city:London")?);
    let strict = parse_strict("name:Bob, age:41, city:Leeds")?;
    println!("age field: {}", field(&strict, "age")?);
    match describe("name:Carol,age:abc,city:Hull") {
        Ok(text) => println!("{}", text),
        Err(err) => println!("could not describe: {}", err),
    }
    Ok(())
}

