fn encrypt_shift_cipher(text: &str, shift: u8) -> String {
    text.chars().map(|c| {
        let res: Result<char, std::io::Error> = if c.is_ascii_lowercase() {
            let base = b'a';
            let offset = c as u8 - base;
            let shifted_offset = (offset + shift) % 26;
            Ok((base + shifted_offset) as char)
        } else {
            Ok(c)
        };
        res.unwrap_or_else(|e| {
            eprintln!("Error processing character: {}", e);
            c 
        })
    }).collect()
}

