use std::convert::TryFrom;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum RangeError {
    Syntax(String),
    Bound(ParseIntError),
    Inverted(i32, i32),
    Overflow(i32, i32),
    TotalOverflow(i64),
}

impl fmt::Display for RangeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RangeError::Syntax(spec) => write!(f, "malformed range specification: {:?}", spec),
            RangeError::Bound(err) => write!(f, "invalid bound: {}", err),
            RangeError::Inverted(a, b) => write!(f, "start {} is greater than end {}", a, b),
            RangeError::Overflow(a, b) => write!(f, "sum of {}..={} does not fit in i32", a, b),
            RangeError::TotalOverflow(t) => write!(f, "combined total {} does not fit in i32", t),
        }
    }
}

impl From<ParseIntError> for RangeError {
    fn from(err: ParseIntError) -> Self {
        RangeError::Bound(err)
    }
}

fn parse_bound(text: &str) -> Result<i32, RangeError> {
    let value = match text.trim().parse::<i32>() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(value)
}

fn parse_range(spec: &str) -> Result<(i32, i32), RangeError> {
    let (left, right) = match spec
        .split_once("..")
        .ok_or_else(|| RangeError::Syntax(spec.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let start = match parse_bound(left) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let end = match parse_bound(right) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((start, end))
}

fn sum_range(start: i32, end: i32) -> i32 {
    if start > end {
        return 0;
    }
    let count = (end as i64) - (start as i64) + 1;
    (((start as i64) + (end as i64)) * count / 2) as i32
}

fn checked_sum_range(start: i32, end: i32) -> Result<i32, RangeError> {
    if start > end {
        return Err(RangeError::Inverted(start, end));
    }
    let count = (end as i64) - (start as i64) + 1;
    let total = ((start as i64) + (end as i64)) * count / 2;
    let fitted = match i32::try_from(total).map_err(|_| RangeError::Overflow(start, end)) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(fitted)
}

fn sum_spec(spec: &str) -> Result<i32, RangeError> {
    let (start, end) = match parse_range(spec) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let total = match checked_sum_range(start, end) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(total)
}

fn format_report(spec: &str) -> Result<String, RangeError> {
    let (start, end) = match parse_range(spec) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let total = match checked_sum_range(start, end) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(format!("sum_range({}, {}) = {}", start, end, total))
}

fn sum_all(specs: &[&str]) -> Result<i32, RangeError> {
    let mut grand = 0i64;
    for spec in specs {
        grand += match sum_spec(spec) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        } as i64;
    }
    let fitted = match i32::try_from(grand).map_err(|_| RangeError::TotalOverflow(grand)) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(fitted)
}

fn main() -> Result<(), RangeError> {
    let specs = ["1..5", "-2..2", "10..10", "-100..100"];
    for spec in &specs {
        println!("{}", match format_report(spec) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    println!("combined total = {}", match sum_all(&specs) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    println!("descending range collapses to {}", sum_range(5, 1));
    let err = sum_spec("7..3").unwrap_err();
    println!("rejected: {}", err);
    Ok(())
}

