use rand::{thread_rng, Rng};
use std::io::{self, Write};

fn generate_password(length: usize) -> Result<String, io::Error> {
    if length == 0 {
        return Ok(String::new());
    }

    let charset: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";
    let mut password = String::with_capacity(length);
    let mut rng = thread_rng();

    for _ in 0..length {
        let idx = rng.gen_range(0..charset.len());
        let char_to_add = charset[idx] as char;
        password.push(char_to_add);
    }
    Ok(password)
}

fn main() -> Result<(), io::Error> {
    let mut input = String::new();
    print!("Enter password length: ");
    io::stdout().flush()?; // Use ? operator

    io::stdin().read_line(&mut input)?; // Use ? operator
    let length: usize = input.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?; // Use ? operator

    let password = generate_password(length)?; // Use ? operator
