use std::env;
use std::fmt;
use std::io::{self, Read};
use std::num::ParseIntError;

#[derive(Debug)]
enum InputError {
    Empty,
    Number(ParseIntError),
    Io(io::Error),
}

impl From<ParseIntError> for InputError {
    fn from(e: ParseIntError) -> Self {
        InputError::Number(e)
    }
}

impl From<io::Error> for InputError {
    fn from(e: io::Error) -> Self {
        InputError::Io(e)
    }
}

fn is_even(num: i32) -> bool {
    num % 2 == 0
}

fn parity_of(num: i32) -> &'static str {
    if is_even(num) {
        "even"
    } else {
        "odd"
    }
}

fn parse_number(text: &str) -> Result<i32, InputError> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err(InputError::Empty);
    }
    Ok(trimmed.parse::<i32>()?)
}

fn parse_all(items: &[&str]) -> Result<Vec<i32>, InputError> {
    let mut values = Vec::with_capacity(items.len());
    for item in items {
        values.push(parse_number(item)?);
    }
    Ok(values)
}

fn read_values_from_stdin() -> Result<Vec<i32>, InputError> {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer)?;
    let items: Vec<&str> = buffer.split_whitespace().collect();
    if items.is_empty() {
        return Err(InputError::Empty);
    }
    parse_all(&items)
}

fn report(values: &[i32]) -> String {
    let evens = values.iter().filter(|v| is_even(**v)).count();
    let mut lines: Vec<String> = values
        .iter()
        .map(|v| format!("{} is {}", v, parity_of(*v)))
        .collect();
    lines.push(format!("{} of {} are even", evens, values.len()));
    lines.join("\n")
}

fn main() -> Result<(), InputError> {
    let args: Vec<String> = env::args().skip(1).collect();
    let values = if args.is_empty() {
        read_values_from_stdin()?
    } else {
        let items: Vec<&str> = args.iter().map(String::as_str).collect();
        parse_all(&items)?
    };
    println!("{}", report(&values));
    Ok(())
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::Empty => write!(f, "no value given"),
            InputError::Number(e) => write!(f, "not an integer: {}", e),
            InputError::Io(e) => write!(f, "cannot read input: {}", e),
        }
    }
}

impl std::error::Error for InputError {}

