use std::f64::consts::PI;

fn circle_circumference(radius: f64) -> f64 {
    2.0 * PI * radius
}

fn parse_radius(text: &str) -> Result<f64, String> {
    let value: f64 = text
        .trim()
        .parse()
        .map_err(|_| format!("`{}` is not a number", text.trim()))?;
    if !value.is_finite() {
        return Err(format!("radius `{}` is not finite", text.trim()));
    }
    if value < 0.0 {
        return Err(format!("radius {} is negative", value));
    }
    Ok(value)
}

fn circumference_of(text: &str) -> Result<f64, String> {
    let radius = parse_radius(text)?;
    Ok(circle_circumference(radius))
}

fn split_record(record: &str) -> Result<(&str, &str), String> {
    let mut parts = record.splitn(2, ',');
    let label = parts.next().ok_or_else(|| "empty record".to_string())?;
    let radius = parts
        .next()
        .ok_or_else(|| format!("record `{}` has no radius field", record))?;
    Ok((label.trim(), radius))
}

fn format_record(record: &str) -> Result<String, String> {
    let (label, radius_text) = split_record(record)?;
    let radius = parse_radius(radius_text)?;
    Ok(format!(
        "{:<10} r = {:>7.3}   C = {:>9.5}",
        label,
        radius,
        circle_circumference(radius)
    ))
}

fn total_circumference(records: &[&str]) -> Result<f64, String> {
    let mut sum = 0.0;
    for record in records {
        let (_, radius_text) = split_record(record)?;
        sum += circumference_of(radius_text)?;
    }
    Ok(sum)
}

fn radius_from_circumference(circumference_text: &str) -> Result<f64, String> {
    let circumference = parse_radius(circumference_text)?;
    Ok(circumference / (2.0 * PI))
}

fn main() -> Result<(), String> {
    let records = ["unit,1.0", "point,0.0", "wheel,0.35", "planet,6371.0"];

    for record in &records {
        println!("{}", format_record(record)?);
    }

    println!("total circumference: {:.5}", total_circumference(&records)?);

    let recovered = radius_from_circumference("6.283185307179586")?;
    println!("radius recovered from C = 6.283185307179586: {:.6}", recovered);

    let bad = format_record("blob,-2");
    println!("rejected input: {}", bad.unwrap_err());

    Ok(())
}

