use std::fmt::Write as _;

/// Builds the multiplication table for `num` from 1 to 10 as printable rows.
fn multiplication_table(num: u8) -> Vec<String> {
    (1..=10u8)
        .map(|i| format!("{} x {} = {}", num, i, num as u16 * i as u16))
        .collect()
}

/// Reads a factor from text (command line argument or a table row fragment).
fn parse_number(text: &str) -> Result<u8, String> {
    let trimmed = text.trim();
    trimmed
        .parse::<u8>()
        .map_err(|e| format!("'{trimmed}' is not a valid factor: {e}"))
}

/// Splits a row such as "5 x 1 = 5" back into its three numbers.
fn parse_entry(row: &str) -> Result<(u8, u8, u16), String> {
    let (factors, product) = row
        .split_once('=')
        .ok_or_else(|| format!("row '{row}' has no '='"))?;
    let (left, right) = factors
        .split_once('x')
        .ok_or_else(|| format!("row '{row}' has no 'x'"))?;
    let factor = parse_number(left)?;
    let index = parse_number(right)?;
    let result = product
        .trim()
        .parse::<u16>()
        .map_err(|e| format!("row '{row}' has an unreadable product: {e}"))?;
    Ok((factor, index, result))
}

/// Re-reads a generated table and returns the sum of its products.
fn table_checksum(num: u8) -> Result<u16, String> {
    let mut checksum = 0u16;
    for (position, row) in multiplication_table(num).iter().enumerate() {
        let (factor, index, result) = parse_entry(row)?;
        if factor != num || index as usize != position + 1 {
            return Err(format!("row {position} has unexpected factors: '{row}'"));
        }
        if result != factor as u16 * index as u16 {
            return Err(format!("row {position} has a wrong product: '{row}'"));
        }
        checksum = checksum
            .checked_add(result)
            .ok_or_else(|| format!("checksum overflow while reading '{row}'"))?;
    }
    Ok(checksum)
}

/// Formats the tables of every requested number into one report.
fn render_report(requests: &[String]) -> Result<String, String> {
    let mut report = String::new();
    for request in requests {
        let num = parse_number(request)?;
        for row in multiplication_table(num) {
            writeln!(report, "{row}").map_err(|e| e.to_string())?;
        }
        let checksum = table_checksum(num)?;
        writeln!(report, "sum of products for {num}: {checksum}\n").map_err(|e| e.to_string())?;
    }
    Ok(report)
}

fn main() -> Result<(), String> {
    let mut requests: Vec<String> = std::env::args().skip(1).collect();
    if requests.is_empty() {
        requests = vec!["2".to_string(), "0".to_string()];
    }
    let report = render_report(&requests)?;
    print!("{report}");
    Ok(())
}

