use std::num::ParseIntError;

/// Returns the smallest element of `numbers`, or `None` when the slice is empty.
fn find_min_element(numbers: &[i32]) -> Option<i32> {
    let mut best = *numbers.first()?;
    for &n in &numbers[1..] {
        if n < best {
            best = n;
        }
    }
    Some(best)
}

/// Human readable summary of a row, or `None` if there is nothing to summarize.
fn summarize(numbers: &[i32]) -> Option<String> {
    let lowest = find_min_element(numbers)?;
    let highest = *numbers.iter().max()?;
    Some(format!(
        "{} values, min {}, max {}",
        numbers.len(),
        lowest,
        highest
    ))
}

/// Parses a comma separated row; blank fields are skipped so empty rows are allowed.
fn parse_row(line: &str) -> Result<Vec<i32>, ParseIntError> {
    line.split(',')
        .map(str::trim)
        .filter(|field| !field.is_empty())
        .map(|field| field.parse::<i32>())
        .collect()
}

/// Parses one line and describes it.
fn describe_row(line: &str) -> Result<String, ParseIntError> {
    let row = parse_row(line)?;
    Ok(summarize(&row).unwrap_or_else(|| "empty row".to_string()))
}

/// Smallest value across every row of the dataset.
fn overall_min(lines: &[&str]) -> Result<Option<i32>, ParseIntError> {
    let mut all = Vec::new();
    for line in lines {
        all.extend(parse_row(line)?);
    }
    Ok(find_min_element(&all))
}

/// Row indices paired with their minimum, ordered from smallest minimum upwards.
fn rows_by_min(lines: &[&str]) -> Result<Vec<(usize, i32)>, ParseIntError> {
    let mut ranked = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        let row = parse_row(line)?;
        if let Some(lowest) = find_min_element(&row) {
            ranked.push((index, lowest));
        }
    }
    ranked.sort_by_key(|&(_, lowest)| lowest);
    Ok(ranked)
}

fn report(dataset: &str) -> Result<String, ParseIntError> {
    let lines: Vec<&str> = dataset.lines().collect();
    let mut out = String::new();

    for line in &lines {
        out.push_str(&format!("{:<14} -> {}\n", line, describe_row(line)?));
    }

    for (index, lowest) in rows_by_min(&lines)? {
        out.push_str(&format!("row {} has minimum {}\n", index, lowest));
    }

    match overall_min(&lines)? {
        Some(lowest) => out.push_str(&format!("overall minimum: {}\n", lowest)),
        None => out.push_str("overall minimum: none\n"),
    }
    Ok(out)
}

fn main() -> Result<(), ParseIntError> {
    print!("{}", report("5, 2, 8, 1, 9\n-3, 7, 7\n\n42, 0")?);
    Ok(())
}

