use std::fmt::{self, Write as _};

#[derive(Debug)]
enum EntryError {
    NoSeparator(String),
    EmptyKey(String),
    EmptyValue(String),
    MissingKey(String),
    Formatting(fmt::Error),
}

impl fmt::Display for EntryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EntryError::NoSeparator(l) => write!(f, "no '=' in line: {l}"),
            EntryError::EmptyKey(l) => write!(f, "empty key in line: {l}"),
            EntryError::EmptyValue(k) => write!(f, "entry {k} has no value"),
            EntryError::MissingKey(k) => write!(f, "no entry named {k}"),
            EntryError::Formatting(e) => write!(f, "formatting failed: {e}"),
        }
    }
}

impl From<fmt::Error> for EntryError {
    fn from(e: fmt::Error) -> Self {
        EntryError::Formatting(e)
    }
}

struct Entry {
    key: String,
    value: String,
}

fn to_uppercase_string(s: &str) -> String {
    s.chars().flat_map(char::to_uppercase).collect()
}

fn parse_entry(line: &str) -> Result<Entry, EntryError> {
    let (raw_key, raw_value) = line
        .split_once('=')
        .ok_or_else(|| EntryError::NoSeparator(line.to_string()))?;
    let key = raw_key.trim();
    if key.is_empty() {
        return Err(EntryError::EmptyKey(line.to_string()));
    }
    Ok(Entry { key: to_uppercase_string(key), value: raw_value.trim().to_string() })
}

fn parse_document(text: &str) -> Result<Vec<Entry>, EntryError> {
    let mut entries = Vec::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        entries.push(parse_entry(trimmed)?);
    }
    Ok(entries)
}

fn lookup<'a>(entries: &'a [Entry], key: &str) -> Result<&'a str, EntryError> {
    let wanted = to_uppercase_string(key);
    let entry = entries
        .iter()
        .find(|e| e.key == wanted)
        .ok_or(EntryError::MissingKey(wanted))?;
    Ok(entry.value.as_str())
}

fn shout_first_word(entries: &[Entry], key: &str) -> Result<String, EntryError> {
    let value = lookup(entries, key)?;
    let word = value
        .split_whitespace()
        .next()
        .ok_or_else(|| EntryError::EmptyValue(to_uppercase_string(key)))?;
    Ok(to_uppercase_string(word))
}

fn render_report(entries: &[Entry]) -> Result<String, EntryError> {
    let mut out = String::new();
    for entry in entries {
        writeln!(out, "{} -> {}", entry.key, to_uppercase_string(&entry.value))?;
    }
    let greeting = lookup(entries, "greeting")?;
    writeln!(out, "shouted greeting: {}", to_uppercase_string(greeting))?;
    let opener = shout_first_word(entries, "greeting")?;
    write!(out, "first word only: {opener}")?;
    Ok(out)
}

fn run(text: &str) -> Result<String, EntryError> {
    let entries = parse_document(text)?;
    render_report(&entries)
}

fn main() {
    let document = "# sample input\ngreeting = hello world\nlanguage = Rust\n";
    match run(document) {
        Ok(report) => println!("{report}"),
        Err(e) => eprintln!("error: {e}"),
    }
}

