use std::error::Error;
use std::fmt;
use std::io::{self, Read, Write};

/// Errors that can come out of the textual input the driver reads.
#[derive(Debug)]
enum InputError {
    NotANumber(String),
    NotPositive,
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::NotANumber(raw) => write!(f, "`{raw}` is not a 32-bit unsigned integer"),
            InputError::NotPositive => write!(f, "the value must be a positive integer"),
        }
    }
}

impl Error for InputError {}

/// The task's function: true when `n` is a power of two.
fn is_power_of_two(n: u32) -> bool {
    n != 0 && n & (n - 1) == 0
}

/// Parses one line of input into the positive integer the checker expects.
fn parse_number(raw: &str) -> Result<u32, InputError> {
    let trimmed = raw.trim();
    let value: u32 = trimmed
        .parse()
        .map_err(|_| InputError::NotANumber(trimmed.to_string()))?;
    if value == 0 {
        return Err(InputError::NotPositive);
    }
    Ok(value)
}

/// `k` such that `n == 2^k`, when `n` is a power of two.
fn exponent_of(n: u32) -> Option<u32> {
    if is_power_of_two(n) {
        Some(n.trailing_zeros())
    } else {
        None
    }
}

/// Largest power of two strictly below `n`, if there is one.
fn largest_power_below(n: u32) -> Option<u32> {
    let below = n.checked_sub(1)?;
    if below == 0 {
        return None;
    }
    Some(1u32 << (31 - below.leading_zeros()))
}

/// One human-readable verdict for one raw input line.
fn describe(raw: &str) -> Result<String, InputError> {
    let n = parse_number(raw)?;
    Ok(match exponent_of(n) {
        Some(k) => format!("{n}: yes (2^{k})"),
        None => match largest_power_below(n) {
            Some(p) => format!("{n}: no (largest power of two below it is {p})"),
            None => format!("{n}: no"),
        },
    })
}

/// Full report for every input line, plus a tally.
fn summarize(inputs: &[&str]) -> Result<String, InputError> {
    let mut report = String::new();
    let mut powers = 0usize;
    for raw in inputs {
        report.push_str(&describe(raw)?);
        report.push('\n');
        if is_power_of_two(parse_number(raw)?) {
            powers += 1;
        }
    }
    report.push_str(&format!("{powers} of {} are powers of two\n", inputs.len()));
    Ok(report)
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text)?;
    let inputs: Vec<&str> = text.lines().filter(|l| !l.trim().is_empty()).collect();
    let report = summarize(&inputs)?;
    let mut out = io::stdout().lock();
    out.write_all(report.as_bytes())?;
    out.flush()?;
    Ok(())
}

