use std::fmt::Write as _;

/// Commands understood by the queue script interpreter.
enum Command {
    Enqueue(String),
    Dequeue,
    Drain(usize),
}

/// Basic FIFO queue behaviour for `Vec<String>`.
trait StringQueue {
    fn enqueue(&mut self, item: String);
    fn dequeue(&mut self) -> Option<String>;
}

impl StringQueue for Vec<String> {
    fn enqueue(&mut self, item: String) {
        self.push(item);
    }

    fn dequeue(&mut self) -> Option<String> {
        if self.is_empty() {
            None
        } else {
            Some(self.remove(0))
        }
    }
}

/// Creates an empty queue of `String` elements.
fn create_string_queue() -> Vec<String> {
    Vec::new()
}

/// Removes exactly `n` elements, or nothing if the queue runs dry.
fn drain_exactly(queue: &mut Vec<String>, n: usize) -> Option<Vec<String>> {
    let mut taken = Vec::with_capacity(n);
    for _ in 0..n {
        taken.push(queue.dequeue()?);
    }
    Some(taken)
}

fn parse_command(line: &str) -> Result<Command, String> {
    let (verb, argument) = match line.split_once(char::is_whitespace) {
        Some((verb, rest)) => (verb, Some(rest.trim())),
        None => (line, None),
    };
    match verb {
        "enqueue" => {
            let value = argument.ok_or_else(|| "enqueue needs a value".to_string())?;
            Ok(Command::Enqueue(value.to_string()))
        }
        "dequeue" => Ok(Command::Dequeue),
        "drain" => {
            let raw = argument.ok_or_else(|| "drain needs a count".to_string())?;
            let count = raw.parse::<usize>().map_err(|e| e.to_string())?;
            Ok(Command::Drain(count))
        }
        other => Err(format!("unknown command {other:?}")),
    }
}

fn apply(queue: &mut Vec<String>, command: Command) -> Result<String, String> {
    match command {
        Command::Enqueue(value) => {
            queue.enqueue(value.clone());
            Ok(format!("enqueued {value:?}, len = {}", queue.len()))
        }
        Command::Dequeue => Ok(format!("dequeued {:?}", queue.dequeue())),
        Command::Drain(n) => {
            let taken = drain_exactly(queue, n)
                .ok_or_else(|| format!("cannot drain {n} items, queue too short"))?;
            Ok(format!("drained {taken:?}"))
        }
    }
}

fn run_script(script: &str) -> Result<String, String> {
    let mut queue = create_string_queue();
    let mut report = String::new();
    for line in script.lines().map(str::trim).filter(|l| !l.is_empty()) {
        let command = parse_command(line)?;
        let outcome = apply(&mut queue, command)?;
        writeln!(report, "{line:>12} -> {outcome}").map_err(|e| e.to_string())?;
    }
    writeln!(report, "{:>12} -> {:?}", "final", queue).map_err(|e| e.to_string())?;
    Ok(report)
}

fn main() -> Result<(), String> {
    let report = run_script(
        "enqueue a
         dequeue
         dequeue
         enqueue b
         enqueue c
         enqueue d
         drain 2",
    )?;
    print!("{report}");
    Ok(())
}

