use std::collections::BTreeMap;
use std::num::NonZeroUsize;

fn calculate_grade_average(grades: &[u8]) -> Option<f64> {
    let count = NonZeroUsize::new(grades.len())?;
    let sum: u32 = grades.iter().copied().map(u32::from).sum();
    Some(f64::from(sum) / count.get() as f64)
}

fn parse_grades(list: &str) -> Result<Vec<u8>, String> {
    let mut grades = Vec::new();
    for token in list.split(',').filter(|t| !t.trim().is_empty()) {
        let text = token.trim();
        let grade: u8 = text.parse().map_err(|_| format!("invalid grade '{text}'"))?;
        if grade > 100 {
            return Err(format!("grade {grade} is above the maximum of 100"));
        }
        grades.push(grade);
    }
    Ok(grades)
}

fn parse_record(line: &str) -> Result<(String, Vec<u8>), String> {
    let (name, rest) = line.split_once(':').ok_or("missing ':' separator")?;
    let grades = parse_grades(rest)?;
    Ok((name.trim().to_string(), grades))
}

fn build_report(lines: &[&str]) -> Result<BTreeMap<String, Option<f64>>, String> {
    let mut report = BTreeMap::new();
    for line in lines {
        let (name, grades) = parse_record(line)?;
        report.insert(name, calculate_grade_average(&grades));
    }
    Ok(report)
}

fn letter_grade(average: f64) -> char {
    if average >= 90.0 {
        'A'
    } else if average >= 80.0 {
        'B'
    } else if average >= 70.0 {
        'C'
    } else if average >= 60.0 {
        'D'
    } else {
        'F'
    }
}

fn top_student(report: &BTreeMap<String, Option<f64>>) -> Option<(String, f64)> {
    report
        .iter()
        .filter_map(|(name, avg)| avg.map(|a| (name.clone(), a)))
        .max_by(|a, b| a.1.total_cmp(&b.1))
}

fn format_report(lines: &[&str]) -> Result<String, String> {
    let report = build_report(lines)?;
    let mut out = String::new();
    for (name, average) in &report {
        match average {
            Some(a) => out.push_str(&format!("{name}: {a:.2} ({})\n", letter_grade(*a))),
            None => out.push_str(&format!("{name}: no grades recorded\n")),
        }
    }
    let (name, average) = top_student(&report).ok_or("no averages available")?;
    out.push_str(&format!("top: {name} with {average:.2}\n"));
    Ok(out)
}

fn main() {
    let lines = [
        "Ada: 90, 85, 95",
        "Grace: 72, 68, 80, 91",
        "Linus: ",
        "Barbara: 100, 99",
    ];
    match format_report(&lines) {
        Ok(text) => print!("{text}"),
        Err(e) => eprintln!("report failed: {e}"),
    }
}

