use std::error::Error;
use std::fmt;

fn remove_vowels(s: &str) -> String {
    s.chars()
        .filter(|c| !matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u'))
        .collect()
}

#[derive(Debug)]
struct EntryError {
    message: String,
}

impl EntryError {
    fn new(message: impl Into<String>) -> Self {
        EntryError { message: message.into() }
    }
}

impl fmt::Display for EntryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl Error for EntryError {}

fn parse_entry(line: &str) -> Result<(&str, &str), EntryError> {
    let (key, value) = line
        .split_once('=')
        .ok_or_else(|| EntryError::new(format!("expected 'key = value' in {line:?}")))?;
    let key = key.trim();
    if key.is_empty() {
        return Err(EntryError::new(format!("empty key in {line:?}")));
    }
    Ok((key, value.trim()))
}

fn reduction_percent(original: &str, stripped: &str) -> Option<f64> {
    let total = original.chars().count();
    if total == 0 {
        return None;
    }
    let removed = total - stripped.chars().count();
    Some(removed as f64 * 100.0 / total as f64)
}

fn describe_entry(line: &str) -> Result<String, EntryError> {
    let (key, value) = parse_entry(line)?;
    let stripped = remove_vowels(value);
    let pct = reduction_percent(value, &stripped)
        .ok_or_else(|| EntryError::new(format!("{key} has an empty value")))?;
    Ok(format!("{key}: {value:?} -> {stripped:?} ({pct:.1}% removed)"))
}

fn shortest_skeleton_key(lines: &[&str]) -> Result<String, EntryError> {
    let mut best: Option<(usize, String)> = None;
    for line in lines {
        let (key, value) = parse_entry(line)?;
        let len = remove_vowels(value).chars().count();
        if best.as_ref().map_or(true, |(best_len, _)| len < *best_len) {
            best = Some((len, key.to_string()));
        }
    }
    let (_, key) = best.ok_or_else(|| EntryError::new("no entries to compare"))?;
    Ok(key)
}

fn report(lines: &[&str]) -> Result<String, EntryError> {
    let mut out = String::new();
    for line in lines {
        let entry = describe_entry(line)?;
        out.push_str(&entry);
        out.push('\n');
    }
    let key = shortest_skeleton_key(lines)?;
    out.push_str(&format!("shortest consonant skeleton belongs to: {key}\n"));
    Ok(out)
}

fn main() -> Result<(), Box<dyn Error>> {
    let data = [
        "greeting = Hello World",
        "vowels = aeiou",
        "mixed = Rust Is Quite Fun",
    ];
    let text = report(&data)?;
    print!("{text}");
    Ok(())
}

