use std::collections::HashMap;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, Clone)]
struct Student {
    name: String,
    grade: u8,
}

impl fmt::Display for Student {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:<8} {:>3}", self.name, self.grade)?;
        write!(f, " [{}]", letter(self.grade))
    }
}

fn create_student(name: String, grade: u8) -> Student {
    Student { name, grade }
}

fn letter(grade: u8) -> char {
    if grade >= 90 {
        'A'
    } else if grade >= 80 {
        'B'
    } else if grade >= 70 {
        'C'
    } else if grade >= 60 {
        'D'
    } else {
        'F'
    }
}

fn parse_grade(text: &str) -> Result<u8, String> {
    let value: u8 = text
        .trim()
        .parse()
        .map_err(|e: ParseIntError| format!("bad grade '{}': {}", text.trim(), e))?;
    if value > 100 {
        return Err(format!("grade {} is above 100", value));
    }
    Ok(value)
}

fn parse_student(record: &str) -> Result<Student, String> {
    let (name, grade) = record
        .split_once(',')
        .ok_or_else(|| format!("missing comma in '{}'", record))?;
    let name = name.trim();
    if name.is_empty() {
        return Err(format!("empty name in '{}'", record));
    }
    let grade = parse_grade(grade)?;
    Ok(create_student(name.to_string(), grade))
}

fn parse_roster(records: &[&str]) -> Result<Vec<Student>, String> {
    let mut roster = Vec::new();
    for record in records {
        roster.push(parse_student(record)?);
    }
    Ok(roster)
}

fn top_student(roster: &[Student]) -> Option<&Student> {
    roster.iter().max_by_key(|student| student.grade)
}

fn report(records: &[&str]) -> Result<String, String> {
    let roster = parse_roster(records)?;
    let mut counts: HashMap<char, usize> = HashMap::new();
    let mut lines = Vec::new();
    for student in &roster {
        *counts.entry(letter(student.grade)).or_insert(0) += 1;
        lines.push(student.to_string());
    }
    let best = top_student(&roster).ok_or("empty roster")?;
    lines.push(format!("top: {} with {}", best.name, best.grade));
    let mut grades: Vec<&char> = counts.keys().collect();
    grades.sort();
    for g in grades {
        lines.push(format!("{}: {}", g, counts[g]));
    }
    Ok(lines.join("\n"))
}

fn main() {
    let records = ["Alice, 90", "Bob, 75", "Cara, 61", "Dan, 88"];
    match report(&records) {
        Ok(text) => println!("{}", text),
        Err(e) => eprintln!("error: {}", e),
    }
}

