fn parse_numbers(spec: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for token in spec.split(',') {
        let trimmed = token.trim();
        let value = trimmed
            .parse::<i32>()
            .map_err(|e| format!("invalid number {:?}: {}", trimmed, e))?;
        values.push(value);
    }
    Ok(values)
}

fn find_second_largest(numbers: &[i32]) -> Option<i32> {
    let largest = numbers.iter().copied().max();
    largest.and_then(|top| numbers.iter().copied().filter(|&n| n < top).max())
}

fn top_two(numbers: &[i32]) -> Option<(i32, i32)> {
    let largest = numbers.iter().copied().max();
    largest.zip(find_second_largest(numbers))
}

fn describe(spec: &str) -> Result<String, String> {
    let numbers = parse_numbers(spec)?;
    let text = match top_two(&numbers) {
        Some((largest, second)) => format!(
            "[{}] -> largest {}, second largest {} (gap {})",
            spec.trim(),
            largest,
            second,
            largest - second
        ),
        None => format!("[{}] -> fewer than two distinct values", spec.trim()),
    };
    Ok(text)
}

fn runners_up(specs: &[&str]) -> Result<Vec<Option<i32>>, String> {
    let mut results = Vec::new();
    for spec in specs {
        let numbers = parse_numbers(spec)?;
        results.push(find_second_largest(&numbers));
    }
    Ok(results)
}

fn best_runner_up(specs: &[&str]) -> Result<Option<i32>, String> {
    let all = runners_up(specs)?;
    Ok(all.into_iter().flatten().max())
}

fn main() -> Result<(), String> {
    let specs = ["1, 5, 2, 8, 3", "7", "4, 4, 4", "-2, -9, -2, -30", "100, 99"];
    for spec in specs.iter() {
        println!("{}", describe(spec)?);
    }

    let found = runners_up(&specs)?.iter().filter(|e| e.is_some()).count();
    println!("{} of {} inputs have a second largest element", found, specs.len());

    match best_runner_up(&specs)? {
        Some(value) => println!("highest runner-up across all inputs: {}", value),
        None => println!("no input had a second largest element"),
    }
    Ok(())
}

