#[derive(Debug)]
enum InputError {
    Empty,
    BadDigits(ParseIntError),
    BadRange(String),
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::Empty => write!(f, "empty input token"),
            InputError::BadDigits(e) => write!(f, "not a valid u32: {}", e),
            InputError::BadRange(s) => write!(f, "malformed range: {}", s),
        }
    }
}

impl From<ParseIntError> for InputError {
    fn from(e: ParseIntError) -> Self {
        InputError::BadDigits(e)
    }
}

fn count_set_bits(n: u32) -> u32 {
    let mut value = n;
    let mut bits = 0;
    while value != 0 {
        value &= value - 1;
        bits += 1;
    }
    bits
}

fn parse_number(token: &str) -> Result<u32, InputError> {
    let t = token.trim();
    if t.is_empty() {
        return Err(InputError::Empty);
    }
    if let Some(hex) = t.strip_prefix("0x") {
        return Ok(u32::from_str_radix(hex, 16)?);
    }
    if let Some(bin) = t.strip_prefix("0b") {
        return Ok(u32::from_str_radix(bin, 2)?);
    }
    Ok(t.parse::<u32>()?)
}

