use std::fmt::Write as _;

/// Number of ordered outcomes of two six-sided dice that add up to `target_sum`.
fn ways_for(target_sum: u8) -> Option<u32> {
    if !(2..=12).contains(&target_sum) {
        return None;
    }
    let distance_from_seven = (i32::from(target_sum) - 7).abs();
    Some((6 - distance_from_seven) as u32)
}

/// Probability of rolling `target_sum` with two standard six-sided dice.
fn dice_sum_probability(target_sum: u8) -> f64 {
    f64::from(ways_for(target_sum).unwrap_or(0)) / 36.0
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

/// The same probability in lowest terms, e.g. 7 -> (1, 6).
fn fraction_for(target_sum: u8) -> Option<(u32, u32)> {
    let ways = ways_for(target_sum)?;
    let divisor = gcd(ways, 36);
    Some((ways / divisor, 36 / divisor))
}

fn parse_target(text: &str) -> Result<u8, String> {
    let value: u8 = text
        .trim()
        .parse()
        .map_err(|e| format!("{:?} is not a whole number: {}", text, e))?;
    ways_for(value).ok_or_else(|| format!("{} is not reachable with two dice", value))?;
    Ok(value)
}

fn render_row(target_sum: u8) -> Result<String, String> {
    let (numerator, denominator) = fraction_for(target_sum)
        .ok_or_else(|| format!("no outcomes sum to {}", target_sum))?;
    let mut row = String::new();
    write!(
        row,
        "{:>3} | {:>5} | {:>7.6}\n",
        target_sum,
        format!("{}/{}", numerator, denominator),
        dice_sum_probability(target_sum)
    )
    .map_err(|e| e.to_string())?;
    Ok(row)
}

fn render_table(targets: &[u8]) -> Result<String, String> {
    let mut table = String::new();
    writeln!(table, "sum | ratio | probability").map_err(|e| e.to_string())?;
    writeln!(table, "----+-------+------------").map_err(|e| e.to_string())?;
    for &target in targets {
        table.push_str(&render_row(target)?);
    }
    Ok(table)
}

fn collect_targets(args: Vec<String>) -> Result<Vec<u8>, String> {
    if args.is_empty() {
        return Ok((2..=12).collect());
    }
    let mut targets = Vec::with_capacity(args.len());
    for arg in &args {
        targets.push(parse_target(arg)?);
    }
    Ok(targets)
}

fn main() -> Result<(), String> {
    let targets = collect_targets(std::env::args().skip(1).collect())?;
    print!("{}", render_table(&targets)?);
    Ok(())
}

