use std::fmt::Write as _;

/// Removes the character at character index `n`, or returns `None` when the
/// index does not address a character of `s`.
fn remove_nth_char(s: &str, n: usize) -> Option<String> {
    let (start, ch) = match s.char_indices().nth(n) {
        Some(v) => v,
        None => return None,
    };
    let mut out = String::with_capacity(s.len() - ch.len_utf8());
    out.push_str(&s[..start]);
    out.push_str(&s[start + ch.len_utf8()..]);
    Some(out)
}

/// Removes several characters at once. Indices refer to the original string,
/// so they are applied from the highest to the lowest.
fn remove_indices(s: &str, indices: &[usize]) -> Option<String> {
    let mut sorted = indices.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    let mut current = s.to_string();
    for n in sorted {
        current = match remove_nth_char(&current, n) {
            Some(v) => v,
            None => return None,
        };
    }
    Some(current)
}

