use std::fmt::Write as _;

#[derive(Debug)]
struct Rectangle {
    width: f64,
    height: f64,
}

fn rectangle_perimeter(width: f64, height: f64) -> f64 {
    2.0 * (width + height)
}

fn parse_dimension(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|_| format!("`{}` is not a number", trimmed))?;
    if !value.is_finite() || value < 0.0 {
        return Err(format!("`{}` is not a valid side length", trimmed));
    }
    Ok(value)
}

fn parse_rectangle(spec: &str) -> Result<Rectangle, String> {
    let (left, right) = spec
        .split_once('x')
        .ok_or_else(|| format!("expected `WIDTHxHEIGHT`, got `{}`", spec.trim()))?;
    let width = parse_dimension(left)?;
    let height = parse_dimension(right)?;
    Ok(Rectangle { width, height })
}

fn perimeter_of_spec(spec: &str) -> Result<f64, String> {
    let rect = parse_rectangle(spec)?;
    Ok(rectangle_perimeter(rect.width, rect.height))
}

fn describe(spec: &str) -> Result<String, String> {
    let rect = parse_rectangle(spec)?;
    let mut line = String::new();
    write!(
        line,
        "{:>10} -> perimeter {:.2}",
        format!("{}x{}", rect.width, rect.height),
        rectangle_perimeter(rect.width, rect.height)
    )
    .map_err(|e| e.to_string())?;
    Ok(line)
}

fn total_perimeter(specs: &[&str]) -> Result<f64, String> {
    let mut sum = 0.0;
    for spec in specs {
        sum += perimeter_of_spec(spec)?;
    }
    Ok(sum)
}

fn report(specs: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    for spec in specs {
        out.push_str(&describe(spec)?);
        out.push('\n');
    }
    let total = total_perimeter(specs)?;
    writeln!(out, "{:>10} -> total {:.2}", "fence", total).map_err(|e| e.to_string())?;
    Ok(out)
}

fn main() -> Result<(), String> {
    let specs = ["5x3", " 0 x 10 ", "2.5x7.25", "12x12"];
    print!("{}", report(&specs)?);

    let single = perimeter_of_spec("5x3")?;
    println!("rectangle_perimeter(5.0, 3.0) = {}", single);

    match perimeter_of_spec("4x-1") {
        Ok(value) => println!("unexpected success: {}", value),
        Err(message) => println!("rejected input: {}", message),
    }
    Ok(())
}

