use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum InputError {
    Empty,
    NotANumber(ParseIntError),
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::Empty => write!(f, "empty field"),
            InputError::NotANumber(e) => write!(f, "not a positive integer: {}", e),
        }
    }
}

impl From<ParseIntError> for InputError {
    fn from(e: ParseIntError) -> Self {
        InputError::NotANumber(e)
    }
}

fn count_digits(n: u64) -> u8 {
    let mut digits = 1u8;
    let mut rest = n / 10;
    while rest > 0 {
        digits += 1;
        rest /= 10;
    }
    digits
}

fn parse_number(field: &str) -> Result<u64, InputError> {
    let trimmed = field.trim();
    if trimmed.is_empty() {
        return Err(InputError::Empty);
    }
    Ok(trimmed.parse::<u64>()?)
}

fn count_digits_of(field: &str) -> Result<u8, InputError> {
    Ok(count_digits(parse_number(field)?))
}

fn widest(csv: &str) -> Result<u64, InputError> {
    let mut best = parse_number(csv.split(',').next().unwrap_or(""))?;
    for field in csv.split(',').skip(1) {
        let value = parse_number(field)?;
        if count_digits(value) > count_digits(best) {
            best = value;
        }
    }
    Ok(best)
}

fn format_row(field: &str) -> Result<String, InputError> {
    let value = parse_number(field)?;
    Ok(format!("{:>12} -> {} digit(s)", value, count_digits(value)))
}

fn report(csv: &str) -> Result<String, InputError> {
    let mut out = String::new();
    for field in csv.split(',') {
        out.push_str(&format_row(field)?);
        out.push('\n');
    }
    let longest = widest(csv)?;
    out.push_str(&format!(
        "longest: {} with {} digit(s)\n",
        longest,
        count_digits(longest)
    ));
    Ok(out)
}

fn main() -> Result<(), InputError> {
    let csv = "12345, 0, 7, 1000000, 42";
    print!("{}", report(csv)?);
    println!("count_digits(12345) = {}", count_digits(12345));
    println!("count_digits(0) = {}", count_digits(0));
    println!("count_digits_of(\" 98765 \") = {}", count_digits_of(" 98765 ")?);
    Ok(())
}

