use std::fmt;

#[derive(Debug)]
enum ConfigError {
    MalformedLine(usize),
    EmptyKey(usize),
    EmptyValue(String),
    MissingKey(String),
    BadPort(String),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MalformedLine(n) => write!(f, "line {n}: expected key=value"),
            ConfigError::EmptyKey(n) => write!(f, "line {n}: key is empty"),
            ConfigError::EmptyValue(k) => write!(f, "value for '{k}' is empty"),
            ConfigError::MissingKey(k) => write!(f, "required key '{k}' is missing"),
            ConfigError::BadPort(v) => write!(f, "'{v}' is not a valid port"),
        }
    }
}

fn is_string_empty(s: &str) -> bool {
    s.is_empty()
}

fn split_entry(line: &str) -> Option<(&str, &str)> {
    let (key, value) = line.split_once('=')?;
    Some((key.trim(), value.trim()))
}

fn parse_entry(line: &str, number: usize) -> Result<(String, String), ConfigError> {
    let (key, value) = split_entry(line).ok_or(ConfigError::MalformedLine(number))?;
    if is_string_empty(key) {
        return Err(ConfigError::EmptyKey(number));
    }
    if is_string_empty(value) {
        return Err(ConfigError::EmptyValue(key.to_string()));
    }
    Ok((key.to_string(), value.to_string()))
}

fn parse_config(text: &str) -> Result<Vec<(String, String)>, ConfigError> {
    let mut entries = Vec::new();
    for (index, raw) in text.lines().enumerate() {
        let line = raw.trim();
        if is_string_empty(line) || line.starts_with('#') {
            continue;
        }
        entries.push(parse_entry(line, index + 1)?);
    }
    Ok(entries)
}

fn lookup<'a>(entries: &'a [(String, String)], key: &str) -> Option<&'a str> {
    let found = entries.iter().find(|(k, _)| k == key)?;
    Some(found.1.as_str())
}

fn get_required<'a>(entries: &'a [(String, String)], key: &str) -> Result<&'a str, ConfigError> {
    lookup(entries, key).ok_or_else(|| ConfigError::MissingKey(key.to_string()))
}

fn render_summary(entries: &[(String, String)]) -> Result<String, ConfigError> {
    let host = get_required(entries, "host")?;
    let raw_port = get_required(entries, "port")?;
    let port = raw_port
        .parse::<u16>()
        .map_err(|_| ConfigError::BadPort(raw_port.to_string()))?;
    let label = lookup(entries, "label").unwrap_or("unnamed");
    Ok(format!("{label}: {host}:{port}"))
}

fn main() -> Result<(), ConfigError> {
    let entries = parse_config("# service settings\nhost = example.org\nport = 8080\nlabel = gateway\n")?;
    println!("{}", render_summary(&entries)?);
    if let Err(err) = parse_config("host = example.org\nport =\n") {
        println!("rejected: {err}");
    }
    Ok(())
}

