use std::fmt::{self, Write as _};

#[derive(Debug)]
enum RuleError {
    MissingSeparator(String),
    MissingChar,
    NotSingleChar(String),
    Format(fmt::Error),
}

impl From<fmt::Error> for RuleError {
    fn from(e: fmt::Error) -> Self {
        RuleError::Format(e)
    }
}

impl fmt::Display for RuleError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RuleError::MissingSeparator(line) => write!(f, "rule {:?} has no '|' separator", line),
            RuleError::MissingChar => write!(f, "rule specifies no character to remove"),
            RuleError::NotSingleChar(field) => write!(f, "{:?} is not a single character", field),
            RuleError::Format(e) => write!(f, "formatting failure: {}", e),
        }
    }
}

