use std::collections::HashMap;
use std::fmt::Write as _;

fn convert_currency(amount: f64, exchange_rate: f64) -> f64 {
    amount * exchange_rate
}

struct RateTable {
    rates: HashMap<(String, String), f64>,
}

fn parse_rate_line(line: &str) -> Result<((String, String), f64), String> {
    let mut parts = line.split_whitespace();
    let from = parts.next().ok_or_else(|| format!("missing source currency in {:?}", line))?;
    let to = parts.next().ok_or_else(|| format!("missing target currency in {:?}", line))?;
    let rate_text = parts.next().ok_or_else(|| format!("missing rate in {:?}", line))?;
    let rate: f64 = rate_text.parse().map_err(|_| format!("bad rate {:?}", rate_text))?;
    if rate <= 0.0 {
        return Err(format!("rate for {}->{} must be positive", from, to));
    }
    Ok(((from.to_uppercase(), to.to_uppercase()), rate))
}

impl RateTable {
    fn from_lines(lines: &[&str]) -> Result<RateTable, String> {
        let mut rates = HashMap::new();
        for line in lines {
            let (pair, rate) = parse_rate_line(line)?;
            rates.insert(pair, rate);
        }
        Ok(RateTable { rates })
    }

    fn rate(&self, from: &str, to: &str) -> Result<f64, String> {
        let key = (from.to_uppercase(), to.to_uppercase());
        if let Some(rate) = self.rates.get(&key) {
            return Ok(*rate);
        }
        let inverse = self.rates.get(&(key.1.clone(), key.0.clone()));
        let rate = inverse.ok_or_else(|| format!("no rate known for {}->{}", from, to))?;
        Ok(1.0 / rate)
    }

    fn convert(&self, amount: f64, from: &str, to: &str) -> Result<f64, String> {
        if amount < 0.0 {
            return Err(format!("amount {} is negative", amount));
        }
        let rate = self.rate(from, to)?;
        Ok(convert_currency(amount, rate))
    }
}

fn parse_request(line: &str) -> Result<(f64, String, String), String> {
    let mut parts = line.split_whitespace();
    let amount_text = parts.next().ok_or_else(|| format!("empty request {:?}", line))?;
    let amount: f64 = amount_text.parse().map_err(|_| format!("bad amount {:?}", amount_text))?;
    let from = parts.next().ok_or_else(|| format!("missing source currency in {:?}", line))?;
    let to = parts.next().ok_or_else(|| format!("missing target currency in {:?}", line))?;
    Ok((amount, from.to_string(), to.to_string()))
}

fn report(table: &RateTable, request: &str) -> Result<String, String> {
    let (amount, from, to) = parse_request(request)?;
    let converted = table.convert(amount, &from, &to)?;
    let mut out = String::new();
    write!(out, "{:.2} {} = {:.2} {}", amount, from.to_uppercase(), converted, to.to_uppercase())
        .map_err(|e| e.to_string())?;
    Ok(out)
}

fn main() -> Result<(), String> {
    let table = RateTable::from_lines(&["USD EUR 1.18", "EUR GBP 0.85", "GBP JPY 155.0"])?;
    for request in ["100 USD EUR", "50 EUR GBP", "20 GBP JPY", "10 EUR USD"] {
        println!("{}", report(&table, request)?);
    }
    match report(&table, "5 USD CHF") {
        Ok(line) => println!("{}", line),
        Err(err) => println!("error: {}", err),
    }
    Ok(())
}

