fn count_substring_occurrences(text: &str, pattern: &str) -> usize {
    if pattern.is_empty() {
        return 0; // Or handle as an error, but 0 is a common convention for empty pattern.
    }

    let mut count = 0;
    let mut start_index = 0;

    while let Some(index) = text[start_index..].find(pattern) {
        count += 1;
        start_index += index + pattern.len();
    }
    count
}

