use std::fmt;

#[derive(Debug)]
enum ParseError {
    NotANumber(String),
    NotPositive,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::NotANumber(text) => write!(f, "`{}` is not a whole number", text),
            ParseError::NotPositive => write!(f, "a perfect number must be positive"),
        }
    }
}

fn parse_number(text: &str) -> Result<u32, ParseError> {
    let trimmed = text.trim();
    let value = trimmed
        .parse::<u32>()
        .map_err(|_| ParseError::NotANumber(trimmed.to_string()))?;
    if value == 0 {
        return Err(ParseError::NotPositive);
    }
    Ok(value)
}

fn proper_divisors(n: u32) -> Vec<u32> {
    let mut divisors = Vec::new();
    let mut d = 1;
    while d * d <= n {
        if n % d == 0 {
            divisors.push(d);
            let partner = n / d;
            if partner != d && partner != n {
                divisors.push(partner);
            }
        }
        d += 1;
    }
    divisors.retain(|&x| x != n);
    divisors.sort_unstable();
    divisors
}

fn is_perfect_number(n: u32) -> bool {
    n > 0 && proper_divisors(n).iter().sum::<u32>() == n
}

fn describe(text: &str) -> Result<String, ParseError> {
    let n = parse_number(text)?;
    let divisors = proper_divisors(n);
    let parts: Vec<String> = divisors.iter().map(|d| d.to_string()).collect();
    let sum: u32 = divisors.iter().sum();
    let verdict = if is_perfect_number(n) { "perfect" } else { "not perfect" };
    Ok(format!("{}: {} = {} -> {}", n, parts.join(" + "), sum, verdict))
}

fn report(lines: &[&str]) -> Result<String, ParseError> {
    let mut out = String::new();
    for line in lines {
        out.push_str(&describe(line)?);
        out.push('\n');
    }
    Ok(out)
}

fn perfect_numbers_up_to(limit_text: &str) -> Result<Vec<u32>, ParseError> {
    let limit = parse_number(limit_text)?;
    Ok((1..=limit).filter(|&n| is_perfect_number(n)).collect())
}

fn summary_line(limit_text: &str) -> Result<String, ParseError> {
    let found = perfect_numbers_up_to(limit_text)?;
    let listed: Vec<String> = found.iter().map(|n| n.to_string()).collect();
    Ok(format!("perfect numbers up to {}: {}", limit_text.trim(), listed.join(", ")))
}

fn main() -> Result<(), ParseError> {
    print!("{}", report(&["6", "10", "28", " 496 "])?);
    let limit = std::env::args().nth(1).unwrap_or_else(|| "10000".to_string());
    println!("{}", summary_line(&limit)?);
    Ok(())
}

