use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug, Clone, Copy, PartialEq)]
struct Point {
    x: f64,
    y: f64,
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({:.3}, {:.3})", self.x, self.y)
    }
}

fn create_point(x: f64, y: f64) -> Point {
    Point { x, y }
}

fn parse_point(spec: &str) -> Result<Point, String> {
    let trimmed = spec.trim().trim_start_matches('(').trim_end_matches(')');
    let (left, right) = trimmed
        .split_once(',')
        .ok_or_else(|| format!("missing comma in {:?}", spec))?;
    let x = parse_coord(left)?;
    let y = parse_coord(right)?;
    Ok(create_point(x, y))
}

fn parse_coord(field: &str) -> Result<f64, String> {
    let text = field.trim();
    let value: f64 = text
        .parse()
        .map_err(|e: ParseFloatError| format!("bad coordinate {:?}: {}", text, e))?;
    if value.is_finite() {
        Ok(value)
    } else {
        Err(format!("coordinate {:?} is not finite", text))
    }
}

fn parse_polyline(specs: &[&str]) -> Result<Vec<Point>, String> {
    let mut points = Vec::with_capacity(specs.len());
    for spec in specs {
        points.push(parse_point(spec)?);
    }
    Ok(points)
}

fn distance(a: Point, b: Point) -> f64 {
    ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt()
}

fn polyline_length(specs: &[&str]) -> Result<f64, String> {
    let points = parse_polyline(specs)?;
    let first = points.first().ok_or("polyline needs at least one point")?;
    let mut total = 0.0;
    let mut previous = *first;
    for current in points.iter().skip(1) {
        total += distance(previous, *current);
        previous = *current;
    }
    Ok(total)
}

fn centroid(specs: &[&str]) -> Result<Point, String> {
    let points = parse_polyline(specs)?;
    let count = points.len();
    if count == 0 {
        return Err("centroid of an empty point set is undefined".to_string());
    }
    let sum = points
        .iter()
        .fold(create_point(0.0, 0.0), |acc, p| create_point(acc.x + p.x, acc.y + p.y));
    Ok(create_point(sum.x / count as f64, sum.y / count as f64))
}

fn report(specs: &[&str]) -> Result<String, String> {
    let middle = centroid(specs)?;
    let length = polyline_length(specs)?;
    Ok(format!("centroid {} length {:.3}", middle, length))
}

fn main() {
    let origin = create_point(0.0, 0.0);
    let corner = create_point(1.0, 2.0);
    println!("{} -> {} is {:.3} long", origin, corner, distance(origin, corner));

    let path = ["(0,0)", "3, 4", "(3, 0)"];
    match report(&path) {
        Ok(line) => println!("{}", line),
        Err(e) => eprintln!("error: {}", e),
    }
    match report(&["(1, oops)"]) {
        Ok(line) => println!("{}", line),
        Err(e) => eprintln!("error: {}", e),
    }
}

