use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ReportError {
    MissingLabel(String),
    BadNumber(ParseIntError),
}

impl fmt::Display for ReportError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ReportError::MissingLabel(line) => write!(f, "missing ':' in line {line:?}"),
            ReportError::BadNumber(e) => write!(f, "bad number: {e}"),
        }
    }
}

impl From<ParseIntError> for ReportError {
    fn from(e: ParseIntError) -> Self {
        ReportError::BadNumber(e)
    }
}

fn is_sorted_ascending(numbers: &[i32]) -> bool {
    numbers.windows(2).all(|pair| pair[0] <= pair[1])
}

fn first_descent(numbers: &[i32]) -> Option<usize> {
    (0..numbers.len().saturating_sub(1)).find(|&i| numbers[i] > numbers[i + 1])
}

fn parse_numbers(list: &str) -> Result<Vec<i32>, ReportError> {
    let mut parsed = Vec::new();
    for token in list.split(',') {
        parsed.push(token.trim().parse::<i32>()?);
    }
    Ok(parsed)
}

fn parse_labeled(line: &str) -> Result<(&str, Vec<i32>), ReportError> {
    let (label, list) = line
        .split_once(':')
        .ok_or_else(|| ReportError::MissingLabel(line.to_string()))?;
    let numbers = parse_numbers(list)?;
    Ok((label.trim(), numbers))
}

fn describe(line: &str) -> Result<String, ReportError> {
    let (label, numbers) = parse_labeled(line)?;
    match first_descent(&numbers) {
        Some(i) => Ok(format!(
            "{label}: not sorted, {} > {} at index {i}",
            numbers[i],
            numbers[i + 1]
        )),
        None => Ok(format!(
            "{label}: sorted ascending ({} values)",
            numbers.len()
        )),
    }
}

fn report(input: &str) -> Result<String, ReportError> {
    let mut out = String::new();
    let mut sorted = 0;
    let mut total = 0;
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        let (_, numbers) = parse_labeled(line)?;
        total += 1;
        if is_sorted_ascending(&numbers) {
            sorted += 1;
        }
        out.push_str(&describe(line)?);
        out.push('\n');
    }
    out.push_str(&format!("{sorted} of {total} lists are ascending\n"));
    Ok(out)
}

fn main() -> Result<(), ReportError> {
    let data = "ascending: 1, 2, 3, 4\nmixed: 1, 3, 2\nplateau: 5, 5, 7\nsingle: 42";
    print!("{}", report(data)?);
    Ok(())
}

