use std::mem;

/// Swaps the values held by two mutable references, in place.
fn swap_values<T>(a: &mut T, b: &mut T) {
    mem::swap(a, b);
}

/// Swaps the first and last element of a slice; `None` if the slice is empty.
fn swap_ends<T>(items: &mut [T]) -> Option<()> {
    let (first, rest) = items.split_first_mut()?;
    if let Some(last) = rest.last_mut() {
        swap_values(first, last);
    }
    Some(())
}

fn parse_pair(text: &str) -> Result<(i64, i64), String> {
    let mut fields = text.split_whitespace();
    let left = fields.next().ok_or_else(|| format!("no first value in {:?}", text))?;
    let right = fields.next().ok_or_else(|| format!("no second value in {:?}", text))?;
    let a = left.parse::<i64>().map_err(|e| format!("{:?}: {}", left, e))?;
    let b = right.parse::<i64>().map_err(|e| format!("{:?}: {}", right, e))?;
    Ok((a, b))
}

/// Reads "a b", swaps the two numbers and renders the result.
fn swapped_pair_line(text: &str) -> Result<String, String> {
    let (mut a, mut b) = parse_pair(text)?;
    swap_values(&mut a, &mut b);
    Ok(format!("{} {}", a, b))
}

fn parse_list(text: &str) -> Result<Vec<i64>, String> {
    let mut values = Vec::new();
    for token in text.split_whitespace() {
        values.push(token.parse::<i64>().map_err(|e| format!("{:?}: {}", token, e))?);
    }
    Ok(values)
}

/// Bubble sort built entirely out of `swap_values`.
fn sort_by_swapping<T: PartialOrd>(items: &mut [T]) {
    for end in (1..items.len()).rev() {
        for i in 0..end {
            if items[i] > items[i + 1] {
                let (head, tail) = items.split_at_mut(i + 1);
                swap_values(&mut head[i], &mut tail[0]);
            }
        }
    }
}

fn median(text: &str) -> Result<f64, String> {
    let mut values = parse_list(text)?;
    sort_by_swapping(&mut values);
    let mid = values.len() / 2;
    let high = *values.get(mid).ok_or("median of an empty list")?;
    if values.len() % 2 == 1 {
        return Ok(high as f64);
    }
    Ok((values[mid - 1] + high) as f64 / 2.0)
}

fn main() -> Result<(), String> {
    let mut x = 1;
    let mut y = 2;
    swap_values(&mut x, &mut y);
    println!("x = {}, y = {}", x, y);

    let mut s1 = "a".to_string();
    let mut s2 = "b".to_string();
    swap_values(&mut s1, &mut s2);
    println!("s1 = {}, s2 = {}", s1, s2);

    for line in ["3 7", "-1 41"] {
        println!("swapped pair: {}", swapped_pair_line(line)?);
    }

    let data = "5 3 9 1 7 2";
    let mut values = parse_list(data)?;
    sort_by_swapping(&mut values);
    swap_ends(&mut values).ok_or("cannot swap the ends of an empty list")?;
    println!("sorted with ends swapped: {:?}", values);
    println!("median: {}", median(data)?);

    let mut words: Vec<String> = "pear apple fig".split_whitespace().map(String::from).collect();
    sort_by_swapping(&mut words);
    swap_ends(&mut words).ok_or("cannot swap the ends of an empty list")?;
    println!("words: {:?}", words);
    Ok(())
}

