use std::fmt::{self, Write};

#[derive(Debug)]
enum AsciiError {
    NotAscii(char),
    BadCode(String),
    Format(fmt::Error),
}

impl fmt::Display for AsciiError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AsciiError::NotAscii(c) => write!(f, "character {:?} is outside the ASCII range", c),
            AsciiError::BadCode(t) => write!(f, "{:?} is not a decimal byte value", t),
            AsciiError::Format(e) => write!(f, "formatting failure: {}", e),
        }
    }
}

fn char_to_ascii(c: char) -> u8 {
    c as u8
}

fn checked_char_to_ascii(c: char) -> Result<u8, AsciiError> {
    if c.is_ascii() {
        Ok(char_to_ascii(c))
    } else {
        Err(AsciiError::NotAscii(c))
    }
}

fn encode_ascii(text: &str) -> Result<Vec<u8>, AsciiError> {
    let mut codes = Vec::with_capacity(text.len());
    for c in text.chars() {
        let code = checked_char_to_ascii(c)?;
        codes.push(code);
    }
    Ok(codes)
}

fn parse_code(token: &str) -> Result<u8, AsciiError> {
    let value: u32 = token
        .parse()
        .map_err(|_| AsciiError::BadCode(token.to_string()))?;
    let c = char::from_u32(value).ok_or_else(|| AsciiError::BadCode(token.to_string()))?;
    checked_char_to_ascii(c)
}

fn decode_codes(spec: &str) -> Result<String, AsciiError> {
    let mut text = String::new();
    for token in spec.split_whitespace() {
        let code = parse_code(token)?;
        text.push(code as char);
    }
    Ok(text)
}

fn hex_dump(text: &str) -> Result<String, AsciiError> {
    let codes = encode_ascii(text)?;
    let mut out = String::new();
    for code in codes {
        write!(&mut out, "{:02X} ", code).map_err(AsciiError::Format)?;
    }
    Ok(out.trim_end().to_string())
}

fn table(text: &str) -> Result<String, AsciiError> {
    let mut out = String::new();
    for c in text.chars() {
        let code = checked_char_to_ascii(c)?;
        writeln!(&mut out, "{:>4}  {:3}  0x{:02X}", c, code, code).map_err(AsciiError::Format)?;
    }
    Ok(out)
}

fn main() -> Result<(), AsciiError> {
    println!("'A' -> {}", char_to_ascii('A'));
    println!("'a' -> {}", char_to_ascii('a'));
    let rendered = table("Hi!")?;
    print!("{}", rendered);
    let dump = hex_dump("Rust")?;
    println!("hex: {}", dump);
    let decoded = decode_codes("82 111 115 101")?;
    println!("decoded: {}", decoded);
    let codes = encode_ascii(&decoded)?;
    println!("re-encoded: {:?}", codes);
    Ok(())
}

