/// Parses one endpoint of a range specification such as `"-3"`.
fn parse_bound(text: &str) -> Result<i32, String> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err("missing endpoint".to_string());
    }
    let value = trimmed
        .parse::<i32>()
        .map_err(|e| format!("bad endpoint `{}`: {}", trimmed, e))?;
    Ok(value)
}

/// Splits a specification of the form `"start..end"` into its two endpoints.
fn parse_spec(spec: &str) -> Result<(i32, i32), String> {
    let (left, right) = spec
        .split_once("..")
        .ok_or_else(|| format!("`{}` is not of the form start..end", spec))?;
    let start = parse_bound(left)?;
    let end = parse_bound(right)?;
    Ok((start, end))
}

/// Generates every integer from `start` to `end`, inclusive.
fn generate_range(start: i32, end: i32) -> Vec<i32> {
    if start > end {
        return Vec::new();
    }
    let mut values = Vec::with_capacity((end - start + 1) as usize);
    let mut current = start;
    while current < end {
        values.push(current);
        current += 1;
    }
    values.push(end);
    values
}

fn range_from_spec(spec: &str) -> Result<Vec<i32>, String> {
    let (start, end) = parse_spec(spec)?;
    Ok(generate_range(start, end))
}

/// Expands a comma-separated list of specifications into one range each.
fn ranges_from_line(line: &str) -> Result<Vec<Vec<i32>>, String> {
    let mut ranges = Vec::new();
    for part in line.split(',') {
        ranges.push(range_from_spec(part.trim())?);
    }
    Ok(ranges)
}

fn summary(spec: &str) -> Result<String, String> {
    let values = range_from_spec(spec)?;
    let first = *values
        .first()
        .ok_or_else(|| format!("range `{}` is empty", spec))?;
    let last = values[values.len() - 1];
    let midpoint = first + (last - first) / 2;
    let listed = values
        .iter()
        .map(|value| value.to_string())
        .collect::<Vec<String>>()
        .join(", ");
    Ok(format!(
        "{:>10} -> [{}] (count {}, midpoint {})",
        spec,
        listed,
        values.len(),
        midpoint
    ))
}

fn main() -> Result<(), String> {
    let line = "1..5, 5..1, -3..3, 7..7";
    for spec in line.split(',') {
        let spec = spec.trim();
        match summary(spec) {
            Ok(text) => println!("{}", text),
            Err(message) => println!("{:>10} -> {}", spec, message),
        }
    }
    let total: usize = ranges_from_line(line)?.iter().map(Vec::len).sum();
    println!("{} integers generated in total", total);
    Ok(())
}

