use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum PowError {
    BadSyntax(String),
    BadNumber(ParseIntError),
    Overflow { base: u32, exponent: u32 },
    SumOverflow,
}

impl From<ParseIntError> for PowError {
    fn from(err: ParseIntError) -> Self {
        PowError::BadNumber(err)
    }
}

impl fmt::Display for PowError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PowError::BadSyntax(s) => write!(f, "expected 'base^exponent', got '{}'", s),
            PowError::BadNumber(e) => write!(f, "invalid number: {}", e),
            PowError::Overflow { base, exponent } => {
                write!(f, "{}^{} does not fit in a u32", base, exponent)
            }
            PowError::SumOverflow => write!(f, "sum of results does not fit in a u32"),
        }
    }
}

fn checked_integer_power(base: u32, exponent: u32) -> Result<u32, PowError> {
    let mut acc: u32 = 1;
    for _ in 0..exponent {
        acc = acc
            .checked_mul(base)
            .ok_or(PowError::Overflow { base, exponent })?;
    }
    Ok(acc)
}

fn integer_power(base: u32, exponent: u32) -> u32 {
    checked_integer_power(base, exponent).expect("power overflows u32")
}

fn parse_expression(text: &str) -> Result<(u32, u32), PowError> {
    let (left, right) = text
        .split_once('^')
        .ok_or_else(|| PowError::BadSyntax(text.to_string()))?;
    let base: u32 = left.trim().parse()?;
    let exponent: u32 = right.trim().parse()?;
    Ok((base, exponent))
}

fn evaluate(text: &str) -> Result<u32, PowError> {
    let (base, exponent) = parse_expression(text)?;
    checked_integer_power(base, exponent)
}

fn format_line(text: &str) -> Result<String, PowError> {
    let value = evaluate(text)?;
    Ok(format!("{} = {}", text.trim(), value))
}

fn total(expressions: &[&str]) -> Result<u32, PowError> {
    let mut sum: u32 = 0;
    for expr in expressions {
        let value = evaluate(expr)?;
        sum = sum.checked_add(value).ok_or(PowError::SumOverflow)?;
    }
    Ok(sum)
}

fn run(expressions: &[&str]) -> Result<(), PowError> {
    for expr in expressions {
        println!("{}", format_line(expr)?);
    }
    println!("total = {}", total(expressions)?);
    Ok(())
}

fn main() {
    println!("integer_power(2, 3) = {}", integer_power(2, 3));
    println!("integer_power(5, 0) = {}", integer_power(5, 0));

    let expressions = ["2^10", "3^4", "7^2", "1^31"];
    if let Err(err) = run(&expressions) {
        eprintln!("error: {}", err);
    }

    match evaluate("2^40") {
        Ok(value) => println!("2^40 = {}", value),
        Err(err) => eprintln!("error: {}", err),
    }
}

