use std::fmt::Write as _;
use std::num::ParseIntError;

fn flatten_vector(nested_vec: Vec<Vec<i32>>) -> Vec<i32> {
    nested_vec.into_iter().flatten().collect()
}

fn parse_row(row: &str) -> Result<Vec<i32>, ParseIntError> {
    let mut values = Vec::new();
    for token in row.split(',') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        values.push(token.parse::<i32>()?);
    }
    Ok(values)
}

fn parse_nested(text: &str) -> Result<Vec<Vec<i32>>, ParseIntError> {
    let mut rows = Vec::new();
    for line in text.lines() {
        rows.push(parse_row(line)?);
    }
    Ok(rows)
}

fn flatten_text(text: &str) -> Result<Vec<i32>, ParseIntError> {
    Ok(flatten_vector(parse_nested(text)?))
}

fn format_flat(values: &[i32]) -> Result<String, std::fmt::Error> {
    let mut out = String::from("[");
    for (index, value) in values.iter().enumerate() {
        if index > 0 {
            out.push_str(", ");
        }
        write!(out, "{}", value)?;
    }
    out.push(']');
    Ok(out)
}

fn report(text: &str) -> Result<String, Box<dyn std::error::Error>> {
    let nested = parse_nested(text)?;
    let row_count = nested.len();
    let flat = flatten_vector(nested);
    let mut summary = format_flat(&flat)?;
    write!(summary, " ({} rows -> {} items)", row_count, flat.len())?;
    Ok(summary)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("{}", format_flat(&flatten_vector(vec![vec![1, 2], vec![3, 4]]))?);
    println!("{}", format_flat(&flatten_vector(vec![vec![], vec![5]]))?);

    let input = "1, 2, 3\n\n4, 5\n6";
    let flat = flatten_text(input)?;
    println!("{}", format_flat(&flat)?);
    println!("{}", report(input)?);

    match flatten_text("7, eight, 9") {
        Ok(values) => println!("{}", format_flat(&values)?),
        Err(err) => println!("could not parse input: {}", err),
    }

    Ok(())
}

