fn ends_with(text: &str, suffix: &str) -> bool {
    let text_len = text.len();
    let suffix_len = suffix.len();

    if suffix_len > text_len {
        return false;
    }

    let start_index = text_len - suffix_len;
    let text_suffix = text.get(start_index..).expect("text.get should not fail given the bounds check");

    text_suffix == suffix
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ends_with_true() {
        assert!(ends_with("hello world", "world"));
    }

    #[test]
    fn test_ends_with_false() {
        assert!(!ends_with("hello world", "earth"));
    }

    #[test]
    fn test_ends_with_empty_suffix() {
        assert!(ends_with("hello world", ""));
    }

    #[test]
    fn test_ends_with_empty_text() {
        assert!(ends_with("", ""));
    }

    #[test]
    fn test_ends_with_empty_text_non_empty_suffix() {
        assert!(!ends_with("", "a"));
    }

    #[test]
    fn test_ends_with_suffix_longer_than_text() {
        assert!(!ends_with("hi", "hello"));
    }

    #[test]
    fn test_ends_with_full_match() {
        assert!(ends_with("rust", "rust"));
    }

    #[test]
    fn test_ends_with_partial_match_false() {
        assert!(!ends_with("testing", "testx"));
    }

    #[test]
    fn test_ends_with_unicode() {
        assert!(ends_with("你好世界", "世界"));
    }
}

