    celsius + 273.15
}

// Below is a contrived example to demonstrate error propagation with '?',
// as the original task was too simple to naturally require it.
// This part is not directly related to the celsius_to_kelvin function itself.

use std::fs::File;
use std::io::{self, Read, Write};
use std::path::Path;

fn read_and_convert_temperature_from_file(file_path: &Path) -> Result<f64, io::Error> {
    let mut file = File::open(file_path)?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    let celsius_str = contents.trim();
    let celsius: f64 = celsius_str.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    Ok(celsius_to_kelvin(celsius))
