use rand::Rng;
use std::fmt::{self, Write};
use std::num::ParseIntError;

#[derive(Debug)]
enum RangeError {
    Syntax(String),
    Number(ParseIntError),
    Empty(i32, i32),
    NoSamples,
    Format(fmt::Error),
}

impl fmt::Display for RangeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RangeError::Syntax(s) => write!(f, "cannot read range specification '{}'", s),
            RangeError::Number(e) => write!(f, "bad bound: {}", e),
            RangeError::Empty(a, b) => write!(f, "empty range [{}, {}]", a, b),
            RangeError::NoSamples => write!(f, "no samples were drawn"),
            RangeError::Format(e) => write!(f, "report formatting failed: {}", e),
        }
    }
}

impl From<ParseIntError> for RangeError {
    fn from(e: ParseIntError) -> Self {
        RangeError::Number(e)
    }
}

impl From<fmt::Error> for RangeError {
    fn from(e: fmt::Error) -> Self {
        RangeError::Format(e)
    }
}

fn parse_range(spec: &str) -> Result<(i32, i32), RangeError> {
    let (lo, hi) = spec
        .split_once("..")
        .ok_or_else(|| RangeError::Syntax(spec.to_string()))?;
    let min: i32 = lo.trim().parse()?;
    let max: i32 = hi.trim().parse()?;
    check_range(min, max)?;
    Ok((min, max))
}

fn check_range(min: i32, max: i32) -> Result<(), RangeError> {
    if min > max {
        return Err(RangeError::Empty(min, max));
    }
    Ok(())
}

fn generate_random_int(min: i32, max: i32) -> i32 {
    rand::thread_rng().gen_range(min..=max)
}

fn sample_spec(spec: &str, count: usize) -> Result<Vec<i32>, RangeError> {
    let (min, max) = parse_range(spec)?;
    Ok((0..count).map(|_| generate_random_int(min, max)).collect())
}

fn observed_bounds(values: &[i32]) -> Result<(i32, i32), RangeError> {
    let lo = *values.iter().min().ok_or(RangeError::NoSamples)?;
    let hi = values.iter().copied().fold(lo, i32::max);
    Ok((lo, hi))
}

fn report(spec: &str, count: usize) -> Result<String, RangeError> {
    let values = sample_spec(spec, count)?;
    let (lo, hi) = observed_bounds(&values)?;
    let mut out = String::new();
    writeln!(out, "range {}: {} draws", spec, values.len())?;
    writeln!(out, "  values   {:?}", values)?;
    writeln!(out, "  observed [{}, {}]", lo, hi)?;
    Ok(out)
}

fn main() -> Result<(), RangeError> {
    let specs: Vec<String> = std::env::args().skip(1).collect();
    let specs = if specs.is_empty() {
        vec!["1..10".to_string(), "5..5".to_string(), "-3..3".to_string()]
    } else {
        specs
    };
    for spec in &specs {
        print!("{}", report(spec, 12)?);
    }
    let (min, max) = parse_range(&specs[0])?;
    println!("single draw from {}..{}: {}", min, max, generate_random_int(min, max));
    Ok(())
}

