use std::env;
use std::fmt::{self, Write as _};
use std::num::ParseFloatError;

#[derive(Debug)]
enum RadiusError {
    Parse(ParseFloatError),
    Negative(f64),
    NotFinite,
    Format(fmt::Error),
}

impl From<ParseFloatError> for RadiusError {
    fn from(e: ParseFloatError) -> Self {
        RadiusError::Parse(e)
    }
}

impl From<fmt::Error> for RadiusError {
    fn from(e: fmt::Error) -> Self {
        RadiusError::Format(e)
    }
}

impl fmt::Display for RadiusError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RadiusError::Parse(e) => write!(f, "not a number: {}", e),
            RadiusError::Negative(r) => write!(f, "radius must not be negative: {}", r),
            RadiusError::NotFinite => write!(f, "radius must be finite"),
            RadiusError::Format(e) => write!(f, "formatting failed: {}", e),
        }
    }
}

fn sphere_volume(radius: f64) -> f64 {
    4.0 / 3.0 * std::f64::consts::PI * radius * radius * radius
}

fn parse_radius(text: &str) -> Result<f64, RadiusError> {
    let radius: f64 = text.trim().parse()?;
    if !radius.is_finite() {
        return Err(RadiusError::NotFinite);
    }
    if radius < 0.0 {
        return Err(RadiusError::Negative(radius));
    }
    Ok(radius)
}

fn volume_from_str(text: &str) -> Result<f64, RadiusError> {
    Ok(sphere_volume(parse_radius(text)?))
}

fn describe(text: &str) -> Result<String, RadiusError> {
    let radius = parse_radius(text)?;
    let mut line = String::new();
    writeln!(line, "r = {:<8} -> V = {}", radius, sphere_volume(radius))?;
    Ok(line)
}

fn total_volume(inputs: &[String]) -> Result<f64, RadiusError> {
    let mut sum = 0.0;
    for text in inputs {
        sum += volume_from_str(text)?;
    }
    Ok(sum)
}

fn build_report(inputs: &[String]) -> Result<String, RadiusError> {
    let mut report = String::new();
    for text in inputs {
        report.push_str(&describe(text)?);
    }
    let total = total_volume(inputs)?;
    writeln!(report, "combined volume = {}", total)?;
    Ok(report)
}

fn main() -> Result<(), RadiusError> {
    let mut inputs: Vec<String> = env::args().skip(1).collect();
    if inputs.is_empty() {
        inputs = vec!["1.0".to_string(), "3.0".to_string()];
    }
    print!("{}", build_report(&inputs)?);
    Ok(())
}

