use std::fs::{self, File};
use std::io::{self, Read};
use std::path::{Path, PathBuf};

/// Counts the lines in a multi-line string. The final line does not need a
/// trailing `\n`; an empty string contains no lines at all.
fn count_lines(text: &str) -> usize {
    if text.is_empty() {
        0
    } else {
        text.lines().count()
    }
}

fn load_text(path: &Path) -> io::Result<String> {
    let mut file = File::open(path)?;
    let mut buffer = String::new();
    file.read_to_string(&mut buffer)?;
    Ok(buffer)
}

fn count_lines_in_file(path: &Path) -> io::Result<usize> {
    let text = load_text(path)?;
    Ok(count_lines(&text))
}

fn nth_line(text: &str, n: usize) -> Option<&str> {
    text.lines().nth(n.checked_sub(1)?)
}

fn longest_line(text: &str) -> Option<&str> {
    text.lines().max_by_key(|line| line.chars().count())
}

/// Parses a `path:line-number` locator, as used on the command line.
fn parse_line_spec(spec: &str) -> Result<(PathBuf, usize), String> {
    let (path, number) = spec
        .rsplit_once(':')
        .ok_or_else(|| format!("missing line number in {:?}", spec))?;
    let index: usize = number
        .trim()
        .parse()
        .map_err(|e| format!("bad line number {:?}: {}", number, e))?;
    if index == 0 {
        return Err("line numbers start at 1".to_string());
    }
    Ok((PathBuf::from(path), index))
}

fn extract_line(spec: &str) -> Result<String, String> {
    let (path, index) = parse_line_spec(spec)?;
    let text = load_text(&path).map_err(|e| format!("{}: {}", path.display(), e))?;
    let line = nth_line(&text, index)
        .ok_or_else(|| format!("{} has only {} line(s)", path.display(), count_lines(&text)))?;
    Ok(line.to_string())
}

fn report(text: &str) -> Option<String> {
    let first = nth_line(text, 1)?;
    let widest = longest_line(text)?;
    Some(format!(
        "{} line(s); first {:?}; longest {:?} ({} chars)",
        count_lines(text),
        first,
        widest,
        widest.chars().count()
    ))
}

fn main() -> Result<(), String> {
    println!("{}", count_lines("hello\nworld"));
    println!("{}", count_lines("single line"));

    let path = std::env::temp_dir().join("count_lines_sample.txt");
    fs::write(&path, "alpha\nbeta gamma delta\nepsilon\n").map_err(|e| e.to_string())?;

    let total = count_lines_in_file(&path).map_err(|e| e.to_string())?;
    println!("{} contains {} line(s)", path.display(), total);

    let spec = format!("{}:2", path.display());
    println!("line 2 is {:?}", extract_line(&spec)?);

    let text = load_text(&path).map_err(|e| e.to_string())?;
    let summary = report(&text).ok_or("file contains no lines")?;
    println!("{}", summary);
    Ok(())
}

