use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
enum ConfigError {
    MissingSeparator(String),
    MissingKey(String),
    BadNumber { key: String, value: String },
    BadFlag { key: String, value: String },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingSeparator(line) => write!(f, "no '=' in line: {}", line),
            ConfigError::MissingKey(key) => write!(f, "required key missing: {}", key),
            ConfigError::BadNumber { key, value } => {
                write!(f, "key {} has non-numeric value {:?}", key, value)
            }
            ConfigError::BadFlag { key, value } => {
                write!(f, "key {} has non-boolean value {:?}", key, value)
            }
        }
    }
}

fn parse_line(line: &str) -> Result<(String, String), ConfigError> {
    let (key, value) = line
        .split_once('=')
        .ok_or_else(|| ConfigError::MissingSeparator(line.to_string()))?;
    Ok((key.trim().to_string(), value.trim().to_string()))
}

fn parse_config(text: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for line in text
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
    {
        let (key, value) = parse_line(line)?;
        map.insert(key, value);
    }
    Ok(map)
}

fn get_from_map(map: &HashMap<String, String>, key: &str) -> String {
    map.get(key)
        .cloned()
        .unwrap_or_else(|| "NOT_FOUND".to_string())
}

fn require<'a>(map: &'a HashMap<String, String>, key: &str) -> Result<&'a String, ConfigError> {
    map.get(key).ok_or_else(|| ConfigError::MissingKey(key.to_string()))
}

fn get_int(map: &HashMap<String, String>, key: &str) -> Result<i64, ConfigError> {
    let raw = require(map, key)?;
    raw.parse::<i64>().map_err(|_| ConfigError::BadNumber {
        key: key.to_string(),
        value: raw.clone(),
    })
}

fn get_flag(map: &HashMap<String, String>, key: &str) -> Result<bool, ConfigError> {
    let raw = require(map, key)?;
    match raw.to_ascii_lowercase().as_str() {
        "true" | "yes" | "on" => Ok(true),
        "false" | "no" | "off" => Ok(false),
        other => Err(ConfigError::BadFlag {
            key: key.to_string(),
            value: other.to_string(),
        }),
    }
}

fn summarize(map: &HashMap<String, String>) -> Result<String, ConfigError> {
    let host = require(map, "host")?;
    let port = get_int(map, "port")?;
    let retries = get_int(map, "retries")?;
    let verbose = get_flag(map, "verbose")?;
    Ok(format!(
        "{}:{} (retries={}, verbose={})",
        host, port, retries, verbose
    ))
}

fn main() -> Result<(), ConfigError> {
    let text = "# service settings\nhost = example.org\nport = 8080\nretries = 3\nverbose = yes\n";
    let map = parse_config(text)?;
    println!("{}", summarize(&map)?);
    println!("host  -> {}", get_from_map(&map, "host"));
    println!("proxy -> {}", get_from_map(&map, "proxy"));
    let attempts = get_int(&map, "retries")? + 1;
    println!("total attempts: {}", attempts);
    Ok(())
}

