use std::str::SplitWhitespace;

#[derive(Debug, Clone, Copy)]
struct Point {
    x: f64,
    y: f64,
}

#[derive(Debug, Clone, Copy)]
struct Rect {
    x1: f64,
    y1: f64,
    x2: f64,
    y2: f64,
}

impl Rect {
    fn new(x1: f64, y1: f64, x2: f64, y2: f64) -> Result<Rect, String> {
        if x1 > x2 || y1 > y2 {
            return Err(format!(
                "corners out of order: ({}, {}) is not below-left of ({}, {})",
                x1, y1, x2, y2
            ));
        }
        Ok(Rect { x1, y1, x2, y2 })
    }
}

fn parse_field(name: &str, tokens: &mut SplitWhitespace) -> Result<f64, String> {
    let tok = tokens.next().ok_or_else(|| format!("missing field `{}`", name))?;
    let value: f64 = tok.parse().map_err(|_| format!("field `{}` is not a number: {}", name, tok))?;
    if value.is_finite() {
        Ok(value)
    } else {
        Err(format!("field `{}` must be finite, got {}", name, tok))
    }
}

fn parse_point(tokens: &mut SplitWhitespace) -> Result<Point, String> {
    let x = parse_field("x", tokens)?;
    let y = parse_field("y", tokens)?;
    Ok(Point { x, y })
}

fn parse_rect(tokens: &mut SplitWhitespace) -> Result<Rect, String> {
    let x1 = parse_field("x1", tokens)?;
    let y1 = parse_field("y1", tokens)?;
    let x2 = parse_field("x2", tokens)?;
    let y2 = parse_field("y2", tokens)?;
    Rect::new(x1, y1, x2, y2)
}

fn parse_query(line: &str) -> Result<(Point, Rect), String> {
    let mut tokens = line.split_whitespace();
    let point = parse_point(&mut tokens)?;
    let rect = parse_rect(&mut tokens)?;
    match tokens.next() {
        Some(extra) => Err(format!("unexpected trailing input: {}", extra)),
        None => Ok((point, rect)),
    }
}

fn is_point_in_rect(x: f64, y: f64, x1: f64, y1: f64, x2: f64, y2: f64) -> bool {
    x >= x1 && x <= x2 && y >= y1 && y <= y2
}

fn describe(p: Point, r: Rect, inside: bool) -> String {
    format!(
        "({}, {}) is {} rectangle [({}, {}), ({}, {})]",
        p.x,
        p.y,
        if inside { "inside" } else { "outside" },
        r.x1, r.y1, r.x2, r.y2
    )
}

fn run(queries: &[&str]) -> Result<usize, String> {
    let mut inside_count = 0;
    for line in queries {
        let (p, r) = parse_query(line)?;
        let inside = is_point_in_rect(p.x, p.y, r.x1, r.y1, r.x2, r.y2);
        if inside {
            inside_count += 1;
        }
        println!("{}", describe(p, r, inside));
    }
    Ok(inside_count)
}

fn main() -> Result<(), String> {
    let queries = [
        "1 1 0 0 2 2",
        "3 1 0 0 2 2",
        "0 0 0 0 2 2",
        "2 2 0 0 2 2",
        "-1.5 0.25 -2 0 -1 1",
    ];
    let inside = run(&queries)?;
    println!("{} of {} points were inside", inside, queries.len());
    Ok(())
}

