use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum VecError {
    BadInt(ParseIntError),
    BadSyntax(String),
    Overflow(String),
    NoData,
}

impl fmt::Display for VecError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            VecError::BadInt(e) => write!(f, "not an integer: {}", e),
            VecError::BadSyntax(s) => write!(f, "expected a bracketed list, got {:?}", s),
            VecError::Overflow(s) => write!(f, "product overflows i32 for {}", s),
            VecError::NoData => write!(f, "no vectors supplied"),
        }
    }
}

impl Error for VecError {}

impl From<ParseIntError> for VecError {
    fn from(e: ParseIntError) -> Self {
        VecError::BadInt(e)
    }
}

fn parse_element(token: &str) -> Result<i32, VecError> {
    let value: i32 = token.trim().parse()?;
    Ok(value)
}

fn parse_vector(spec: &str) -> Result<Vec<i32>, VecError> {
    let trimmed = spec.trim();
    let body = trimmed
        .strip_prefix('[')
        .and_then(|s| s.strip_suffix(']'))
        .ok_or_else(|| VecError::BadSyntax(trimmed.to_string()))?;
    if body.trim().is_empty() {
        return Ok(Vec::new());
    }
    let mut values = Vec::new();
    for token in body.split(',') {
        values.push(parse_element(token)?);
    }
    Ok(values)
}

fn product_of_elements(values: &Vec<i32>) -> i32 {
    values.iter().fold(1i32, |acc, &v| acc.wrapping_mul(v))
}

fn safe_product(values: &Vec<i32>) -> Result<i32, VecError> {
    values
        .iter()
        .try_fold(1i32, |acc, &v| acc.checked_mul(v))
        .ok_or_else(|| VecError::Overflow(format!("{:?}", values)))
}

fn product_of_spec(spec: &str) -> Result<i32, VecError> {
    let values = parse_vector(spec)?;
    safe_product(&values)
}

fn describe(spec: &str) -> Result<String, VecError> {
    let values = parse_vector(spec)?;
    let product = safe_product(&values)?;
    Ok(format!(
        "{} has {} element(s) and product {}",
        spec.trim(),
        values.len(),
        product
    ))
}

fn largest_product(specs: &[&str]) -> Result<i32, VecError> {
    let (first, rest) = specs.split_first().ok_or(VecError::NoData)?;
    let mut best = product_of_spec(first)?;
    for spec in rest {
        let candidate = product_of_spec(spec)?;
        if candidate > best {
            best = candidate;
        }
    }
    Ok(best)
}

fn main() -> Result<(), Box<dyn Error>> {
    let specs = ["[1, 2, 3]", "[]", "[-4, 5, 2]", "[7]"];
    for spec in specs.iter() {
        println!("{}", describe(spec)?);
    }
    println!("largest product: {}", largest_product(&specs)?);
    let huge = parse_vector("[100000, 100000]")?;
    println!("wrapping product of {:?}: {}", huge, product_of_elements(&huge));
    match safe_product(&huge) {
        Ok(p) => println!("checked product: {}", p),
        Err(e) => println!("checked product failed: {}", e),
    }
    Ok(())
}

