use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum PriceError {
    BadNumber(ParseFloatError),
    MissingField(&'static str),
    OutOfRange(String),
}

impl fmt::Display for PriceError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            PriceError::BadNumber(e) => write!(f, "not a number: {}", e),
            PriceError::MissingField(name) => write!(f, "missing field: {}", name),
            PriceError::OutOfRange(msg) => write!(f, "out of range: {}", msg),
        }
    }
}

impl From<ParseFloatError> for PriceError {
    fn from(e: ParseFloatError) -> Self {
        PriceError::BadNumber(e)
    }
}

fn calculate_discounted_price(price: f64, discount: f64) -> f64 {
    price - price * discount / 100.0
}

fn parse_price(text: &str) -> Result<f64, PriceError> {
    let value: f64 = text.trim().parse()?;
    if value < 0.0 {
        return Err(PriceError::OutOfRange(format!("price {} is negative", value)));
    }
    Ok(value)
}

fn parse_discount(text: &str) -> Result<f64, PriceError> {
    let value: f64 = text.trim().parse()?;
    if !(0.0..=100.0).contains(&value) {
        return Err(PriceError::OutOfRange(format!("discount {}% not in 0..=100", value)));
    }
    Ok(value)
}

struct Item {
    name: String,
    price: f64,
    discount: f64,
}

impl Item {
    fn final_price(&self) -> f64 {
        calculate_discounted_price(self.price, self.discount)
    }
}

fn parse_item(line: &str) -> Result<Item, PriceError> {
    let mut fields = line.split(',');
    let name = fields.next().ok_or(PriceError::MissingField("name"))?;
    let price_text = fields.next().ok_or(PriceError::MissingField("price"))?;
    let discount_text = fields.next().ok_or(PriceError::MissingField("discount"))?;
    let price = parse_price(price_text)?;
    let discount = parse_discount(discount_text)?;
    Ok(Item { name: name.trim().to_string(), price, discount })
}

fn receipt(lines: &[&str]) -> Result<String, PriceError> {
    let mut out = String::new();
    let mut total = 0.0;
    for line in lines {
        let item = parse_item(line)?;
        total += item.final_price();
        out.push_str(&format!("{:<10} {:>8.2} -{:>5.1}% {:>8.2}\n",
            item.name, item.price, item.discount, item.final_price()));
    }
    out.push_str(&format!("{:<10} {:>25.2}\n", "TOTAL", total));
    Ok(out)
}

fn main() -> Result<(), PriceError> {
    println!("{}", calculate_discounted_price(100.0, 10.0));
    println!("{}", calculate_discounted_price(50.0, 25.0));
    let lines = ["Widget, 100.0, 10.0", "Gadget, 50.0, 25.0", "Bolt, 2.5, 0.0"];
    print!("{}", receipt(&lines)?);
    match parse_item("Broken, 10.0, 150.0") {
        Ok(item) => println!("{} costs {:.2}", item.name, item.final_price()),
        Err(e) => println!("rejected: {}", e),
    }
    Ok(())
}

