fn binary_to_gray(n: u32) -> u32 {
    n ^ (n >> 1)
}

fn gray_to_binary(gray: u32) -> u32 {
    let mut value = gray;
    let mut shift = 1;
    while shift < 32 {
        value ^= value >> shift;
        shift <<= 1;
    }
    value
}

fn parse_binary_literal(digits: &str) -> Result<u32, String> {
    if digits.is_empty() {
        return Err("binary literal has no digits".to_string());
    }
    let value = u32::from_str_radix(digits, 2)
        .map_err(|e| format!("bad binary literal '{digits}': {e}"))?;
    Ok(value)
}

fn parse_value(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    if let Some(digits) = trimmed.strip_prefix("0b") {
        return parse_binary_literal(digits);
    }
    let value = trimmed
        .parse::<u32>()
        .map_err(|e| format!("bad decimal value '{trimmed}': {e}"))?;
    Ok(value)
}

fn bit_width(value: u32) -> u32 {
    (32 - value.leading_zeros()).max(1)
}

fn column_width(inputs: &[String]) -> Result<u32, String> {
    let mut width = 1;
    for text in inputs {
        let value = parse_value(text)?;
        width = width.max(bit_width(value));
        width = width.max(bit_width(binary_to_gray(value)));
    }
    Ok(width)
}

fn to_bits(value: u32, width: u32) -> String {
    (0..width)
        .rev()
        .map(|bit| if value >> bit & 1 == 1 { '1' } else { '0' })
        .collect()
}

fn format_row(text: &str, width: u32) -> Result<String, String> {
    let value = parse_value(text)?;
    let gray = binary_to_gray(value);
    Ok(format!(
        "{:>10} -> {} ^ {} = {} ({:>10})  decoded {}",
        value,
        to_bits(value, width),
        to_bits(value >> 1, width),
        to_bits(gray, width),
        gray,
        gray_to_binary(gray)
    ))
}

fn report(inputs: &[String]) -> Result<String, String> {
    let width = column_width(inputs)?;
    let mut lines = Vec::with_capacity(inputs.len());
    for text in inputs {
        lines.push(format_row(text, width)?);
    }
    Ok(lines.join("\n"))
}

fn main() {
    let mut inputs: Vec<String> = std::env::args().skip(1).collect();
    if inputs.is_empty() {
        inputs = ["4", "7", "0b1011", "0", "255"]
            .iter()
            .map(|s| s.to_string())
            .collect();
    }
    match report(&inputs) {
        Ok(table) => println!("{table}"),
        Err(message) => {
            eprintln!("error: {message}");
            std::process::exit(1);
        }
    }
}

