use std::env;
use std::error::Error;
use std::fs;
use std::io::{self, Read, Write};

/// Counts every character in `text` that is not whitespace.
pub fn count_non_whitespace_chars(text: &str) -> usize {
    text.chars().filter(|c| !c.is_whitespace()).count()
}

pub struct Entry {
    pub name: String,
    pub non_ws: usize,
    pub total: usize,
}

/// Reads one file and measures its character counts.
pub fn analyze(path: &str) -> io::Result<Entry> {
    let text = fs::read_to_string(path)?;
    Ok(Entry {
        name: path.to_string(),
        non_ws: count_non_whitespace_chars(&text),
        total: text.chars().count(),
    })
}

/// Reads every requested file, stopping at the first I/O failure.
pub fn analyze_all(paths: &[String]) -> io::Result<Vec<Entry>> {
    let mut entries = Vec::with_capacity(paths.len());
    for path in paths {
        entries.push(analyze(path)?);
    }
    Ok(entries)
}

/// Share of characters that are not whitespace; `None` for an empty file.
pub fn entry_density(entry: &Entry) -> Option<f64> {
    if entry.total == 0 {
        return None;
    }
    Some(entry.non_ws as f64 / entry.total as f64)
}

/// The file with the highest non-whitespace ratio, ignoring empty files.
pub fn densest(entries: &[Entry]) -> Option<&Entry> {
    let mut rated = entries
        .iter()
        .filter_map(|e| entry_density(e).map(|d| (e, d)));
    let (mut best, mut best_density) = rated.next()?;
    for (entry, density) in rated {
        if density > best_density {
            best = entry;
            best_density = density;
        }
    }
    Some(best)
}

pub fn write_report(out: &mut impl Write, entries: &[Entry]) -> io::Result<()> {
    for entry in entries {
        let shown = match entry_density(entry) {
            Some(d) => format!("{:.1}%", d * 100.0),
            None => String::from("empty"),
        };
        writeln!(out, "{:<24} {:>8} / {:<8} {}", entry.name, entry.non_ws, entry.total, shown)?;
    }
    if let Some(best) = densest(entries) {
        writeln!(out, "densest file: {}", best.name)?;
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let paths: Vec<String> = env::args().skip(1).collect();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    if paths.is_empty() {
        let mut text = String::new();
        io::stdin().read_to_string(&mut text)?;
        writeln!(out, "{}", count_non_whitespace_chars(&text))?;
        return Ok(());
    }
    let entries = analyze_all(&paths)?;
    write_report(&mut out, &entries)?;
    Ok(())
}

