use std::fmt;
use std::num::ParseIntError;

/// Returns `true` when every character of `s` is a letter or a digit.
/// The empty string trivially satisfies the condition.
pub fn is_alphanumeric(s: &str) -> bool {
    s.chars().all(char::is_alphanumeric)
}

#[derive(Debug)]
pub enum ParseError {
    MissingSeparator(String),
    NotAlphanumeric(String),
    BadNumber(ParseIntError),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingSeparator(line) => write!(f, "no '=' in {:?}", line),
            ParseError::NotAlphanumeric(text) => write!(f, "{:?} is not alphanumeric", text),
            ParseError::BadNumber(err) => write!(f, "bad number: {}", err),
        }
    }
}

impl From<ParseIntError> for ParseError {
    fn from(err: ParseIntError) -> Self {
        ParseError::BadNumber(err)
    }
}

pub struct Record {
    pub label: String,
    pub count: u32,
}

fn split_pair(line: &str) -> Result<(&str, &str), ParseError> {
    let (left, right) = line
        .split_once('=')
        .ok_or_else(|| ParseError::MissingSeparator(line.to_string()))?;
    Ok((left.trim(), right.trim()))
}

fn checked(text: &str) -> Result<&str, ParseError> {
    if is_alphanumeric(text) {
        Ok(text)
    } else {
        Err(ParseError::NotAlphanumeric(text.to_string()))
    }
}

pub fn parse_record(line: &str) -> Result<Record, ParseError> {
    let (label, value) = split_pair(line)?;
    let label = checked(label)?;
    let digits = checked(value)?;
    let count = digits.parse::<u32>()?;
    Ok(Record { label: label.to_string(), count })
}

pub fn parse_all(input: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();
    for line in input.lines().map(str::trim).filter(|l| !l.is_empty()) {
        records.push(parse_record(line)?);
    }
    Ok(records)
}

pub fn count_of(records: &[Record], label: &str) -> Option<u32> {
    records.iter().find(|r| r.label == label).map(|r| r.count)
}

pub fn format_report(records: &[Record]) -> String {
    let width = records.iter().map(|r| r.label.len()).max().unwrap_or(5);
    let mut out = String::new();
    let mut total = 0u32;
    for record in records {
        out.push_str(&format!("{:<width$} : {:>5}\n", record.label, record.count));
        total += record.count;
    }
    out.push_str(&format!("{:<width$} : {:>5}\n", "TOTAL", total));
    if let Some(top) = records.iter().max_by_key(|r| r.count) {
        out.push_str(&format!("busiest label: {}\n", top.label));
    }
    out
}

fn run(input: &str, query: &str) -> Result<(), ParseError> {
    let records = parse_all(input)?;
    print!("{}", format_report(&records));
    let label = checked(query)?;
    match count_of(&records, label) {
        Some(count) => println!("{} appears with count {}", label, count),
        None => println!("{} is not listed", label),
    }
    Ok(())
}

fn main() {
    let input = "HelloWorld123 = 12\nRust2024 = 99\nData7 = 30\n";
    if let Err(err) = run(input, "Rust2024") {
        eprintln!("error: {}", err);
    }
}

