use std::fmt::Write as _;

/// Converts a number of hours (possibly fractional) into minutes.
fn hours_to_minutes(hours: f64) -> f64 {
    hours * 60.0
}

/// Rejects values that cannot describe a real duration.
fn validate_hours(hours: f64) -> Result<f64, String> {
    if !hours.is_finite() {
        return Err(format!("{hours} is not a finite number of hours"));
    }
    if hours < 0.0 {
        return Err(format!("{hours} hours is negative"));
    }
    Ok(hours)
}

/// Parses a decimal amount of hours, e.g. "0.5" or "2".
fn parse_hours(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|_| format!("'{trimmed}' is not a number"))?;
    validate_hours(value)
}

fn parse_field(name: &str, text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    trimmed
        .parse()
        .map_err(|_| format!("{name} '{trimmed}' is not a number"))
}

/// Parses a "H:MM" clock-style duration into fractional hours.
fn parse_clock(text: &str) -> Result<f64, String> {
    let (left, right) = text
        .split_once(':')
        .ok_or_else(|| format!("'{text}' is not in H:MM form"))?;
    let whole_hours = parse_field("hour count", left)?;
    let minutes = parse_field("minute count", right)?;
    if minutes >= 60.0 {
        return Err(format!("{minutes} minutes does not fit in an hour"));
    }
    validate_hours(whole_hours + minutes / 60.0)
}

fn parse_duration(text: &str) -> Result<f64, String> {
    if text.contains(':') {
        return parse_clock(text.trim());
    }
    parse_hours(text)
}

fn build_report(inputs: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    let mut total = 0.0;
    for input in inputs {
        let hours = parse_duration(input)?;
        let minutes = hours_to_minutes(hours);
        total += minutes;
        writeln!(out, "{input:>6} hours => {minutes:.1} minutes").map_err(|e| e.to_string())?;
    }
    writeln!(out, "{:>6} total  => {total:.1} minutes", "").map_err(|e| e.to_string())?;
    Ok(out)
}

fn main() -> Result<(), String> {
    let report = build_report(&["2.0", "0.5", "1:45", "0.25"])?;
    print!("{report}");
    let overnight = parse_duration("7:30")?;
    println!("a 7:30 sleep is {} minutes", hours_to_minutes(overnight));
    Ok(())
}

