use std::fmt::Write;

/// Keep only the strings that begin with `prefix` (case-sensitive).
fn filter_by_prefix(words: &Vec<String>, prefix: &str) -> Vec<String> {
    words
        .iter()
        .filter(|word| word.starts_with(prefix))
        .cloned()
        .collect()
}

/// Read the `prefix=...` field of a query line.
fn parse_prefix(field: &str) -> Result<&str, String> {
    let value = field
        .strip_prefix("prefix=")
        .ok_or_else(|| format!("expected a `prefix=` field, got {:?}", field))?;
    if value.is_empty() {
        return Err("the prefix must not be empty".to_string());
    }
    Ok(value)
}

/// A single word of the candidate list, with surrounding blanks removed.
fn parse_word(raw: &str) -> Result<&str, String> {
    let word = raw.trim();
    if word.is_empty() {
        return Err("the word list contains an empty entry".to_string());
    }
    Ok(word)
}

/// Read the `words=a,b,c` field of a query line.
fn parse_words(field: &str) -> Result<Vec<String>, String> {
    let value = field
        .strip_prefix("words=")
        .ok_or_else(|| format!("expected a `words=` field, got {:?}", field))?;
    let mut words = Vec::new();
    for raw in value.split(',') {
        words.push(parse_word(raw)?.to_string());
    }
    Ok(words)
}

/// Split `prefix=ap; words=apple,apricot` into its two parts.
fn parse_line(line: &str) -> Result<(String, Vec<String>), String> {
    let (left, right) = line
        .split_once(';')
        .ok_or_else(|| format!("missing `;` separator in {:?}", line))?;
    let prefix = parse_prefix(left.trim())?;
    let words = parse_words(right.trim())?;
    Ok((prefix.to_string(), words))
}

/// Render one result as a human readable line.
fn format_report(prefix: &str, total: usize, hits: &[String]) -> Result<String, std::fmt::Error> {
    let mut out = String::new();
    write!(out, "{:?}: {} of {} match", prefix, hits.len(), total)?;
    if hits.is_empty() {
        write!(out, " (nothing)")?;
    } else {
        write!(out, " -> {}", hits.join(", "))?;
    }
    Ok(out)
}

fn run_query(line: &str) -> Result<String, String> {
    let (prefix, words) = parse_line(line)?;
    let hits = filter_by_prefix(&words, &prefix);
    let report = format_report(&prefix, words.len(), &hits).map_err(|e| e.to_string())?;
    Ok(report)
}

fn main() -> Result<(), String> {
    let queries = [
        "prefix=ap; words=apple, apricot, banana",
        "prefix=hello; words=Hello",
        "prefix=ba; words=banana, bandit, Banana",
    ];
    for query in queries {
        println!("{}", run_query(query)?);
    }
    Ok(())
}

