    BadNumber(String),
    NonPositive(f64),
    EmptyDataset,
}

impl fmt::Display for StatsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StatsError::BadNumber(token) => write!(f, "not a number: {}", token),
            StatsError::NonPositive(value) => write!(f, "value must be positive, got {}", value),
            StatsError::EmptyDataset => write!(f, "dataset contains no values"),
        }
    }
}

fn parse_value(token: &str) -> Result<f64, StatsError> {
    let value = token.parse::<f64>().map_err(|_| StatsError::BadNumber(token.to_string()))?;
    if value <= 0.0 {
        return Err(StatsError::NonPositive(value));
    }
    Ok(value)
}

fn parse_dataset(line: &str) -> Result<Vec<f64>, StatsError> {
    let mut values = Vec::new();
    for token in line.split(|c: char| c == ',' || c.is_whitespace()) {
        if !token.is_empty() {
            let value = parse_value(token)?;
            values.push(value);
        }
    }
    Ok(values)
}

fn harmonic_mean(values: &Vec<f64>) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let reciprocal_sum: f64 = values.iter().map(|x| 1.0 / x).sum();
    values.len() as f64 / reciprocal_sum
}

fn arithmetic_mean(values: &[f64]) -> f64 {
    values.iter().sum::<f64>() / values.len() as f64
}

fn min_max(values: &[f64]) -> Option<(f64, f64)> {
    let first = values.first().copied()?;
    let folded = values.iter().fold((first, first), |(lo, hi), &v| (lo.min(v), hi.max(v)));
    Some(folded)
}

fn append_summary(out: &mut String, line: &str) -> Result<(), StatsError> {
    let values = parse_dataset(line)?;
    let (lo, hi) = min_max(&values).ok_or(StatsError::EmptyDataset)?;
    out.push_str(&format!(
        "n={} min={} max={} harmonic={} arithmetic={}\n",
        values.len(),
        lo,
        hi,
        harmonic_mean(&values),
        arithmetic_mean(&values)
    ));
    Ok(())
}

fn format_report(lines: &[&str]) -> Result<String, StatsError> {
    let mut out = String::new();
    for line in lines {
        append_summary(&mut out, line)?;
    }
    Ok(out)
}

fn main() {
    let batches: [&[&str]; 3] = [&["1, 2, 4", "0.5 8 12.25"], &["3 -1 5"], &["   "]];
    for batch in batches.iter() {
        match format_report(batch) {
            Ok(report) => print!("{}", report),
            Err(e) => eprintln!("report rejected: {}", e),
        }
    }
}

