use std::fmt::{self, Write};

#[derive(Debug)]
enum ParseError {
    MissingSeparator(String),
    EmptyKey(String),
    BadValue { key: String, text: String },
    Format(fmt::Error),
}

impl From<fmt::Error> for ParseError {
    fn from(err: fmt::Error) -> Self {
        ParseError::Format(err)
    }
}

#[derive(Debug)]
struct Entry {
    key: String,
    value: i64,
}

fn to_kebab_case(input: &str) -> String {
    let mut out = String::new();
    for ch in input.chars() {
        if ch == ' ' || ch == '_' || ch == '-' || ch == '\t' {
            if !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
        } else {
            out.extend(ch.to_lowercase());
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

fn split_key_value(line: &str) -> Option<(&str, &str)> {
    let (raw_key, raw_value) = line.split_once('=')?;
    Some((raw_key.trim(), raw_value.trim()))
}

fn parse_entry(line: &str) -> Result<Entry, ParseError> {
    let (raw_key, raw_value) =
        split_key_value(line).ok_or_else(|| ParseError::MissingSeparator(line.to_string()))?;
    let key = to_kebab_case(raw_key);
    if key.is_empty() {
        return Err(ParseError::EmptyKey(line.to_string()));
    }
    let value = raw_value.parse::<i64>().map_err(|_| ParseError::BadValue {
        key: key.clone(),
        text: raw_value.to_string(),
    })?;
    Ok(Entry { key, value })
}

fn parse_document(text: &str) -> Result<Vec<Entry>, ParseError> {
    let mut entries = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        entries.push(parse_entry(line)?);
    }
    Ok(entries)
}

fn lookup(entries: &[Entry], name: &str) -> Option<i64> {
    let wanted = to_kebab_case(name);
    let entry = entries.iter().find(|e| e.key == wanted)?;
    Some(entry.value)
}

fn render(entries: &[Entry]) -> Result<String, fmt::Error> {
    let mut out = String::new();
    for entry in entries {
        writeln!(out, "{} -> {}", entry.key, entry.value)?;
    }
    write!(out, "{} entries", entries.len())?;
    Ok(out)
}

fn report(entries: &[Entry], queries: &[&str]) -> Result<String, ParseError> {
    let mut out = String::from(render(entries)?);
    out.push('\n');
    for query in queries {
        match lookup(entries, query) {
            Some(value) => writeln!(out, "query {:?}: {}", query, value)?,
            None => writeln!(out, "query {:?}: missing", query)?,
        }
    }
    Ok(out)
}

fn main() -> Result<(), ParseError> {
    let document = "Hello World = 12\nanother_example_string = 7\n  Mixed__Up  Keys = -3\n";
    let entries = parse_document(document)?;
    print!("{}", report(&entries, &["hello world", "Mixed_Up-Keys", "nope"])?);
    println!("{}", to_kebab_case("Hello World"));
    println!("{}", to_kebab_case("another_example_string"));
    Ok(())
}

