use std::fmt;
use std::io::{self, BufRead, Write};
use std::num::ParseIntError;

#[derive(Debug)]
enum SpecError {
    MissingSeparator,
    BadCount(ParseIntError),
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SpecError::MissingSeparator => write!(f, "expected the form <text>,<n>"),
            SpecError::BadCount(e) => write!(f, "invalid count: {}", e),
        }
    }
}

impl From<ParseIntError> for SpecError {
    fn from(e: ParseIntError) -> Self {
        SpecError::BadCount(e)
    }
}

fn remove_first_n_chars(s: &str, n: usize) -> String {
    s.chars().skip(n).collect()
}

fn parse_spec(line: &str) -> Result<(&str, usize), SpecError> {
    let (text, count) = match line.split_once(',').ok_or(SpecError::MissingSeparator) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let n = match count.trim().parse::<usize>() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((text, n))
}

fn format_spec_result(line: &str) -> Result<String, SpecError> {
    let (text, n) = match parse_spec(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let tail = remove_first_n_chars(text, n);
    Ok(format!(
        "{:?} minus first {} char(s) = {:?} ({} char(s) left)",
        text,
        n,
        tail,
        tail.chars().count()
    ))
}

fn run<R: BufRead, W: Write>(input: R, mut output: W) -> io::Result<()> {
    for entry in input.lines() {
        let line = match entry {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        if line.trim().is_empty() {
            continue;
        }
        match format_spec_result(&line) {
            Ok(report) => match writeln!(output, "{}", report) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            Err(err) => match writeln!(output, "{:?}: {}", line, err) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
        }
    }
    match output.flush() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(())
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let stdout = io::stdout();
    match run(stdin.lock(), stdout.lock()) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(())
}

