use std::fmt::{self, Write as _};
use std::num::NonZeroUsize;

/// Counts the words in `text`; words are any runs of non-whitespace characters.
fn count_words(text: &str) -> usize {
    text.split_whitespace().count()
}

fn first_word(text: &str) -> Option<&str> {
    text.split_whitespace().next()
}

/// The first character of the first word, if there is one.
fn initial(text: &str) -> Option<char> {
    first_word(text)?.chars().next()
}

fn longest_word(text: &str) -> Option<&str> {
    text.split_whitespace().max_by_key(|word| word.chars().count())
}

/// Mean number of words over the non-blank lines of `text`.
fn average_words_per_line(text: &str) -> Option<f64> {
    let lines: Vec<&str> = text.lines().filter(|line| !line.trim().is_empty()).collect();
    let line_count = NonZeroUsize::new(lines.len())?;
    let total: usize = lines.iter().map(|line| count_words(line)).sum();
    Some(total as f64 / line_count.get() as f64)
}

/// Splits a `"<text>=<expected count>"` specification into its two parts.
fn parse_spec(spec: &str) -> Result<(&str, usize), String> {
    let (text, expected) = spec
        .rsplit_once('=')
        .ok_or_else(|| format!("missing '=' in specification {:?}", spec))?;
    let expected = expected
        .trim()
        .parse::<usize>()
        .map_err(|err| format!("bad expected count {:?}: {}", expected, err))?;
    Ok((text, expected))
}

/// Checks one specification and describes the outcome.
fn verify(spec: &str) -> Result<String, String> {
    let (text, expected) = parse_spec(spec)?;
    let actual = count_words(text);
    if actual != expected {
        return Err(format!("{:?}: expected {} words, counted {}", text, expected, actual));
    }
    Ok(format!("ok: {:?} -> {} words", text, actual))
}

/// Builds a multi-line report about `text`.
fn summary(text: &str) -> Result<String, fmt::Error> {
    let mut out = String::new();
    writeln!(out, "words: {}", count_words(text))?;
    match initial(text) {
        Some(letter) => writeln!(out, "first letter: {}", letter)?,
        None => writeln!(out, "first letter: none (text is blank)")?,
    }
    if let Some(word) = longest_word(text) {
        writeln!(out, "longest word: {}", word)?;
    }
    if let Some(average) = average_words_per_line(text) {
        writeln!(out, "words per line: {:.2}", average)?;
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    for spec in ["hello world=2", "  one   two  three   =3", "=0"] {
        println!("{}", verify(spec)?);
    }

    let text = "the quick brown fox\n\njumps over the lazy dog\n";
    let report = summary(text).map_err(|err| format!("could not format report: {}", err))?;
    print!("{}", report);
    Ok(())
}

