use std::fmt::Write as FmtWrite;

/// Sum of absolute differences between corresponding elements.
fn sum_abs_diffs(a: &Vec<i32>, b: &Vec<i32>) -> i32 {
    a.iter().zip(b.iter()).map(|(x, y)| (*x - *y).abs()).sum()
}

/// Splits a line of the form "1 2 3 | 4 1 0" into its two halves.
fn split_pair(line: &str) -> Result<(&str, &str), String> {
    let (left, right) = line
        .split_once('|')
        .ok_or_else(|| format!("missing '|' separator in {:?}", line))?;
    Ok((left, right))
}

/// Parses whitespace separated integers into a vector.
fn parse_vector(text: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for token in text.split_whitespace() {
        let n = token
            .parse::<i32>()
            .map_err(|e| format!("bad integer {:?}: {}", token, e))?;
        values.push(n);
    }
    if values.is_empty() {
        return Err(format!("no integers found in {:?}", text));
    }
    Ok(values)
}

/// Parses both vectors of a line and checks that they have equal length.
fn parse_pair(line: &str) -> Result<(Vec<i32>, Vec<i32>), String> {
    let (left_text, right_text) = split_pair(line)?;
    let left = parse_vector(left_text)?;
    let right = parse_vector(right_text)?;
    if left.len() != right.len() {
        return Err(format!(
            "length mismatch: {} vs {} in {:?}",
            left.len(),
            right.len(),
            line
        ));
    }
    Ok((left, right))
}

/// Builds a human readable breakdown of one comparison plus its total.
fn line_report(line: &str) -> Result<(String, i32), String> {
    let (left, right) = parse_pair(line)?;
    let total = sum_abs_diffs(&left, &right);
    let mut out = String::new();
    let mut terms = Vec::new();
    for (x, y) in left.iter().zip(right.iter()) {
        terms.push((*x - *y).abs().to_string());
    }
    write!(out, "{:?} vs {:?}: ", left, right).map_err(|e| e.to_string())?;
    write!(out, "{} = {}", terms.join(" + "), total).map_err(|e| e.to_string())?;
    Ok((out, total))
}

/// Reports every line and returns the grand total of all distances.
fn run(lines: &[&str]) -> Result<i32, String> {
    let mut grand_total = 0;
    for line in lines {
        let (report, total) = line_report(line)?;
        println!("{}", report);
        grand_total += total;
    }
    Ok(grand_total)
}

fn main() -> Result<(), String> {
    let lines = ["1 2 3 | 4 1 0", "5 | 2", "-3 7 0 12 | 3 7 -4 10"];
    let grand_total = run(&lines)?;
    println!("grand total: {}", grand_total);
    Ok(())
}

