    s.split(' ').map(capitalize).collect::<Vec<String>>().join(" ")
}

fn capitalize(word: &str) -> String {
    let mut chars = word.chars();
    match chars.next() {
        Some(first) => first
            .to_uppercase()
            .chain(chars.flat_map(|c| c.to_lowercase()))
            .collect(),
        None => String::new(),
    }
}

#[derive(Debug)]
struct ParseError {
    line: usize,
    reason: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: {}", self.line, self.reason)
    }
}

impl Error for ParseError {}

struct Entry {
    id: u32,
    name: String,
}

/// Splits `"12 | some name"` into its trimmed halves, or `None` if the bar is missing.
fn split_entry(line: &str) -> Option<(&str, &str)> {
    let (id, name) = line.split_once('|')?;
    Some((id.trim(), name.trim()))
}

fn parse_entry(number: usize, line: &str) -> Result<Entry, ParseError> {
    let (id_part, name_part) = split_entry(line).ok_or_else(|| ParseError {
        line: number,
        reason: format!("expected '<id> | <name>', got {:?}", line),
    })?;
    let id = id_part.parse::<u32>().map_err(|e| ParseError {
        line: number,
        reason: format!("bad id {:?}: {}", id_part, e),
    })?;
    if name_part.is_empty() {
