use std::error::Error;
use std::fmt;
use std::io::Read;
use std::num::ParseIntError;

fn vector_contains(values: &Vec<i32>, element: i32) -> bool {
    values.iter().any(|&candidate| candidate == element)
}

#[derive(Debug)]
enum QueryError {
    Format(String),
    Number(ParseIntError),
}

impl fmt::Display for QueryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueryError::Format(line) => write!(f, "malformed query: {}", line),
            QueryError::Number(err) => write!(f, "bad integer: {}", err),
        }
    }
}

impl Error for QueryError {}

impl From<ParseIntError> for QueryError {
    fn from(err: ParseIntError) -> Self {
        QueryError::Number(err)
    }
}

fn parse_vector(text: &str) -> Result<Vec<i32>, QueryError> {
    let mut values = Vec::new();
    for token in text.split(',') {
        let trimmed = token.trim();
        if trimmed.is_empty() {
            return Err(QueryError::Format(text.to_string()));
        }
        values.push(trimmed.parse::<i32>()?);
    }
    Ok(values)
}

fn parse_query(line: &str) -> Result<(Vec<i32>, i32), QueryError> {
    let (left, right) = line
        .split_once('|')
        .ok_or_else(|| QueryError::Format(line.to_string()))?;
    let values = parse_vector(left)?;
    let element = right.trim().parse::<i32>()?;
    Ok((values, element))
}

fn answer(line: &str) -> Result<String, QueryError> {
