use std::fmt;
use std::num::{ParseFloatError, ParseIntError};

#[derive(Debug)]
enum SpecError {
    MissingSeparator(String),
    BadValue(ParseFloatError),
    BadPlaces(ParseIntError),
    PlacesOutOfRange(u32),
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SpecError::MissingSeparator(line) => write!(f, "expected 'value,places' in {:?}", line),
            SpecError::BadValue(e) => write!(f, "invalid number: {}", e),
            SpecError::BadPlaces(e) => write!(f, "invalid decimal count: {}", e),
            SpecError::PlacesOutOfRange(n) => write!(f, "{} decimals exceed f64 precision", n),
        }
    }
}

fn round_to_n_decimals(value: f64, places: u32) -> f64 {
    let factor = 10f64.powi(places as i32);
    (value * factor).round() / factor
}

fn parse_spec(line: &str) -> Result<(f64, u32), SpecError> {
    let (raw_value, raw_places) = line
        .split_once(',')
        .ok_or_else(|| SpecError::MissingSeparator(line.to_string()))?;
    let value: f64 = raw_value.trim().parse().map_err(SpecError::BadValue)?;
    let places: u32 = raw_places.trim().parse().map_err(SpecError::BadPlaces)?;
    if places > 17 {
        return Err(SpecError::PlacesOutOfRange(places));
    }
    Ok((value, places))
}

fn round_line(line: &str) -> Result<f64, SpecError> {
    let (value, places) = parse_spec(line)?;
    Ok(round_to_n_decimals(value, places))
}

fn format_line(line: &str) -> Result<String, SpecError> {
    let (value, places) = parse_spec(line)?;
    let rounded = round_to_n_decimals(value, places);
    Ok(format!(
        "{:>12} -> {:.*} ({} decimals)",
        value, places as usize, rounded, places
    ))
}

fn round_all(lines: &[&str]) -> Result<Vec<f64>, SpecError> {
    let mut rounded = Vec::with_capacity(lines.len());
    for line in lines {
        rounded.push(round_line(line)?);
    }
    Ok(rounded)
}

fn sum_rounded(lines: &[&str], places: u32) -> Result<f64, SpecError> {
    let values = round_all(lines)?;
    let total: f64 = values.iter().sum();
    Ok(round_to_n_decimals(total, places))
}

fn report(lines: &[&str]) -> Result<String, SpecError> {
    let mut out = String::new();
    for line in lines {
        out.push_str(&format_line(line)?);
        out.push('\n');
    }
    let total = sum_rounded(lines, 3)?;
    out.push_str(&format!("total (3 decimals) -> {:.3}", total));
    Ok(out)
}

fn main() -> Result<(), SpecError> {
    let inputs = ["3.14159, 2", "123.456, 0", "-2.71828, 4", "0.05, 1"];
    println!("{}", report(&inputs)?);
    let first = round_line(inputs[0])?;
    println!("first value rounded again to 1 decimal: {}", round_to_n_decimals(first, 1));
    Ok(())
}

