fn parse_number(token: &str) -> Result<i32, String> {
    let value = token
        .trim()
        .parse::<i32>()
        .map_err(|e| format!("bad number {:?}: {}", token.trim(), e))?;
    Ok(value)
}

fn parse_numbers(list: &str) -> Result<Vec<i32>, String> {
    let body = list.trim();
    if body.is_empty() {
        return Ok(Vec::new());
    }
    let mut numbers = Vec::new();
    for token in body.split(',') {
        numbers.push(parse_number(token)?);
    }
    Ok(numbers)
}

fn split_query(line: &str) -> Result<(&str, &str), String> {
    let (list, threshold) = line
        .split_once('|')
        .ok_or_else(|| format!("query {:?} must look like `1,5,2,8 | 3`", line))?;
    Ok((list, threshold))
}

fn parse_query(line: &str) -> Result<(Vec<i32>, i32), String> {
    let (list, threshold) = split_query(line)?;
    let numbers = parse_numbers(list)?;
    let limit = parse_number(threshold)?;
    Ok((numbers, limit))
}

fn filter_greater_than(numbers: &Vec<i32>, threshold: i32) -> Vec<i32> {
    numbers.iter().copied().filter(|n| *n > threshold).collect()
}

fn format_list(numbers: &[i32]) -> String {
    let parts: Vec<String> = numbers.iter().map(|n| n.to_string()).collect();
    format!("[{}]", parts.join(", "))
}

fn describe_query(line: &str) -> Result<String, String> {
    let (numbers, threshold) = parse_query(line)?;
    let kept = filter_greater_than(&numbers, threshold);
    Ok(format!(
        "{} > {} => {}",
        format_list(&numbers),
        threshold,
        format_list(&kept)
    ))
}

fn run(queries: &[&str]) -> Result<Vec<String>, String> {
    let mut reports = Vec::with_capacity(queries.len());
    for query in queries {
        reports.push(describe_query(query)?);
    }
    Ok(reports)
}

fn main() -> Result<(), String> {
    let queries = ["1, 5, 2, 8 | 3", "10, 20 | 30", " | 0", "-4, 0, 7 | -5"];
    for report in run(&queries)? {
        println!("{}", report);
    }
    match describe_query("1,2,3") {
        Ok(report) => println!("{}", report),
        Err(message) => println!("rejected: {}", message),
    }
    Ok(())
}

