use std::fmt;

const MAX_LEN: usize = 12;

#[derive(Debug)]
enum PairError {
    MissingSeparator(String),
    TooLong(String),
    NoCandidates(String),
}

impl fmt::Display for PairError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PairError::MissingSeparator(line) => write!(f, "no ',' separator in {line:?}"),
            PairError::TooLong(word) => write!(f, "{word:?} exceeds {MAX_LEN} characters"),
            PairError::NoCandidates(word) => write!(f, "no candidates to compare with {word:?}"),
        }
    }
}

fn check_short(word: &str) -> Result<&str, PairError> {
    if word.chars().count() > MAX_LEN {
        return Err(PairError::TooLong(word.to_string()));
    }
    Ok(word)
}

fn parse_pair(line: &str) -> Result<(String, String), PairError> {
    let (left, right) = line
        .split_once(',')
        .ok_or_else(|| PairError::MissingSeparator(line.to_string()))?;
    let first = check_short(left.trim())?;
    let second = check_short(right.trim())?;
    Ok((first.to_string(), second.to_string()))
}

fn distance(a: &[char], b: &[char]) -> usize {
    if a.is_empty() {
        return b.len();
    }
    if b.is_empty() {
        return a.len();
    }
    let cost = if a[0] == b[0] { 0 } else { 1 };
    let substitute = distance(&a[1..], &b[1..]) + cost;
    let delete = distance(&a[1..], b) + 1;
    let insert = distance(a, &b[1..]) + 1;
    substitute.min(delete).min(insert)
}

fn levenshtein_distance(a: &str, b: &str) -> usize {
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    distance(&left, &right)
}

fn report_line(line: &str) -> Result<String, PairError> {
    let (a, b) = parse_pair(line)?;
    Ok(format!("{a} -> {b}: {}", levenshtein_distance(&a, &b)))
}

fn summarize(lines: &[&str]) -> Result<String, PairError> {
    let mut out = String::new();
    for line in lines {
        out.push_str(&report_line(line)?);
        out.push('\n');
    }
    Ok(out)
}

fn closest<'a>(word: &str, candidates: &[&'a str]) -> Result<(&'a str, usize), PairError> {
    let best = candidates
        .iter()
        .copied()
        .min_by_key(|c| levenshtein_distance(word, c))
        .ok_or_else(|| PairError::NoCandidates(word.to_string()))?;
    Ok((best, levenshtein_distance(word, best)))
}

fn suggestion(word: &str, candidates: &[&str]) -> Result<String, PairError> {
    let checked = check_short(word)?;
    let (best, dist) = closest(checked, candidates)?;
    Ok(format!("closest to {checked} is {best} (distance {dist})"))
}

fn main() -> Result<(), PairError> {
    let report = summarize(&["kitten,sitting", "flaw,lawn", "rosetta, rosettas"])?;
    print!("{report}");
    println!("{}", suggestion("kitteh", &["sitting", "kitten", "mitten"])?);
    Ok(())
}

