use rand::Rng;
use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::io::{self, Write};

/// Simulates a single coin flip.
fn coin_flip() -> &'static str {
    if rand::thread_rng().gen::<bool>() {
        "Heads"
    } else {
        "Tails"
    }
}

/// Reads the number of flips requested on the command line.
fn parse_flip_count(arg: &str) -> Result<usize, Box<dyn Error>> {
    let count: usize = arg.trim().parse()?;
    if count == 0 {
        return Err("the number of flips must be at least 1".into());
    }
    Ok(count)
}

fn flip_many(count: usize) -> Vec<&'static str> {
    (0..count).map(|_| coin_flip()).collect()
}

fn tally(flips: &[&'static str]) -> HashMap<&'static str, usize> {
    let mut counts = HashMap::new();
    for face in flips {
        *counts.entry(*face).or_insert(0) += 1;
    }
    counts
}

/// Share of the flips that landed on `face`, as a percentage.
fn percentage(counts: &HashMap<&'static str, usize>, face: &str) -> Option<f64> {
    let hits = *counts.get(face)?;
    let total: usize = counts.values().sum();
    Some(hits as f64 * 100.0 / total as f64)
}

fn format_report(counts: &HashMap<&'static str, usize>) -> Option<String> {
    let heads = percentage(counts, "Heads")?;
    let tails = percentage(counts, "Tails")?;
    Some(format!("Heads: {heads:.1}%  Tails: {tails:.1}%"))
}

/// The face of the longest streak, together with its length.
fn longest_run(flips: &[&'static str]) -> Option<(&'static str, usize)> {
    let mut best = (*flips.first()?, 1usize);
    let mut current = best;
    for face in &flips[1..] {
        if *face == current.0 {
            current.1 += 1;
        } else {
            current = (*face, 1);
        }
        if current.1 > best.1 {
            best = current;
        }
    }
    Some(best)
}

fn write_report(
    out: &mut impl Write,
    count: usize,
    shares: &str,
    streak: (&str, usize),
) -> io::Result<()> {
    writeln!(out, "{count} flips")?;
    writeln!(out, "{shares}")?;
    writeln!(out, "longest streak: {} x{}", streak.0, streak.1)?;
    out.flush()
}

fn main() -> Result<(), Box<dyn Error>> {
    let arg = env::args().nth(1).unwrap_or_else(|| "20".to_string());
    let count = parse_flip_count(&arg)?;
    let flips = flip_many(count);
    println!("first flip: {}", flips[0]);
    let counts = tally(&flips);
    let shares = format_report(&counts).ok_or("one of the two faces never appeared")?;
    let streak = longest_run(&flips).ok_or("no flips were recorded")?;
    write_report(&mut io::stdout().lock(), count, &shares, streak)?;
    Ok(())
}

