fn find_first_index(values: &Vec<i32>, target: i32) -> Option<usize> {
    values.iter().position(|&v| v == target)
}

fn parse_values(text: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for token in text.split(',') {
        let trimmed = token.trim();
        let value = trimmed
            .parse::<i32>()
            .map_err(|e| format!("bad number {:?}: {}", trimmed, e))?;
        values.push(value);
    }
    Ok(values)
}

fn parse_query(line: &str) -> Result<(Vec<i32>, i32), String> {
    let (left, right) = line
        .split_once('|')
        .ok_or_else(|| format!("missing '|' separator in {:?}", line))?;
    let values = parse_values(left)?;
    let target = right
        .trim()
        .parse::<i32>()
        .map_err(|e| format!("bad target {:?}: {}", right.trim(), e))?;
    Ok((values, target))
}

fn report(line: &str) -> Result<String, String> {
    let (values, target) = parse_query(line)?;
    let first = find_first_index(&values, target)
        .ok_or_else(|| format!("{} not found in {:?}", target, values))?;
    let occurrences = values.iter().filter(|&&v| v == target).count();
    let sum_before: i32 = values[..first].iter().sum();
    Ok(format!(
        "{} -> first index {}, {} occurrence(s), earlier values sum to {}",
        line.trim(),
        first,
        occurrences,
        sum_before
    ))
}

fn total_first_indices(lines: &[&str]) -> Result<usize, String> {
    let mut total = 0;
    for line in lines {
        let (values, target) = parse_query(line)?;
        if let Some(index) = find_first_index(&values, target) {
            total += index;
        }
    }
    Ok(total)
}

fn main() {
    let queries = [
        "10, 20, 30, 20 | 20",
        "1, 2, 3 | 5",
        "7, 7, 7 | 7",
        "-4, 0, 9, 9, -4 | -4",
        "5, 6 7 | 6",
    ];
    for line in queries.iter() {
        match report(line) {
            Ok(text) => println!("{}", text),
            Err(message) => println!("error: {}", message),
        }
    }
    match total_first_indices(&queries[..4]) {
        Ok(total) => println!("sum of first indices: {}", total),
        Err(message) => println!("error: {}", message),
    }
}

