        .map_err(|_| format!("`{}` is not a number", text.trim())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    if !value.is_finite() {
        return Err(format!("`{}` is not a finite length", text.trim()));
    }
    if value <= 0.0 {
        return Err(format!("side must be positive, got {}", value));
    }
    Ok(value)
}

/// Parse a rectangle written as `width x height`, e.g. "3 x 4".
pub fn parse_rectangle(spec: &str) -> Result<(f64, f64), String> {
    let (left, right) = match spec
        .split_once('x')
        .ok_or_else(|| format!("missing `x` separator in `{}`", spec)) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let width = match parse_dimension(left) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let height = match parse_dimension(right) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((width, height))
}

/// Diagonal of a rectangle given in textual form.
pub fn diagonal_of_spec(spec: &str) -> Result<f64, String> {
    let (width, height) = match parse_rectangle(spec) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(rectangle_diagonal(width, height))
}

/// One report line: dimensions, area and diagonal.
pub fn describe(spec: &str) -> Result<String, String> {
    let (width, height) = match parse_rectangle(spec) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let diagonal = rectangle_diagonal(width, height);
    let mut line = String::new();
    match write!(
        line,
        "{:>6.2} x {:<6.2} area {:>9.3}  diagonal {:.3}",
        width,
        height,
        width * height,
        diagonal
    )
    .map_err(|e| e.to_string()) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(line)
}

/// Sum of the diagonals of every rectangle in the list.
pub fn total_diagonal(specs: &[&str]) -> Result<f64, String> {
    let mut total = 0.0;
    for spec in specs {
        total += match diagonal_of_spec(spec) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    Ok(total)
}

fn main() -> Result<(), String> {
    let specs = ["3 x 4", "5 x 12", "1 x 1", "2.5 x 6"];

    for spec in &specs {
        println!("{}", match describe(spec) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }

    println!("total diagonal length: {:.3}", match total_diagonal(&specs) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    println!("3 x 4 -> {}", match diagonal_of_spec("3 x 4") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    println!("5 x 12 -> {}", match diagonal_of_spec("5 x 12") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });

    match describe("7 x -2") {
        Ok(line) => println!("{}", line),
        Err(err) => println!("rejected `7 x -2`: {}", err),
    }

    Ok(())
}

