use std::fmt::{self, Write};

/// Removes every character that is not an ASCII letter.
fn remove_non_alpha(input: &str) -> String {
    input.chars().filter(|c| c.is_ascii_alphabetic()).collect()
}

#[derive(Debug)]
enum ParseError {
    MissingSeparator(String),
    EmptyKey(String),
    NoAlpha(String),
    Format(fmt::Error),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingSeparator(line) => write!(f, "no '=' in {line:?}"),
            ParseError::EmptyKey(line) => write!(f, "key has no letters in {line:?}"),
            ParseError::NoAlpha(line) => write!(f, "value has no letters in {line:?}"),
            ParseError::Format(e) => write!(f, "formatting failed: {e}"),
        }
    }
}

impl From<fmt::Error> for ParseError {
    fn from(e: fmt::Error) -> Self {
        ParseError::Format(e)
    }
}

/// Splits `key = value` into its two trimmed halves.
fn split_entry(line: &str) -> Option<(&str, &str)> {
    let (key, value) = line.split_once('=')?;
    Some((key.trim(), value.trim()))
}

/// Parses a line and strips non-alphabetic noise from both halves.
fn clean_entry(line: &str) -> Result<(String, String), ParseError> {
    let (raw_key, raw_value) =
        split_entry(line).ok_or_else(|| ParseError::MissingSeparator(line.to_string()))?;
    let key = remove_non_alpha(raw_key);
    if key.is_empty() {
        return Err(ParseError::EmptyKey(line.to_string()));
    }
    Ok((key, remove_non_alpha(raw_value)))
}

/// First letter of every whitespace separated word, ignoring punctuation.
fn initials(full_name: &str) -> Option<String> {
    let mut out = String::new();
    for part in full_name.split_whitespace() {
        let letters = remove_non_alpha(part);
        out.push(letters.chars().next()?);
    }
    if out.is_empty() {
        return None;
    }
    Some(out)
}

fn value_initials(line: &str) -> Result<String, ParseError> {
    let (_, raw_value) =
        split_entry(line).ok_or_else(|| ParseError::MissingSeparator(line.to_string()))?;
    initials(raw_value).ok_or_else(|| ParseError::NoAlpha(line.to_string()))
}

fn build_report(lines: &[&str]) -> Result<String, ParseError> {
    let mut out = String::new();
    for line in lines {
        if line.trim().is_empty() {
            continue;
        }
        let (key, value) = clean_entry(line)?;
        writeln!(out, "{key} -> {value}")?;
    }
    Ok(out)
}

fn main() -> Result<(), ParseError> {
    let lines = [
        "greeting = Hello123World!",
        "alphabet-3 = abc-def",
        "",
        "full_name = Ada  P. Lovelace",
    ];
    print!("{}", build_report(&lines)?);
    let tag = value_initials(lines[3])?;
    println!("initials of {} = {tag}", clean_entry(lines[3])?.0);
    Ok(())
}

