use std::collections::HashMap;
use std::error::Error;
use std::fmt;

#[derive(Debug)]
enum ModeError {
    Empty,
    Tie(i32, i32),
    BadNumber(String),
}

impl fmt::Display for ModeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ModeError::Empty => write!(f, "cannot take the mode of an empty sample"),
            ModeError::Tie(a, b) => write!(f, "mode is not unique: {} and {} tie", a, b),
            ModeError::BadNumber(t) => write!(f, "not an integer: {:?}", t),
        }
    }
}

impl Error for ModeError {}

fn parse_row(line: &str) -> Result<Vec<i32>, ModeError> {
    let mut row = Vec::new();
    for token in line.split(',') {
        let text = token.trim();
        row.push(text.parse::<i32>().map_err(|_| ModeError::BadNumber(text.to_string()))?);
    }
    Ok(row)
}

fn parse_dataset(text: &str) -> Result<Vec<Vec<i32>>, ModeError> {
    let mut rows = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        rows.push(parse_row(line)?);
    }
    Ok(rows)
}

fn tally(values: &Vec<i32>) -> HashMap<i32, usize> {
    let mut counts = HashMap::new();
    for &v in values {
        *counts.entry(v).or_insert(0) += 1;
    }
    counts
