use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum DateError {
    Missing(&'static str),
    Field(ParseIntError),
    Extra(String),
    Range(String),
}

impl fmt::Display for DateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DateError::Missing(field) => write!(f, "missing {} in date", field),
            DateError::Field(err) => write!(f, "bad number: {}", err),
            DateError::Extra(text) => write!(f, "unexpected trailing text: {}", text),
            DateError::Range(text) => write!(f, "value out of range: {}", text),
        }
    }
}

fn next_field<'a, I: Iterator<Item = &'a str>>(
    parts: &mut I,
    name: &'static str,
) -> Result<u32, DateError> {
    let raw = parts.next().ok_or(DateError::Missing(name))?;
    let value = raw.trim().parse::<u32>().map_err(DateError::Field)?;
    Ok(value)
}

fn validate(date: (u32, u32, u32)) -> Result<(u32, u32, u32), DateError> {
    let (year, month, day) = date;
    if month < 1 || month > 12 {
        return Err(DateError::Range(format!("month {}", month)));
    }
    if day < 1 || day > 30 {
        return Err(DateError::Range(format!("day {}", day)));
    }
    Ok((year, month, day))
}

fn parse_date(text: &str) -> Result<(u32, u32, u32), DateError> {
    let mut parts = text.split('-');
    let year = next_field(&mut parts, "year")?;
    let month = next_field(&mut parts, "month")?;
    let day = next_field(&mut parts, "day")?;
    if let Some(rest) = parts.next() {
        return Err(DateError::Extra(rest.to_string()));
    }
    validate((year, month, day))
}

fn to_day_number(date: (u32, u32, u32)) -> i32 {
    let (year, month, day) = date;
    year as i32 * 360 + (month as i32 - 1) * 30 + (day as i32 - 1)
}

fn days_between_naive(from: (u32, u32, u32), to: (u32, u32, u32)) -> i32 {
    to_day_number(to) - to_day_number(from)
}

fn days_between_checked(
    from: (u32, u32, u32),
    to: (u32, u32, u32),
) -> Result<i32, DateError> {
    let start = validate(from)?;
    let end = validate(to)?;
    Ok(days_between_naive(start, end))
}

fn span_report(from_text: &str, to_text: &str) -> Result<String, DateError> {
    let from = parse_date(from_text)?;
    let to = parse_date(to_text)?;
    let days = days_between_checked(from, to)?;
    Ok(format!("{} -> {}: {} days", from_text, to_text, days))
}

fn main() -> Result<(), DateError> {
    let pairs = [
        ("2023-1-1", "2023-1-10"),
        ("2023-1-1", "2023-2-1"),
        ("2023-12-30", "2024-1-1"),
        ("2024-3-15", "2023-3-15"),
        ("2023-1-1", "2023-13-1"),
    ];
    for (from, to) in pairs {
        match span_report(from, to) {
            Ok(line) => println!("{}", line),
            Err(err) => println!("{} -> {}: error: {}", from, to, err),
        }
    }
    let decade = span_report("2020-1-1", "2030-1-1")?;
    println!("decade span: {}", decade);
    Ok(())
}

