use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum SentenceError {
    Empty,
    BadSpacing,
    MissingSeparator,
    BadCount(ParseIntError),
    CountMismatch { expected: usize, found: usize },
}

impl fmt::Display for SentenceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SentenceError::Empty => write!(f, "sentence is empty"),
            SentenceError::BadSpacing => write!(f, "words must be separated by single spaces"),
            SentenceError::MissingSeparator => write!(f, "directive needs a ':' separator"),
            SentenceError::BadCount(e) => write!(f, "invalid word count: {e}"),
            SentenceError::CountMismatch { expected, found } => {
                write!(f, "declared {expected} words but found {found}")
            }
        }
    }
}

impl Error for SentenceError {}

impl From<ParseIntError> for SentenceError {
    fn from(e: ParseIntError) -> Self {
        SentenceError::BadCount(e)
    }
}

fn validate_sentence(sentence: &str) -> Result<&str, SentenceError> {
    if sentence.is_empty() {
        return Err(SentenceError::Empty);
    }
    if sentence.split(' ').any(|word| word.is_empty()) {
        return Err(SentenceError::BadSpacing);
    }
    Ok(sentence)
}

pub fn reverse_words_order(input: &str) -> String {
    input.split(' ').rev().collect::<Vec<&str>>().join(" ")
}

fn reverse_checked(input: &str) -> Result<String, SentenceError> {
    Ok(reverse_words_order(validate_sentence(input)?))
}

fn parse_directive(line: &str) -> Result<(usize, &str), SentenceError> {
    let (count, rest) = line.split_once(':').ok_or(SentenceError::MissingSeparator)?;
    let expected: usize = count.trim().parse()?;
    let sentence = validate_sentence(rest.trim())?;
    let found = sentence.split(' ').count();
    if found != expected {
        return Err(SentenceError::CountMismatch { expected, found });
    }
    Ok((expected, sentence))
}

fn format_report(line: &str) -> Result<String, SentenceError> {
    let (count, sentence) = parse_directive(line)?;
    let reversed = reverse_checked(sentence)?;
    Ok(format!("{count} words -> {reversed}"))
}

fn process_batch(text: &str) -> Result<Vec<String>, SentenceError> {
    let mut reports = Vec::new();
    for line in text.lines().map(str::trim).filter(|l| !l.is_empty()) {
        reports.push(format_report(line)?);
    }
    Ok(reports)
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("{}", reverse_checked("hello world")?);
    println!("{}", reverse_checked("rust programming is fun")?);

    let batch = "2: hello world\n4: rust programming is fun\n3: one two three";
    for report in process_batch(batch)? {
        println!("{report}");
