use std::error::Error;
use std::fmt::Write as FmtWrite;
use std::io::{self, Read};
use std::num::ParseIntError;

/// Parses a comma separated list of integers such as "5, 3, 1".
fn parse_vector(spec: &str) -> Result<Vec<i32>, ParseIntError> {
    let mut values = Vec::new();
    for token in spec.split(',').filter(|t| !t.trim().is_empty()) {
        let value = token.trim().parse::<i32>()?;
        values.push(value);
    }
    Ok(values)
}

/// True when no element is smaller than the one that follows it.
/// Empty vectors and single element vectors are trivially sorted.
fn is_sorted_descending(values: &Vec<i32>) -> bool {
    values.windows(2).all(|pair| pair[0] >= pair[1])
}

/// Length of the longest descending stretch inside the vector.
fn longest_descending_run(values: &Vec<i32>) -> usize {
    let mut best = values.len().min(1);
    let mut current = best;
    for pair in values.windows(2) {
        if pair[0] >= pair[1] {
            current += 1;
        } else {
            current = 1;
        }
        best = best.max(current);
    }
    best
}

/// Turns one input specification into a human readable verdict.
fn describe_line(spec: &str) -> Result<String, Box<dyn Error>> {
    let values = parse_vector(spec)?;
    let mut line = String::new();
    write!(line, "{:?}: descending = {}", values, is_sorted_descending(&values))?;
    if let Some((first, last)) = values.first().zip(values.last()) {
        write!(line, " (from {} to {})", first, last)?;
        write!(line, ", longest run = {}", longest_descending_run(&values))?;
    }
    Ok(line)
}

fn report(specs: &[&str]) -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    for spec in specs {
        let line = describe_line(spec)?;
        writeln!(out, "{}", line)?;
    }
    Ok(out)
}

