use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Write};

#[derive(Debug)]
enum CodecError {
    Malformed(String),
    BadShift(String),
    UnknownOp(String),
}

impl fmt::Display for CodecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CodecError::Malformed(line) => {
                write!(f, "expected `<encode|decode> <shift> <text>`, got `{}`", line)
            }
            CodecError::BadShift(field) => write!(f, "`{}` is not a shift in 0..=25", field),
            CodecError::UnknownOp(op) => write!(f, "unknown operation `{}`", op),
        }
    }
}

impl Error for CodecError {}

/// Shifts every ASCII lowercase letter forward by `shift`, wrapping 'z' to 'a'.
/// All other characters are passed through untouched.
pub fn shift_encode(text: &str, shift: u8) -> String {
    let k = shift % 26;
    text.chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                (b'a' + (c as u8 - b'a' + k) % 26) as char
            } else {
                c
            }
        })
        .collect()
}

/// Inverse of `shift_encode` for the same shift amount.
pub fn shift_decode(text: &str, shift: u8) -> String {
    shift_encode(text, 26 - shift % 26)
}

fn parse_shift(field: &str) -> Result<u8, CodecError> {
    let value: u32 = field
        .parse()
        .map_err(|_| CodecError::BadShift(field.to_string()))?;
    if value > 25 {
        return Err(CodecError::BadShift(field.to_string()));
    }
    Ok(value as u8)
}

fn split_directive(line: &str) -> Result<(&str, &str, &str), CodecError> {
    let (op, rest) = line
        .split_once(' ')
        .ok_or_else(|| CodecError::Malformed(line.to_string()))?;
    let (shift_field, payload) = rest
        .split_once(' ')
        .ok_or_else(|| CodecError::Malformed(line.to_string()))?;
    Ok((op, shift_field, payload))
}

fn process_line(line: &str) -> Result<String, CodecError> {
    let (op, shift_field, payload) = split_directive(line)?;
    let shift = parse_shift(shift_field)?;
    match op {
        "encode" => Ok(shift_encode(payload, shift)),
        "decode" => Ok(shift_decode(payload, shift)),
        other => Err(CodecError::UnknownOp(other.to_string())),
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let stdin = io::stdin();
    let mut out = io::stdout();
    for line in stdin.lock().lines() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let result = process_line(trimmed)?;
        writeln!(out, "{}", result)?;
    }
    out.flush()?;
    Ok(())
}

