use std::fmt;

#[derive(Debug)]
enum CountError {
    MissingSeparator(String),
    EmptyNeedle,
}

impl fmt::Display for CountError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CountError::MissingSeparator(line) => write!(f, "no '|' separator in {:?}", line),
            CountError::EmptyNeedle => write!(f, "the needle must not be empty"),
        }
    }
}

/// Counts non-overlapping, case-sensitive occurrences of `needle` in `haystack`.
fn count_substring(haystack: &str, needle: &str) -> usize {
    if needle.is_empty() {
        return 0;
    }
    let mut count = 0;
    let mut rest = haystack;
    while let Some(index) = rest.find(needle) {
        count += 1;
        rest = &rest[index + needle.len()..];
    }
    count
}

fn count_checked(haystack: &str, needle: &str) -> Result<usize, CountError> {
    if needle.is_empty() {
        return Err(CountError::EmptyNeedle);
    }
    Ok(count_substring(haystack, needle))
}

/// Byte offset of the `n`-th (1-based) non-overlapping occurrence.
fn nth_occurrence(haystack: &str, needle: &str, n: usize) -> Option<usize> {
    let mut base = 0;
    let mut rest = haystack;
    for _ in 1..n {
        let index = rest.find(needle)?;
        base += index + needle.len();
        rest = &rest[index + needle.len()..];
    }
    let index = rest.find(needle)?;
    Some(base + index)
}

/// Splits a query of the form `haystack | needle`.
fn parse_query(line: &str) -> Result<(&str, &str), CountError> {
    let (haystack, needle) = line
        .split_once('|')
        .ok_or_else(|| CountError::MissingSeparator(line.to_string()))?;
    Ok((haystack.trim(), needle.trim()))
}

fn format_report(line: &str) -> Result<String, CountError> {
    let (haystack, needle) = parse_query(line)?;
    let count = count_checked(haystack, needle)?;
    let tail = match nth_occurrence(haystack, needle, count) {
        Some(offset) => format!(", last match at byte {}", offset),
        None => String::from(", no match"),
    };
    Ok(format!("{:?} in {:?}: {}{}", needle, haystack, count, tail))
}

fn total_matches(queries: &[&str]) -> Result<usize, CountError> {
    let mut total = 0;
    for query in queries {
        let (haystack, needle) = parse_query(query)?;
        total += count_checked(haystack, needle)?;
    }
    Ok(total)
}

fn run(queries: &[&str]) -> Result<(), CountError> {
    for query in queries {
        println!("{}", format_report(query)?);
    }
    println!("total matches: {}", total_matches(queries)?);
    Ok(())
}

fn main() {
    let queries = [
        "ababab | ab",
        "aaaaa | aa",
        "Mississippi | ss",
        "banana | Na",
    ];
    if let Err(err) = run(&queries) {
        eprintln!("error: {}", err);
    }
}

