use std::env;
use std::error::Error;
use std::fmt;
use std::fs;
use std::fs::File;
use std::io::Write;

/// Builds the times table of `n` from 1 to 10, one line per product.
pub fn generate_times_table(n: u32) -> Vec<String> {
    (1..=10).map(|i| format!("{} x {} = {}", n, i, n * i)).collect()
}

#[derive(Debug)]
pub enum TableError {
    BadNumber(String),
    TooLarge(u32),
    MissingPath,
}

impl fmt::Display for TableError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TableError::BadNumber(text) => write!(f, "invalid multiplicand '{}'", text),
            TableError::TooLarge(n) => write!(f, "multiplicand {} overflows when multiplied by 10", n),
            TableError::MissingPath => write!(f, "--file requires a path argument"),
        }
    }
}

impl Error for TableError {}

/// Reads a user supplied multiplicand, rejecting values whose table would overflow `u32`.
fn parse_request(text: &str) -> Result<u32, TableError> {
    let trimmed = text.trim();
    let n: u32 = trimmed.parse().map_err(|_| TableError::BadNumber(trimmed.to_string()))?;
    if n > u32::MAX / 10 {
        return Err(TableError::TooLarge(n));
    }
    Ok(n)
}

/// Loads one multiplicand per non-blank line of a request file.
fn load_requests(path: &str) -> Result<Vec<u32>, Box<dyn Error>> {
    let text = fs::read_to_string(path)?;
    let mut requests = Vec::new();
    for line in text.lines().filter(|line| !line.trim().is_empty()) {
        requests.push(parse_request(line)?);
    }
    Ok(requests)
}

/// Produces a printable report: a header, the table itself and the sum of products.
fn render_report(n: u32) -> String {
    let mut out = format!("Times table for {}\n", n);
    for row in generate_times_table(n) {
        out.push_str(&format!("  {}\n", row));
    }
    let total: u32 = (1..=10).map(|i| n * i).sum();
    out.push_str(&format!("  sum of products = {}\n", total));
    out
}

fn save_report(path: &str, report: &str) -> std::io::Result<()> {
    let mut file = File::create(path)?;
    file.write_all(report.as_bytes())?;
    file.flush()
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().skip(1).collect();
    let requests: Vec<u32> = match args.split_first() {
        Some((flag, rest)) if flag == "--file" => {
            let path = rest.first().ok_or(TableError::MissingPath)?;
            load_requests(path)?
        }
        Some(_) => {
            let mut parsed = Vec::with_capacity(args.len());
            for arg in &args {
                parsed.push(parse_request(arg)?);
            }
            parsed
        }
        None => vec![2],
    };
    for n in requests {
        let report = render_report(n);
        print!("{}", report);
        save_report(&format!("times_table_{}.txt", n), &report)?;
    }
    Ok(())
}

