fn is_palindrome_ci(s: &str) -> bool {
    let cleaned_chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphabetic())
        .map(|c| c.to_ascii_lowercase())
        .collect();

    let mut left = 0;
    let mut right = cleaned_chars.len();

    while left < right {
        if cleaned_chars[left] != cleaned_chars[right - 1] {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

