use std::fmt::Write;

#[derive(Debug)]
struct Record {
    name: String,
    part: f64,
    whole: f64,
}

fn calculate_percentage(part: f64, whole: f64) -> f64 {
    if whole == 0.0 {
        return 0.0;
    }
    part / whole * 100.0
}

fn parse_field(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|e| format!("'{}' is not a number: {}", trimmed, e))?;
    if value < 0.0 {
        return Err(format!("'{}' must not be negative", trimmed));
    }
    Ok(value)
}

fn parse_record(line: &str) -> Result<Record, String> {
    let mut fields = line.split(',');
    let name = fields.next().ok_or_else(|| "empty line".to_string())?;
    let part_text = fields
        .next()
        .ok_or_else(|| format!("missing part in '{}'", line))?;
    let whole_text = fields
        .next()
        .ok_or_else(|| format!("missing whole in '{}'", line))?;
    let part = parse_field(part_text)?;
    let whole = parse_field(whole_text)?;
    Ok(Record {
        name: name.trim().to_string(),
        part,
        whole,
    })
}

fn parse_table(text: &str) -> Result<Vec<Record>, String> {
    let mut records = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let record = parse_record(line)?;
        records.push(record);
    }
    Ok(records)
}

fn format_row(record: &Record) -> Result<String, String> {
    let share = calculate_percentage(record.part, record.whole);
    let mut row = String::new();
    write!(
        row,
        "{:<10} {:>8.1} / {:>8.1} = {:>6.2}%",
        record.name, record.part, record.whole, share
    )
    .map_err(|e| e.to_string())?;
    Ok(row)
}

fn largest_share(records: &[Record]) -> Option<f64> {
    records
        .iter()
        .map(|r| calculate_percentage(r.part, r.whole))
        .max_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
}

fn build_report(text: &str) -> Result<String, String> {
    let records = parse_table(text)?;
    let mut report = String::new();
    for record in &records {
        let row = format_row(record)?;
        writeln!(report, "{}", row).map_err(|e| e.to_string())?;
    }
    let total_part: f64 = records.iter().map(|r| r.part).sum();
    let total_whole: f64 = records.iter().map(|r| r.whole).sum();
    let overall = calculate_percentage(total_part, total_whole);
    writeln!(report, "overall    {:>6.2}%", overall).map_err(|e| e.to_string())?;
    if let Some(best) = largest_share(&records) {
        writeln!(report, "best       {:>6.2}%", best).map_err(|e| e.to_string())?;
    }
    Ok(report)
}

fn main() -> Result<(), String> {
    let data = "alpha, 25, 100\nbeta, 10, 0\ngamma, 7, 8\n";
    let report = build_report(data)?;
    print!("{}", report);
    Ok(())
}

