use std::env;
use std::fmt::Write as FmtWrite;

/// Highest index whose Fibonacci number still fits in a u64.
const MAX_INDEX: u32 = 93;

/// Parses a textual index and rejects values that cannot be represented.
fn parse_index(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    let value: u32 = trimmed
        .parse()
        .map_err(|err| format!("'{}' is not a valid index: {}", trimmed, err))?;
    if value > MAX_INDEX {
        return Err(format!(
            "index {} is too large: F({}) does not fit in a u64",
            value,
            MAX_INDEX + 1
        ));
    }
    Ok(value)
}

/// All Fibonacci numbers F(0)..=F(upto), computed iteratively.
fn fibonacci_upto(upto: u32) -> Result<Vec<u64>, String> {
    let mut terms = Vec::with_capacity(upto as usize + 1);
    let (mut previous, mut current) = (0u64, 1u64);
    for index in 0..=upto {
        terms.push(previous);
        let next = previous
            .checked_add(current)
            .ok_or_else(|| format!("F({}) overflows u64", index + 2))?;
        previous = current;
        current = next;
    }
    Ok(terms)
}

/// F(0) = 0, F(1) = 1, F(6) = 8.
fn nth_fibonacci(n: u32) -> u64 {
    let terms = fibonacci_upto(n).expect("Fibonacci number exceeds u64 range");
    terms[n as usize]
}

/// Turns one command-line argument into a printable report.
fn format_report(text: &str) -> Result<String, String> {
    let index = parse_index(text)?;
    let terms = fibonacci_upto(index)?;
    let mut report = String::new();
    writeln!(report, "F({}) = {}", index, nth_fibonacci(index)).map_err(|err| err.to_string())?;
    let listed: Vec<String> = terms.iter().map(|term| term.to_string()).collect();
    write!(report, "  sequence: {}", listed.join(", ")).map_err(|err| err.to_string())?;
    Ok(report)
}

fn run() -> Result<(), String> {
    let arguments: Vec<String> = env::args().skip(1).collect();
    if arguments.is_empty() {
        return Err("usage: fibonacci <index> [index ...]".to_string());
    }
    for argument in &arguments {
        println!("{}", format_report(argument)?);
    }
    Ok(())
}

fn main() {
    if let Err(message) = run() {
        eprintln!("error: {}", message);
        std::process::exit(1);
    }
}

