use std::env;
use std::fmt;
use std::fmt::Write as FmtWrite;
use std::fs;
use std::num::ParseFloatError;

#[derive(Debug)]
enum LedgerError {
    Malformed(String),
    BadAmount(ParseFloatError),
    Unknown(String),
    NoTotal,
    Io(String),
    Format,
}

impl fmt::Display for LedgerError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LedgerError::Malformed(line) => write!(f, "malformed ledger entry: {:?}", line),
            LedgerError::BadAmount(e) => write!(f, "bad amount: {}", e),
            LedgerError::Unknown(d) => write!(f, "no such expense: {}", d),
            LedgerError::NoTotal => write!(f, "ledger has no amounts to compare"),
            LedgerError::Io(msg) => write!(f, "cannot read ledger: {}", msg),
            LedgerError::Format => write!(f, "could not build report"),
        }
    }
}

impl From<ParseFloatError> for LedgerError {
    fn from(e: ParseFloatError) -> Self {
        LedgerError::BadAmount(e)
    }
}

impl From<fmt::Error> for LedgerError {
    fn from(_: fmt::Error) -> Self {
        LedgerError::Format
    }
}

fn total_expenses(expenses: &Vec<(String, f64)>) -> f64 {
    expenses.iter().map(|(_, amount)| amount).sum()
}

fn parse_expense(line: &str) -> Result<(String, f64), LedgerError> {
    let (description, amount) = line
        .split_once(',')
        .ok_or_else(|| LedgerError::Malformed(line.to_string()))?;
    let description = description.trim();
    if description.is_empty() {
        return Err(LedgerError::Malformed(line.to_string()));
    }
    let amount: f64 = amount.trim().parse()?;
    Ok((description.to_string(), amount))
}

fn parse_ledger(text: &str) -> Result<Vec<(String, f64)>, LedgerError> {
    let mut expenses = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        expenses.push(parse_expense(line)?);
    }
    Ok(expenses)
}

fn share_of_total(expenses: &Vec<(String, f64)>, description: &str) -> Result<f64, LedgerError> {
    let (_, amount) = expenses
        .iter()
        .find(|(d, _)| d == description)
        .ok_or_else(|| LedgerError::Unknown(description.to_string()))?;
    let total = total_expenses(expenses);
    if total == 0.0 {
        return Err(LedgerError::NoTotal);
    }
    Ok(amount / total * 100.0)
}

fn biggest_item(expenses: &Vec<(String, f64)>) -> Result<String, LedgerError> {
    let (description, _) = expenses
        .iter()
        .max_by(|a, b| a.1.total_cmp(&b.1))
        .ok_or(LedgerError::NoTotal)?;
    let share = share_of_total(expenses, description)?;
    Ok(format!("{} ({:.1}% of the total)", description, share))
}

fn format_report(text: &str, focus: Option<&str>) -> Result<String, LedgerError> {
    let expenses = parse_ledger(text)?;
    let mut out = String::new();
    for (description, amount) in &expenses {
        writeln!(out, "{:<12} {:>8.2}", description, amount)?;
    }
    writeln!(out, "{:<12} {:>8.2}", "TOTAL", total_expenses(&expenses))?;
    if expenses.is_empty() {
        writeln!(out, "largest: none")?;
    } else {
        let item = biggest_item(&expenses)?;
        writeln!(out, "largest: {}", item)?;
    }
    if let Some(description) = focus {
        let share = share_of_total(&expenses, description)?;
        writeln!(out, "{} share: {:.1}%", description, share)?;
    }
    Ok(out)
}

fn main() -> Result<(), LedgerError> {
    let text = match env::args().nth(1) {
        Some(path) => fs::read_to_string(&path).map_err(|e| LedgerError::Io(e.to_string()))?,
        None => "Groceries, 50.5\nFuel, 30.0\nBooks, 12.75\n".to_string(),
    };
    let focus = env::args().nth(2);
    print!("{}", format_report(&text, focus.as_deref())?);
    Ok(())
}

