use std::num::ParseIntError;

#[derive(Debug)]
enum ParseError {
    MissingSeparator(usize),
    BadId(usize, ParseIntError),
    EmptyWord(usize),
    Format(fmt::Error),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingSeparator(n) => write!(f, "line {n}: expected 'id: word'"),
            ParseError::BadId(n, e) => write!(f, "line {n}: bad id ({e})"),
            ParseError::EmptyWord(n) => write!(f, "line {n}: word is empty"),
            ParseError::Format(e) => write!(f, "formatting failed: {e}"),
        }
    }
}

impl From<fmt::Error> for ParseError {
    fn from(e: fmt::Error) -> Self {
        ParseError::Format(e)
    }
}

struct Record {
    id: u32,
    word: String,
}

fn normalized_initial(text: &str) -> Option<char> {
    let first = text.trim_start().chars().next()?;
    Some(first.to_ascii_lowercase())
}

fn starts_with_vowel(text: &str) -> bool {
    matches!(normalized_initial(text), Some('a' | 'e' | 'i' | 'o' | 'u'))
}

fn article_for(word: &str) -> &'static str {
    if starts_with_vowel(word) { "an" } else { "a" }
}

fn parse_record(line_no: usize, line: &str) -> Result<Record, ParseError> {
    let (id_part, word_part) = line
        .split_once(':')
        .ok_or(ParseError::MissingSeparator(line_no))?;
    let id = id_part
        .trim()
        .parse::<u32>()
        .map_err(|e| ParseError::BadId(line_no, e))?;
    let word = word_part.trim();
    if word.is_empty() {
        return Err(ParseError::EmptyWord(line_no));
    }
    Ok(Record { id, word: word.to_string() })
}

fn parse_dataset(text: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();
    for (idx, line) in text.lines().enumerate().filter(|(_, l)| !l.trim().is_empty()) {
        records.push(parse_record(idx + 1, line)?);
    }
    Ok(records)
}

fn longest_vowel_word(records: &[Record]) -> Option<&str> {
    let best = records
        .iter()
        .filter(|r| starts_with_vowel(&r.word))
        .max_by_key(|r| r.word.chars().count())?;
    Some(best.word.as_str())
}

fn build_report(records: &[Record]) -> Result<String, ParseError> {
    let mut out = String::new();
    writeln!(out, "{:<4} {:<12} {:>6}", "id", "word", "vowel")?;
    for record in records {
        let flag = starts_with_vowel(&record.word);
        writeln!(out, "{:<4} {:<12} {:>6}", record.id, record.word, flag)?;
    }
    let vowel_count = records.iter().filter(|r| starts_with_vowel(&r.word)).count();
    writeln!(out, "{vowel_count} of {} start with a vowel", records.len())?;
    if let Some(word) = longest_vowel_word(records) {
        writeln!(out, "longest vowel-initial word: {} {word}", article_for(word))?;
    }
    Ok(out)
}

fn main() -> Result<(), ParseError> {
    let data = "1: Apple\n2: Banana\n3: orange\n4: Umbrella\n5: kiwi\n";
    let records = parse_dataset(data)?;
    print!("{}", build_report(&records)?);
    println!("\"\" -> {}", starts_with_vowel(""));
    Ok(())
}

