use std::fmt::{self, Display, Write};

#[derive(Debug, Clone)]
struct Email {
    local: String,
    host: String,
    tld: String,
}

impl Display for Email {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}@{}.{}", self.local, self.host, self.tld)
    }
}

#[derive(Debug, Clone)]
struct Contact {
    name: String,
    email: Email,
}

/// Splits an address into its parts, reporting why the loose email shape
/// (non-empty local part, '@', host, '.', tld) is not met.
fn parse_email(text: &str) -> Result<Email, String> {
    let trimmed = text.trim();
    let (local, domain) = trimmed
        .split_once('@')
        .ok_or_else(|| format!("no '@' in {trimmed:?}"))?;
    let (host, tld) = domain
        .rsplit_once('.')
        .ok_or_else(|| format!("no '.' in domain {domain:?}"))?;
    if local.is_empty() || host.is_empty() || tld.is_empty() {
        return Err(format!("empty component in {trimmed:?}"));
    }
    Ok(Email {
        local: local.to_string(),
        host: host.to_string(),
        tld: tld.to_string(),
    })
}

pub fn is_valid_email(text: &str) -> bool {
    parse_email(text).is_ok()
}

/// Parses one line of the form `Name <local@host.tld>`.
fn parse_contact(line: &str) -> Result<Contact, String> {
    let line = line.trim();
    let (name, rest) = line
        .split_once('<')
        .ok_or_else(|| format!("missing '<' in {line:?}"))?;
    let address = rest
        .strip_suffix('>')
        .ok_or_else(|| format!("missing '>' in {line:?}"))?;
    let email = parse_email(address)?;
    Ok(Contact {
        name: name.trim().to_string(),
        email,
    })
}

fn parse_contacts(text: &str) -> Result<Vec<Contact>, String> {
    let mut contacts = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        contacts.push(parse_contact(line)?);
    }
    Ok(contacts)
}

fn format_report(contacts: &[Contact]) -> Result<String, fmt::Error> {
    let mut out = String::new();
    writeln!(out, "{} contact(s)", contacts.len())?;
    for contact in contacts {
        writeln!(out, "  {:<6} {}", contact.name, contact.email)?;
    }
    let mut tlds: Vec<&str> = contacts.iter().map(|c| c.email.tld.as_str()).collect();
    tlds.sort_unstable();
    tlds.dedup();
    write!(out, "top-level domains:")?;
    for tld in tlds {
        write!(out, " .{tld}")?;
    }
    writeln!(out)?;
    Ok(out)
}

fn main() -> Result<(), String> {
    for candidate in ["test@example.com", "invalid-email"] {
        println!("{candidate:?} -> {}", is_valid_email(candidate));
    }
    let directory = "Alice <alice@example.com>\nBob <bob@rust-lang.org>\nCarol <carol@mail.example.com>\n";
    let contacts = parse_contacts(directory)?;
    let report = format_report(&contacts).map_err(|e| e.to_string())?;
    print!("{report}");
    Ok(())
}

