use std::fmt;
use std::io::{self, Read};

#[derive(Debug)]
struct GeomError(String);

impl fmt::Display for GeomError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl From<io::Error> for GeomError {
    fn from(e: io::Error) -> Self {
        GeomError(format!("cannot read input: {}", e))
    }
}

pub fn euclidean_distance_2d(x1: f64, y1: f64, x2: f64, y2: f64) -> f64 {
    let dx = x2 - x1;
    let dy = y2 - y1;
    dx.hypot(dy)
}

fn parse_coord(text: &str) -> Result<f64, GeomError> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|e| GeomError(format!("invalid coordinate {:?}: {}", trimmed, e)))?;
    if value.is_finite() {
        Ok(value)
    } else {
        Err(GeomError(format!("coordinate {:?} is not finite", trimmed)))
    }
}

fn parse_point(token: &str) -> Result<(f64, f64), GeomError> {
    let (xs, ys) = token
        .split_once(',')
        .ok_or_else(|| GeomError(format!("point {:?} must look like x,y", token)))?;
    let x = parse_coord(xs)?;
    let y = parse_coord(ys)?;
    Ok((x, y))
}

fn parse_path(spec: &str) -> Result<Vec<(f64, f64)>, GeomError> {
    let points = spec
        .split_whitespace()
        .map(parse_point)
        .collect::<Result<Vec<_>, GeomError>>()?;
    if points.len() < 2 {
        return Err(GeomError("a path needs at least two points".to_string()));
    }
    Ok(points)
}

fn path_length(points: &[(f64, f64)]) -> f64 {
    points
        .windows(2)
        .map(|w| euclidean_distance_2d(w[0].0, w[0].1, w[1].0, w[1].1))
        .sum()
}

fn format_report(spec: &str) -> Result<String, GeomError> {
    let points = parse_path(spec)?;
    let mut report = String::new();
    for w in points.windows(2) {
        let d = euclidean_distance_2d(w[0].0, w[0].1, w[1].0, w[1].1);
        report.push_str(&format!(
            "({}, {}) -> ({}, {}) = {:.4}\n",
            w[0].0, w[0].1, w[1].0, w[1].1, d
        ));
    }
    report.push_str(&format!("total = {:.4}", path_length(&points)));
    Ok(report)
}

fn run() -> Result<(), GeomError> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    for (index, line) in input.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let report = format_report(line)
            .map_err(|e| GeomError(format!("line {}: {}", index + 1, e)))?;
        println!("{}", report);
    }
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {}", e);
        std::process::exit(1);
    }
