use std::fmt::{self, Write};
use std::num::ParseFloatError;

const POUND_IN_KG: f64 = 0.453592;

#[derive(Debug)]
enum ConvError {
    NotANumber(ParseFloatError),
    Negative(f64),
    MissingWeight(String),
    NoRecords,
    Format(fmt::Error),
}

impl fmt::Display for ConvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConvError::NotANumber(e) => write!(f, "not a number: {}", e),
            ConvError::Negative(v) => write!(f, "weight cannot be negative: {}", v),
            ConvError::MissingWeight(l) => write!(f, "record has no weight field: {:?}", l),
            ConvError::NoRecords => write!(f, "no records to summarise"),
            ConvError::Format(e) => write!(f, "formatting failed: {}", e),
        }
    }
}

impl From<ParseFloatError> for ConvError {
    fn from(e: ParseFloatError) -> Self {
        ConvError::NotANumber(e)
    }
}

impl From<fmt::Error> for ConvError {
    fn from(e: fmt::Error) -> Self {
        ConvError::Format(e)
    }
}

fn pounds_to_kilograms(pounds: f64) -> f64 {
    pounds * POUND_IN_KG
}

fn parse_pounds(text: &str) -> Result<f64, ConvError> {
    let value: f64 = text.trim().parse()?;
    if value < 0.0 {
        return Err(ConvError::Negative(value));
    }
    Ok(value)
}

fn convert_line(text: &str) -> Result<String, ConvError> {
    let pounds = parse_pounds(text)?;
    Ok(format!("{} lb = {:.5} kg", pounds, pounds_to_kilograms(pounds)))
}

fn parse_record(line: &str) -> Result<(String, f64), ConvError> {
    let (name, weight) = line
        .rsplit_once(',')
        .ok_or_else(|| ConvError::MissingWeight(line.trim().to_string()))?;
    let pounds = parse_pounds(weight)?;
    Ok((name.trim().to_string(), pounds))
}

fn report(input: &str) -> Result<String, ConvError> {
    let mut records = Vec::new();
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        records.push(parse_record(line)?);
    }
    let heaviest = records
        .iter()
        .max_by(|a, b| a.1.total_cmp(&b.1))
        .ok_or(ConvError::NoRecords)?;
    let mut out = String::new();
    for (name, pounds) in &records {
        writeln!(out, "{:<8} {:>9.3} lb {:>9.3} kg", name, pounds, pounds_to_kilograms(*pounds))?;
    }
    let total: f64 = records.iter().map(|(_, lb)| pounds_to_kilograms(*lb)).sum();
    writeln!(out, "total {:.3} kg over {} crates", total, records.len())?;
    write!(out, "heaviest: {} at {:.3} kg", heaviest.0, pounds_to_kilograms(heaviest.1))?;
    Ok(out)
}

fn main() -> Result<(), ConvError> {
    const MANIFEST: &str = "anvil, 152.5\nfeathers, 3.25\ngravel, 87\n";
    println!("{}", report(MANIFEST)?);
    for entry in ["10", " 2.20462 "] {
        println!("{}", convert_line(entry)?);
    }
    Ok(())
}

