use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum AppError {
    Parse(ParseIntError),
    NotPositive,
}

impl From<ParseIntError> for AppError {
    fn from(e: ParseIntError) -> Self {
        AppError::Parse(e)
    }
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Parse(e) => write!(f, "not a number: {}", e),
            AppError::NotPositive => write!(f, "value must be a positive integer"),
        }
    }
}

fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 || n % 3 == 0 {
        return n == 2 || n == 3;
    }
    let mut k = 5;
    while k.saturating_mul(k) <= n {
        if n % k == 0 || n % (k + 2) == 0 {
            return false;
        }
        k += 6;
    }
    true
}

fn parse_positive(text: &str) -> Result<u64, AppError> {
    let n: u64 = text.trim().parse()?;
    if n == 0 {
        return Err(AppError::NotPositive);
    }
    Ok(n)
}

fn parse_list(line: &str) -> Result<Vec<u64>, AppError> {
    let mut values = Vec::new();
    for token in line.split(',') {
        values.push(parse_positive(token)?);
    }
    Ok(values)
}

fn smallest_factor(n: u64) -> Option<u64> {
    (2..=n).find(|d| n % d == 0)
}

fn classify(text: &str) -> Result<String, AppError> {
    let n = parse_positive(text)?;
    if is_prime(n) {
        return Ok(format!("{} is prime", n));
    }
    match smallest_factor(n) {
        Some(d) => Ok(format!("{} is composite (divisible by {})", n, d)),
        None => Ok(format!("{} is neither prime nor composite", n)),
    }
}

fn summarize(line: &str) -> Result<String, AppError> {
    let values = parse_list(line)?;
    let primes: Vec<String> = values
        .iter()
        .filter(|&&v| is_prime(v))
        .map(|v| v.to_string())
        .collect();
    Ok(format!(
        "{} of {} inputs are prime: [{}]",
        primes.len(),
        values.len(),
        primes.join(", ")
    ))
}

fn nth_prime(text: &str) -> Result<u64, AppError> {
    let index = parse_positive(text)?;
    let mut found = 0;
    let mut candidate = 1;
    while found < index {
        candidate += 1;
        if is_prime(candidate) {
            found += 1;
        }
    }
    Ok(candidate)
}

fn main() -> Result<(), AppError> {
    println!("{}", classify("7")?);
    println!("{}", classify(" 10 ")?);
    println!("{}", classify("1")?);
    println!("{}", summarize("2,3,4,5,6,7,8,9,10")?);
    println!("the 100th prime is {}", nth_prime("100")?);
    match summarize("11,twelve,13") {
        Ok(report) => println!("{}", report),
        Err(e) => println!("rejected input: {}", e),
    }
    Ok(())
}

