/// Iterative factorials with overflow-aware helpers and a small text front-end.

/// Iterative factorial guarded against overflow; returns `None` if the
/// result does not fit into a `u64`.
fn checked_factorial(n: u64) -> Option<u64> {
    let mut acc: u64 = 1;
    for i in 2..=n {
        acc = acc.checked_mul(i)?;
    }
    Some(acc)
}

/// Factorial of a non-negative integer, computed iteratively.
fn factorial(n: u64) -> u64 {
    checked_factorial(n).expect("factorial does not fit into u64")
}

/// Binomial coefficient built from factorials; `None` when `k > n` or when
/// any intermediate factorial overflows.
fn binomial(n: u64, k: u64) -> Option<u64> {
    if k > n {
        return None;
    }
    let numerator = checked_factorial(n)?;
    let lower = checked_factorial(k)?;
    let upper = checked_factorial(n - k)?;
    let denominator = lower.checked_mul(upper)?;
    Some(numerator / denominator)
}

/// Parses one textual argument into a non-negative integer whose factorial
/// still fits into a `u64`.
fn parse_arg(text: &str) -> Result<u64, String> {
    let n: u64 = text
        .trim()
        .parse()
        .map_err(|_| format!("{:?} is not a non-negative integer", text.trim()))?;
    match checked_factorial(n) {
        Some(_) => Ok(n),
        None => Err(format!("{}! overflows u64", n)),
    }
}

fn factorial_line(text: &str) -> Result<String, String> {
    let n = parse_arg(text)?;
    Ok(format!("{}! = {}", n, factorial(n)))
}

fn binomial_line(n_text: &str, k_text: &str) -> Result<String, String> {
    let n = parse_arg(n_text)?;
    let k = parse_arg(k_text)?;
    let c = binomial(n, k).ok_or_else(|| format!("C({}, {}) is undefined", n, k))?;
    let n_fact = factorial_line(n_text)?;
    Ok(format!("C({}, {}) = {}   [{}]", n, k, c, n_fact))
}

fn main() {
    for text in ["0", "1", "5", " 7 ", "20", "abc", "21"] {
        match factorial_line(text) {
            Ok(line) => println!("{}", line),
            Err(err) => println!("error: {}", err),
        }
    }
    for (n_text, k_text) in [("10", "3"), ("20", "10"), ("5", "7")] {
        match binomial_line(n_text, k_text) {
            Ok(line) => println!("{}", line),
            Err(err) => println!("error: {}", err),
        }
    }
}

