    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            AppError::Parse(detail) => write!(f, "not an integer: {}", detail),
            AppError::EmptyRow(line) => write!(f, "row {} contains no numbers", line),
            AppError::NoData => write!(f, "no rows of numbers were supplied"),
            AppError::Io(err) => write!(f, "input error: {}", err),
            AppError::Format(err) => write!(f, "report error: {}", err),
        }
    }
}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        AppError::Io(err)
    }
}

impl From<fmt::Error> for AppError {
    fn from(err: fmt::Error) -> Self {
        AppError::Format(err)
    }
}

fn find_max(numbers: &Vec<i32>) -> i32 {
    let mut largest = numbers[0];
    for &value in numbers.iter().skip(1) {
        if value > largest {
            largest = value;
        }
    }
    largest
}

fn parse_row(line: &str) -> Result<Vec<i32>, AppError> {
    let mut numbers = Vec::new();
    for token in line.split_whitespace() {
        numbers.push(
            token
                .parse::<i32>()
                .map_err(|err| AppError::Parse(format!("{:?} ({})", token, err)))?,
        );
    }
    Ok(numbers)
}

