use std::cmp::Ordering;
use std::fmt;

#[derive(Debug)]
enum RomanError {
    Empty,
    InvalidDigit(char),
    NotAdditive(String),
}

impl fmt::Display for RomanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RomanError::Empty => write!(f, "empty roman numeral"),
            RomanError::InvalidDigit(c) => write!(f, "invalid roman digit '{}'", c),
            RomanError::NotAdditive(s) => write!(f, "'{}' is not purely additive", s),
        }
    }
}

fn digit_value(c: char) -> Result<u32, RomanError> {
    match c {
        'I' => Ok(1),
        'V' => Ok(5),
        'X' => Ok(10),
        other => Err(RomanError::InvalidDigit(other)),
    }
}

fn parse_roman(s: &str) -> Result<u32, RomanError> {
    if s.is_empty() {
        return Err(RomanError::Empty);
    }
    let mut total = 0;
    let mut previous = u32::MAX;
    for c in s.chars() {
        let value = digit_value(c)?;
        if value > previous {
            return Err(RomanError::NotAdditive(s.to_string()));
        }
        previous = value;
        total += value;
    }
    Ok(total)
}

fn roman_to_int(s: &str) -> u32 {
    parse_roman(s).unwrap_or_else(|e| panic!("{}", e))
}

fn format_report(numeral: &str) -> Result<String, RomanError> {
    let value = parse_roman(numeral)?;
    Ok(format!("{:>6} = {:>3}", numeral, value))
}

fn sum_numerals(list: &[&str]) -> Result<u32, RomanError> {
    let mut sum = 0;
    for numeral in list {
        sum += parse_roman(numeral)?;
    }
    Ok(sum)
}

fn compare_numerals(a: &str, b: &str) -> Result<Ordering, RomanError> {
    let left = parse_roman(a)?;
    Ok(left.cmp(&parse_roman(b)?))
}

fn largest_numeral<'a>(list: &[&'a str]) -> Result<&'a str, RomanError> {
    let mut best = *list.first().ok_or(RomanError::Empty)?;
    for numeral in &list[1..] {
        if compare_numerals(numeral, best)? == Ordering::Greater {
            best = numeral;
        }
    }
    Ok(best)
}

fn main() -> Result<(), RomanError> {
    let numerals = ["VII", "XX", "XVI", "XXXII", "III"];
    for numeral in &numerals {
        println!("{}", format_report(numeral)?);
    }
    println!("total  = {}", sum_numerals(&numerals)?);
    println!("larges = {}", largest_numeral(&numerals)?);
    println!("VII as integer = {}", roman_to_int("VII"));
    Ok(())
}

