use std::fmt;

#[derive(Debug)]
enum PairError {
    MissingSeparator(String),
    EmptyWord(String),
}

impl fmt::Display for PairError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PairError::MissingSeparator(line) => write!(f, "no ',' in input line: {line:?}"),
            PairError::EmptyWord(line) => write!(f, "empty word in input line: {line:?}"),
        }
    }
}

fn normalize(s: &str) -> String {
    s.chars()
        .filter(|c| !c.is_whitespace())
        .flat_map(|c| c.to_lowercase())
        .collect()
}

fn sorted_letters(s: &str) -> String {
    let mut chars: Vec<char> = normalize(s).chars().collect();
    chars.sort_unstable();
    chars.into_iter().collect()
}

pub fn is_anagram(a: &str, b: &str) -> bool {
    sorted_letters(a) == sorted_letters(b)
}

fn parse_pair(line: &str) -> Result<(&str, &str), PairError> {
    let (left, right) = line
        .split_once(',')
        .ok_or_else(|| PairError::MissingSeparator(line.to_string()))?;
    let (a, b) = (left.trim(), right.trim());
    if normalize(a).is_empty() || normalize(b).is_empty() {
        return Err(PairError::EmptyWord(line.to_string()));
    }
    Ok((a, b))
}

fn check_pair(line: &str) -> Result<bool, PairError> {
    let (a, b) = parse_pair(line)?;
    Ok(is_anagram(a, b))
}

fn describe(line: &str) -> Result<String, PairError> {
    let (a, b) = parse_pair(line)?;
    let verdict = if is_anagram(a, b) { "are anagrams" } else { "are not anagrams" };
    Ok(format!("{a:?} and {b:?} {verdict}"))
}

fn report(lines: &[&str]) -> Result<Vec<String>, PairError> {
    let mut out = Vec::with_capacity(lines.len());
    for line in lines {
        out.push(describe(line)?);
    }
    Ok(out)
}

fn count_anagram_pairs(lines: &[&str]) -> Result<usize, PairError> {
    let mut total = 0;
    for line in lines {
        if check_pair(line)? {
            total += 1;
        }
    }
    Ok(total)
}

fn anagram_partner<'a>(word: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let index = candidates.iter().position(|c| is_anagram(word, c))?;
    Some(candidates[index])
}

fn partner_report(word: &str, candidates: &[&str]) -> Option<String> {
    let partner = anagram_partner(word, candidates)?;
    Some(format!("{word:?} can be rearranged into {partner:?}"))
}

fn main() -> Result<(), PairError> {
    let lines = ["listen,silent", "hello,world", "Dormitory, Dirty Room"];
    for entry in report(&lines)? {
        println!("{entry}");
