use std::str::Split;

#[derive(Debug)]
struct Loan {
    label: String,
    principal: f64,
    rate: f64,
    time: f64,
}

fn simple_interest(principal: f64, rate: f64, time: f64) -> f64 {
    principal * rate * time
}

fn parse_amount(name: &str, text: &str) -> Result<f64, String> {
    let value: f64 = text
        .trim()
        .parse()
        .map_err(|_| format!("{}: '{}' is not a number", name, text.trim()))?;
    if !value.is_finite() || value < 0.0 {
        return Err(format!("{}: must be finite and non-negative, got {}", name, value));
    }
    Ok(value)
}

fn parse_rate(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    match trimmed.strip_suffix('%') {
        Some(percent) => {
            let value = parse_amount("rate", percent)?;
            Ok(value / 100.0)
        }
        None => parse_amount("rate", trimmed),
    }
}

fn next_field<'a>(fields: &mut Split<'a, char>, name: &str) -> Result<&'a str, String> {
    fields.next().ok_or_else(|| format!("missing {}", name))
}

fn parse_record(line: &str) -> Result<Loan, String> {
    let mut fields = line.split(',');
    let label = next_field(&mut fields, "label")?;
    let principal_text = next_field(&mut fields, "principal")?;
    let principal = parse_amount("principal", principal_text)?;
    let rate_text = next_field(&mut fields, "rate")?;
    let rate = parse_rate(rate_text)?;
    let time_text = next_field(&mut fields, "time")?;
    let time = parse_amount("time", time_text)?;
    if fields.next().is_some() {
        return Err(format!("too many fields in record: '{}'", line));
    }
    Ok(Loan { label: label.trim().to_string(), principal, rate, time })
}

fn describe(loan: &Loan, interest: f64) -> String {
    format!(
        "{:<10} {:>10.2} @ {:>5.2}% for {:>4.1}y -> interest {:>9.2}, total {:>9.2}",
        loan.label,
        loan.principal,
        loan.rate * 100.0,
        loan.time,
        interest,
        loan.principal + interest
    )
}

fn build_report(records: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    let mut total = 0.0;
    for line in records {
        let loan = parse_record(line)?;
        let interest = simple_interest(loan.principal, loan.rate, loan.time);
        total += interest;
        out.push_str(&describe(&loan, interest));
        out.push('\n');
    }
    out.push_str(&format!("{:<10} total interest {:.2}", "ALL", total));
    Ok(out)
}

fn main() -> Result<(), String> {
    let records = ["house, 1000, 0.05, 2", "car, 500, 10%, 1", "boat, 2500, 4.5%, 3.5"];
    let report = build_report(&records)?;
    println!("{}", report);
    Ok(())
}

