fn filter_by_char(items: &Vec<String>, needle: char) -> Vec<String> {
    items
        .iter()
        .filter(|s| s.contains(needle))
        .cloned()
        .collect()
}

fn parse_char(field: &str) -> Result<char, String> {
    let trimmed = field.trim();
    let mut chars = trimmed.chars();
    let first = chars.next().ok_or_else(|| "missing filter character".to_string())?;
    if chars.next().is_some() {
        return Err(format!("expected a single character, got {:?}", trimmed));
    }
    Ok(first)
}

fn parse_words(field: &str) -> Vec<String> {
    field
        .split(',')
        .map(|w| w.trim().to_string())
        .filter(|w| !w.is_empty())
        .collect()
}

fn parse_query(line: &str) -> Result<(char, Vec<String>), String> {
    let (head, tail) = line
        .split_once(':')
        .ok_or_else(|| format!("query {:?} has no ':' separator", line))?;
    let needle = parse_char(head)?;
    let words = parse_words(tail);
    if words.is_empty() {
        return Err(format!("query for {:?} lists no strings", needle));
    }
    Ok((needle, words))
}

fn format_report(line: &str) -> Result<String, String> {
    let (needle, words) = parse_query(line)?;
    let kept = filter_by_char(&words, needle);
    Ok(format!(
        "{}: [{}] ({} of {} kept)",
        needle,
        kept.join(", "),
        kept.len(),
        words.len()
    ))
}

fn expected_count(header: &str) -> Result<usize, String> {
    let count = header
        .trim()
        .parse::<usize>()
        .map_err(|e| format!("bad query count {:?}: {}", header.trim(), e))?;
    Ok(count)
}

fn run(input: &str) -> Result<String, String> {
    let mut lines = input.lines().filter(|l| !l.trim().is_empty());
    let header = lines.next().ok_or_else(|| "input is empty".to_string())?;
    let announced = expected_count(header)?;
    let mut reports = Vec::new();
    for line in lines {
        reports.push(format_report(line)?);
    }
    if reports.len() != announced {
        return Err(format!(
            "header announced {} queries but {} were given",
            announced,
            reports.len()
        ));
    }
    Ok(reports.join("\n"))
}

fn main() -> Result<(), String> {
    let input = "3\n\
                 p: apple, banana\n\
                 z: cat, dog\n\
                 a: banana, cat, dog, kiwi";
    println!("{}", run(input)?);
    Ok(())
}

