fn is_leap_year(year: u32) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

fn parse_year(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    let year: u32 = trimmed
        .parse()
        .map_err(|e| format!("invalid year {trimmed:?}: {e}"))?;
    if year == 0 {
        return Err("the Gregorian calendar has no year 0".to_string());
    }
    Ok(year)
}

fn parse_range(spec: &str) -> Result<(u32, u32), String> {
    let (left, right) = spec
        .split_once('-')
        .ok_or_else(|| format!("range {spec:?} must look like \"1896-1910\""))?;
    let start = parse_year(left)?;
    let end = parse_year(right)?;
    if start > end {
        return Err(format!("range {spec:?} ends before it starts"));
    }
    Ok((start, end))
}

fn days_in_year(year: u32) -> u32 {
    if is_leap_year(year) { 366 } else { 365 }
}

fn month_name(month: u32) -> Result<&'static str, String> {
    const NAMES: [&str; 12] = [
        "January", "February", "March", "April", "May", "June", "July", "August", "September",
        "October", "November", "December",
    ];
    NAMES
        .get(month.wrapping_sub(1) as usize)
        .copied()
        .ok_or_else(|| format!("month {month} is out of range 1..=12"))
}

fn days_in_month(year: u32, month: u32) -> Result<u32, String> {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Ok(31),
        4 | 6 | 9 | 11 => Ok(30),
        2 => Ok(28 + u32::from(is_leap_year(year))),
        other => Err(format!("month {other} is out of range 1..=12")),
    }
}

fn describe_month(year_text: &str, month: u32) -> Result<String, String> {
    let year = parse_year(year_text)?;
    let name = month_name(month)?;
    let days = days_in_month(year, month)?;
    Ok(format!("{name} {year} has {days} days"))
}

fn range_report(spec: &str) -> Result<String, String> {
    let (start, end) = parse_range(spec)?;
    let leaps: Vec<String> = (start..=end)
        .filter(|&y| is_leap_year(y))
        .map(|y| y.to_string())
        .collect();
    Ok(format!("{spec}: {} leap years ({})", leaps.len(), leaps.join(", ")))
}

fn year_report(year_text: &str) -> Result<String, String> {
    let year = parse_year(year_text)?;
    let february = days_in_month(year, 2)?;
    Ok(format!(
        "{year}: leap = {}, {} days, February has {february}",
        is_leap_year(year),
        days_in_year(year)
    ))
}

fn main() {
    for spec in ["2000", "1900", "2024", "0", "twenty"] {
        match year_report(spec) {
            Ok(line) => println!("{line}"),
            Err(err) => println!("error: {err}"),
        }
    }
    for spec in ["1896-1910", "2100-2000"] {
        match range_report(spec) {
            Ok(line) => println!("{line}"),
            Err(err) => println!("error: {err}"),
        }
    }
    for (year, month) in [("2024", 2), ("1900", 2), ("2023", 13)] {
        match describe_month(year, month) {
            Ok(line) => println!("{line}"),
            Err(err) => println!("error: {err}"),
        }
    }
}

