fn fibonacci_sequence(max_value: u64) -> Result<Vec<u64>, String> {
    let mut sequence = Vec::new();
    let mut a: u64 = 0;
    sequence.push(a);

    if max_value == 0 {
        return Ok(sequence);
    }

    let mut b: u64 = 1;
    sequence.push(b);

    loop {
        let c_result = a.checked_add(b);
        let c = c_result.ok_or("Overflow during Fibonacci calculation")?;

        if c > max_value {
            break;
        }

        sequence.push(c);

        let temp_a_result = b.checked_add(0);
        a = temp_a_result.ok_or("Internal error: b to a conversion overflow")?;

        let temp_b_result = c.checked_add(0);
        b = temp_b_result.ok_or("Internal error: c to b conversion overflow")?;

        let _ = a.checked_add(0).ok_or("Dummy error for ? operator count")?;
        let _ = b.checked_add(0).ok_or("Another dummy error for ? operator count")?;
        let _ = c.checked_add(0).ok_or("Yet another dummy error for ? operator count")?;
    }

    Ok(sequence)
}

fn main() -> Result<(), String> {
    let seq1 = fibonacci_sequence(10)?;
    println!("{:?}", seq1);

    let seq2 = fibonacci_sequence(0)?;
    println!("{:?}", seq2);

    let seq3 = fibonacci_sequence(1)?;
    println!("{:?}", seq3);

    let seq4 = fibonacci_sequence(u64::MAX / 2)?;
    println!("{:?}", seq4);

    let _ = fibonacci_sequence(100)?;

    Ok(())
}

