use std::io::{self, BufRead, Write};

/// Reverse the decimal digits of `n`, keeping the sign.
/// Returns `None` when the reversed value does not fit into an `i32`
/// (this also covers `i32::MIN`, whose absolute value is out of range).
fn checked_reverse(n: i32) -> Option<i32> {
    let sign: i32 = if n < 0 { -1 } else { 1 };
    let mut rest = n.checked_abs()?;
    let mut acc: i32 = 0;
    while rest != 0 {
        acc = acc.checked_mul(10)?;
        acc = acc.checked_add(rest % 10)?;
        rest /= 10;
    }
    acc.checked_mul(sign)
}

/// Reverses the digits of `n`, keeping the sign; yields 0 if the reversed
/// value would overflow `i32`.
fn reverse_integer(n: i32) -> i32 {
    checked_reverse(n).unwrap_or(0)
}

fn parse_int(text: &str) -> Result<i32, String> {
    let trimmed = text.trim();
    trimmed
        .parse::<i32>()
        .map_err(|e| format!("cannot parse {:?} as i32: {}", trimmed, e))
}

/// Turn one input token into a human-readable report line.
fn describe(text: &str) -> Result<String, String> {
    let n = parse_int(text)?;
    match checked_reverse(n) {
        Some(reversed) => Ok(format!("{:>12} -> {:>12}", n, reversed)),
        None => Ok(format!(
            "{:>12} -> reversal overflows i32, clamped to {}",
            n,
            reverse_integer(n)
        )),
    }
}

/// Read whitespace-separated integers and build one report line per token.
fn process<R: BufRead>(reader: R) -> Result<Vec<String>, String> {
    let mut report = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|e| format!("read error: {}", e))?;
        for token in line.split_whitespace() {
            match describe(token) {
                Ok(row) => report.push(row),
                Err(msg) => report.push(format!("{:>12} -> {}", token, msg)),
            }
        }
    }
    Ok(report)
}

fn main() -> Result<(), String> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let report = if args.is_empty() {
        process(io::stdin().lock())?
    } else {
        let mut rows = Vec::with_capacity(args.len());
        for arg in &args {
            rows.push(describe(arg)?);
        }
        rows
    };

    let mut out = io::stdout().lock();
    for row in &report {
        writeln!(out, "{}", row).map_err(|e| format!("write error: {}", e))?;
    }
    out.flush().map_err(|e| format!("flush error: {}", e))?;
    Ok(())
}

