fn parse_int_list(text: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for token in text.split(',') {
        let trimmed = token.trim();
        let value: i32 = trimmed
            .parse()
            .map_err(|e| format!("cannot parse {:?}: {}", trimmed, e))?;
        values.push(value);
    }
    Ok(values)
}

fn check_sorted(values: &Vec<i32>) -> Result<(), String> {
    for pair in values.windows(2) {
        if pair[0] > pair[1] {
            return Err(format!("not sorted: {} comes before {}", pair[0], pair[1]));
        }
    }
    Ok(())
}

fn load_sorted(text: &str) -> Result<Vec<i32>, String> {
    let values = parse_int_list(text)?;
    check_sorted(&values)?;
    Ok(values)
}

fn remove_duplicates_sorted(values: &Vec<i32>) -> Vec<i32> {
    let mut unique: Vec<i32> = Vec::new();
    for &value in values.iter() {
        if unique.last() != Some(&value) {
            unique.push(value);
        }
    }
    unique
}

fn span(values: &[i32]) -> Result<i32, String> {
    let first = values
        .first()
        .ok_or_else(|| String::from("empty list has no span"))?;
    let last = values
        .last()
        .ok_or_else(|| String::from("empty list has no span"))?;
    Ok(last - first)
}

fn most_repeated(values: &Vec<i32>) -> Result<(i32, usize), String> {
    let unique = remove_duplicates_sorted(values);
    let best = unique
        .into_iter()
        .map(|candidate| (candidate, values.iter().filter(|&&v| v == candidate).count()))
        .max_by_key(|&(_, count)| count)
        .ok_or_else(|| String::from("empty list has no repeated value"))?;
    Ok(best)
}

fn describe(text: &str) -> Result<String, String> {
    let values = load_sorted(text)?;
    let unique = remove_duplicates_sorted(&values);
    let width = span(&unique)?;
    let (value, count) = most_repeated(&values)?;
    Ok(format!(
        "{:?} -> {:?} (span {}, most repeated {} x{})",
        values, unique, width, value, count
    ))
}

fn report(lines: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    for line in lines {
        out.push_str(&describe(line)?);
        out.push('\n');
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    let inputs = ["1, 1, 2, 3, 3, 3, 4", "5, 5, 5", "-4, -4, 0, 7, 7, 9"];
    let text = report(&inputs)?;
    print!("{}", text);
    let single = load_sorted("2, 2, 8")?;
    println!("deduped once more: {:?}", remove_duplicates_sorted(&single));
    Ok(())
}

