use std::fmt;

#[derive(Debug)]
enum GeoError {
    MissingArrow(String),
    MissingComma(String),
    BadNumber(String),
    TotalOverflow,
}

impl fmt::Display for GeoError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GeoError::MissingArrow(s) => write!(f, "record has no `->` separator: {s:?}"),
            GeoError::MissingComma(s) => write!(f, "point has no `,` separator: {s:?}"),
            GeoError::BadNumber(s) => write!(f, "not a valid i32 coordinate: {s:?}"),
            GeoError::TotalOverflow => write!(f, "sum of distances overflows i32"),
        }
    }
}

fn manhattan_distance_2d(x1: i32, y1: i32, x2: i32, y2: i32) -> i32 {
    (x1 - x2).abs() + (y1 - y2).abs()
}

fn parse_coord(text: &str) -> Result<i32, GeoError> {
    let trimmed = text.trim();
    trimmed
        .parse::<i32>()
        .map_err(|_| GeoError::BadNumber(trimmed.to_string()))
}

fn parse_point(field: &str) -> Result<(i32, i32), GeoError> {
    let (left, right) = field
        .split_once(',')
        .ok_or_else(|| GeoError::MissingComma(field.trim().to_string()))?;
    let x = parse_coord(left)?;
    let y = parse_coord(right)?;
    Ok((x, y))
}

fn distance_of_record(record: &str) -> Result<i32, GeoError> {
    let (first, second) = record
        .split_once("->")
        .ok_or_else(|| GeoError::MissingArrow(record.trim().to_string()))?;
    let (x1, y1) = parse_point(first)?;
    let (x2, y2) = parse_point(second)?;
    Ok(manhattan_distance_2d(x1, y1, x2, y2))
}

fn format_line(label: &str, distance: i32) -> String {
    format!("{label:<20} d = {distance}")
}

fn report(records: &[&str]) -> Result<String, GeoError> {
    let mut lines = Vec::with_capacity(records.len() + 1);
    let mut total = 0i32;
    for record in records {
        let distance = distance_of_record(record)?;
        lines.push(format_line(record.trim(), distance));
        total = total
            .checked_add(distance)
            .ok_or(GeoError::TotalOverflow)?;
    }
    lines.push(format_line("total", total));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), GeoError> {
    let records = ["0,0 -> 3,4", "1,1 -> 1,5", "-7,2 -> 10,-3"];
    println!("{}", report(&records)?);
    let (x, y) = parse_point("2, 9")?;
    println!("{}", format_line("origin -> 2,9", manhattan_distance_2d(0, 0, x, y)));
    Ok(())
}

