fn distance_of_record(record: &str) -> Result<i32, GeoError> {
    let (first, second) = match record
        .split_once("->")
        .ok_or_else(|| GeoError::MissingArrow(record.trim().to_string())) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let (x1, y1) = match parse_point(first) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let (x2, y2) = match parse_point(second) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(manhattan_distance_2d(x1, y1, x2, y2))
}

fn format_line(label: &str, distance: i32) -> String {
    format!("{label:<20} d = {distance}")
}

fn report(records: &[&str]) -> Result<String, GeoError> {
    let mut lines = Vec::with_capacity(records.len() + 1);
    let mut total = 0i32;
    for record in records {
        let distance = match distance_of_record(record) { Ok(v) => v, Err(e) => return Err(e.into()) };
        lines.push(format_line(record.trim(), distance));
        total = match total
            .checked_add(distance)
            .ok_or(GeoError::TotalOverflow) { Ok(v) => v, Err(e) => return Err(e.into()) };
    }
    lines.push(format_line("total", total));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), GeoError> {
    let records = ["0,0 -> 3,4", "1,1 -> 1,5", "-7,2 -> 10,-3"];
    println!("{}", match report(&records) { Ok(v) => v, Err(e) => return Err(e.into()) });
    let (x, y) = match parse_point("2, 9") { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("{}", format_line("origin -> 2,9", manhattan_distance_2d(0, 0, x, y)));
    Ok(())
}

