use std::collections::HashSet;
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct EmptyInputError;

impl fmt::Display for EmptyInputError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Input vector cannot be empty")
    }
}

impl Error for EmptyInputError {}

fn smallest_missing_positive(nums: &Vec<i32>) -> Result<i32, Box<dyn Error>> {
    if nums.is_empty() {
        return Err(Box::new(EmptyInputError));
    }
    let mut seen = HashSet::new();
    for &num in nums {
        if num > 0 {
            seen.insert(num);
        }
    }
    let mut i = 1;
    loop {
        if !seen.contains(&i) {
            return Ok(i);
        }
        i = i.checked_add(1).ok_or("Integer overflow")?;
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let test1 = vec![1, 2, 0];
    let result1 = smallest_missing_positive(&test1)?;
    println!("{}", result1); // Expected: 3

    let test2 = vec![3, 4, -1, 1];
    let result2 = smallest_missing_positive(&test2)?;
    println!("{}", result2); // Expected: 2

    let test3 = vec![7, 8, 9, 11, 12];
    let result3 = smallest_missing_positive(&test3)?;
    println!("{}", result3); // Expected: 1

    let test4 = vec![1, 2, 3, 4, 5];
    let result4 = smallest_missing_positive(&test4)?;
    println!("{}", result4); // Expected: 6

    let test5 = vec![];
    match smallest_missing_positive(&test5) {
        Ok(_) => println!("Unexpected success for empty input"),
        Err(e) => println!("Error for empty input: {}", e),
    }

    let test6 = vec![-5, -2, -10];
    let result6 = smallest_missing_positive(&test6)?;
    println!("{}", result6); // Expected: 1

    Ok(())
}

