struct Investment {
    label: String,
    principal: f64,
    rate: f64,
    periods: u32,
}

fn compound_interest(principal: f64, rate: f64, periods: u32) -> f64 {
    principal * (1.0 + rate).powi(periods as i32)
}

fn validated_future_value(principal: f64, rate: f64, periods: u32) -> Result<f64, String> {
    if !principal.is_finite() || principal < 0.0 {
        return Err(format!("principal must be a non-negative number, got {principal}"));
    }
    if !rate.is_finite() || rate <= -1.0 {
        return Err(format!("rate must be finite and greater than -1, got {rate}"));
    }
    Ok(compound_interest(principal, rate, periods))
}

fn next_field<'a, I: Iterator<Item = &'a str>>(fields: &mut I, name: &str) -> Result<&'a str, String> {
    fields
        .next()
        .map(str::trim)
        .ok_or_else(|| format!("missing field `{name}`"))
}

fn parse_investment(line: &str) -> Result<Investment, String> {
    let mut fields = line.split(',');
    let label = next_field(&mut fields, "label")?.to_string();
    let principal_text = next_field(&mut fields, "principal")?;
    let principal = principal_text
        .parse::<f64>()
        .map_err(|e| format!("bad principal `{principal_text}`: {e}"))?;
    let rate_text = next_field(&mut fields, "rate")?;
    let rate = rate_text
        .parse::<f64>()
        .map_err(|e| format!("bad rate `{rate_text}`: {e}"))?;
    let periods_text = next_field(&mut fields, "periods")?;
    let periods = periods_text
        .parse::<u32>()
        .map_err(|e| format!("bad periods `{periods_text}`: {e}"))?;
    Ok(Investment { label, principal, rate, periods })
}

fn report_row(investment: &Investment) -> Result<String, String> {
    let future = validated_future_value(investment.principal, investment.rate, investment.periods)?;
    let earned = future - investment.principal;
    Ok(format!(
        "{:<12} {:>10.2} @ {:>6.2}% x {:>2} -> {:>10.2} (interest {:>9.2})",
        investment.label, investment.principal, investment.rate * 100.0, investment.periods, future, earned
    ))
}

fn build_report(data: &str) -> Result<Vec<String>, String> {
    let mut rows = Vec::new();
    for line in data.lines().filter(|l| !l.trim().is_empty()) {
        let investment = parse_investment(line)?;
        rows.push(report_row(&investment)?);
    }
    Ok(rows)
}

fn periods_to_reach(principal: f64, rate: f64, target: f64) -> Result<u32, String> {
    if rate <= 0.0 || principal <= 0.0 {
        return Err("reaching a target needs a positive principal and rate".to_string());
    }
    let mut periods = 0u32;
    while validated_future_value(principal, rate, periods)? < target {
        periods += 1;
    }
    Ok(periods)
}

fn main() -> Result<(), String> {
    const DATA: &str = "savings, 1000, 0.05, 1\n\
                        savings, 1000, 0.05, 2\n\
                        bond, 2500.5, 0.037, 10\n\
                        deposit, 750, 0.0125, 24";
    for row in build_report(DATA)? {
        println!("{row}");
    }
    let doubling = periods_to_reach(1000.0, 0.05, 2000.0)?;
    println!("1000.00 at 5.00% doubles after {doubling} periods");
    Ok(())
}

