const ALPHANUM: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const MAX_LEN: usize = 4096;
const FALLBACK_SEED: u64 = 0x9E37_79B9_7F4A_7C15;

#[derive(Debug)]
enum LengthError {
    NotANumber(String, ParseIntError),
    TooLong(usize),
}

impl Display for LengthError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LengthError::NotANumber(arg, e) => write!(f, "invalid length {arg:?}: {e}"),
            LengthError::TooLong(n) => write!(f, "length {n} exceeds maximum of {MAX_LEN}"),
        }
    }
}

impl Error for LengthError {}

fn now_nanos() -> Result<u128, SystemTimeError> {
    Ok(SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos())
}

struct Rng {
    state: u64,
}

impl Rng {
    fn with_seed(seed: u64) -> Rng {
        Rng { state: seed | 1 }
    }

    fn from_time() -> Result<Rng, SystemTimeError> {
        Ok(Rng::with_seed(now_nanos()? as u64))
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.state = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
}

