    let mut rng = Rng::from_time().unwrap_or_else(|_| Rng::with_seed(FALLBACK_SEED));
    let mut out = String::with_capacity(length);
    for _ in 0..length {
        let idx = (rng.next_u64() % ALPHANUM.len() as u64) as usize;
        out.push(ALPHANUM[idx] as char);
    }
    out
}

