use std::env;
use std::error::Error;
use std::fmt::Write as _;

/// Sum of the integers from 1 to `n`, or `None` if the result (or the
/// intermediate product) does not fit in a `u32`.
fn checked_triangular(n: u32) -> Option<u32> {
    let successor = n.checked_add(1)?;
    let product = n.checked_mul(successor)?;
    Some(product / 2)
}

/// The Nth triangular number.
fn triangular_number(n: u32) -> u32 {
    checked_triangular(n).expect("triangular number does not fit in a u32")
}

/// Largest `r` with `r * r <= v`.
fn integer_sqrt(v: u32) -> u32 {
    let mut r = (v as f64).sqrt() as u32;
    while r.saturating_mul(r) > v {
        r -= 1;
    }
    while (r + 1).saturating_mul(r + 1) <= v {
        r += 1;
    }
    r
}

/// Inverse of `triangular_number`: the index `n` such that `T(n) == value`,
/// or `None` when `value` is not triangular.
fn triangular_index(value: u32) -> Option<u32> {
    let eight_v = value.checked_mul(8)?;
    let discriminant = eight_v.checked_add(1)?;
    let root = integer_sqrt(discriminant);
    if root * root != discriminant {
        return None;
    }
    Some((root - 1) / 2)
}

fn parse_limit(text: &str) -> Result<u32, Box<dyn Error>> {
    let n: u32 = text.trim().parse()?;
    match checked_triangular(n) {
        Some(_) => Ok(n),
        None => Err(format!("T({n}) does not fit in a u32").into()),
    }
}

fn table(limit: u32) -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    for n in 1..=limit {
        let t = checked_triangular(n).ok_or("triangular number out of range")?;
        writeln!(out, "T({n:>3}) = {t}")?;
    }
    Ok(out)
}

fn describe(value: u32) -> Result<String, Box<dyn Error>> {
    let n = triangular_index(value).ok_or(format!("{value} is not triangular"))?;
    let mut out = String::new();
    write!(out, "{value} = T({n}) = sum of 1..={n}")?;
    Ok(out)
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().skip(1).collect();
    let limit = match args.first() {
        Some(text) => parse_limit(text)?,
        None => 10,
    };
    print!("{}", table(limit)?);

    let probe = match args.get(1) {
        Some(text) => text.trim().parse()?,
        None => triangular_number(limit),
    };
    match describe(probe) {
        Ok(line) => println!("{line}"),
        Err(why) => println!("{why}"),
    }
    Ok(())
}

