use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    MissingSeparator(usize),
    EmptyKey(usize),
    MissingKey(String),
    BadNumber(String, ParseIntError),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingSeparator(n) => write!(f, "line {}: expected 'key = value'", n),
            ConfigError::EmptyKey(n) => write!(f, "line {}: key is empty", n),
            ConfigError::MissingKey(k) => write!(f, "missing key '{}'", k),
            ConfigError::BadNumber(k, e) => write!(f, "key '{}': {}", k, e),
        }
    }
}

fn trim_string(input: &str) -> String {
    input.trim().to_string()
}

fn split_entry(line: &str, number: usize) -> Result<(String, String), ConfigError> {
    let (raw_key, raw_value) = line
        .split_once('=')
        .ok_or(ConfigError::MissingSeparator(number))?;
    let key = trim_string(raw_key);
    if key.is_empty() {
        return Err(ConfigError::EmptyKey(number));
    }
    Ok((key, trim_string(raw_value)))
}

fn parse_config(text: &str) -> Result<Vec<(String, String)>, ConfigError> {
    let mut entries = Vec::new();
    for (index, line) in text.lines().enumerate() {
        let cleaned = trim_string(line);
        if cleaned.is_empty() || cleaned.starts_with('#') {
            continue;
        }
        entries.push(split_entry(&cleaned, index + 1)?);
    }
    Ok(entries)
}

fn lookup<'a>(entries: &'a [(String, String)], key: &str) -> Result<&'a str, ConfigError> {
    entries
        .iter()
        .find(|(k, _)| k == key)
        .map(|(_, v)| v.as_str())
        .ok_or_else(|| ConfigError::MissingKey(key.to_string()))
}

fn lookup_number(entries: &[(String, String)], key: &str) -> Result<i64, ConfigError> {
    let raw = lookup(entries, key)?;
    raw.parse::<i64>()
        .map_err(|e| ConfigError::BadNumber(key.to_string(), e))
}

fn render_report(text: &str) -> Result<String, ConfigError> {
    let entries = parse_config(text)?;
    let host = lookup(&entries, "host")?;
    let port = lookup_number(&entries, "port")?;
    let retries = lookup_number(&entries, "retries")?;
    Ok(format!("{}:{} (retries: {})", host, port, retries))
}

fn main() -> Result<(), ConfigError> {
    println!("[{}]", trim_string("  hello world  "));
