use std::collections::BTreeMap;

/// Frequency table of the dataset, keyed in ascending numeric order.
fn tally(values: &Vec<i32>) -> BTreeMap<i32, usize> {
    let mut counts = BTreeMap::new();
    for v in values {
        *counts.entry(*v).or_insert(0) += 1;
    }
    counts
}

/// Highest frequency in the dataset, or `None` when it is empty.
fn max_frequency(values: &Vec<i32>) -> Option<usize> {
    tally(values).into_values().max()
}

/// All elements sharing the highest frequency; `None` for an empty dataset.
fn try_find_modes(values: &Vec<i32>) -> Option<Vec<i32>> {
    let counts = tally(values);
    let best = counts.values().copied().max()?;
    Some(
        counts
            .into_iter()
            .filter(|(_, n)| *n == best)
            .map(|(value, _)| value)
            .collect(),
    )
}

pub fn find_modes(values: &Vec<i32>) -> Vec<i32> {
    try_find_modes(values).unwrap_or_default()
}

/// Reads a dataset written as comma-separated integers.
fn parse_dataset(line: &str) -> Result<Vec<i32>, String> {
    let mut data = Vec::new();
    for token in line.split(',') {
        let text = token.trim();
        let value: i32 = text.parse().map_err(|e| format!("bad value {text:?}: {e}"))?;
        data.push(value);
    }
    Ok(data)
}

/// One-line report: the modes of a dataset and how often they occur.
fn describe(line: &str) -> Result<String, String> {
    let data = parse_dataset(line)?;
    let freq = max_frequency(&data).ok_or_else(|| "dataset is empty".to_string())?;
    let modes = find_modes(&data);
    let listed: Vec<String> = modes.iter().map(|m| m.to_string()).collect();
    Ok(format!("[{line}] -> modes {} (each appearing {freq}x)", listed.join(", ")))
}

/// The single mode of a dataset, if the data is not multi-modal.
fn unique_mode(line: &str) -> Result<Option<i32>, String> {
    let data = parse_dataset(line)?;
    let modes = find_modes(&data);
    Ok(if modes.len() == 1 { modes.first().copied() } else { None })
}

/// Modes of every dataset merged into one pool.
fn pooled_modes(lines: &[&str]) -> Result<Vec<i32>, String> {
    let mut pool = Vec::new();
    for line in lines {
        pool.extend(parse_dataset(line)?);
    }
    Ok(find_modes(&pool))
}

fn main() -> Result<(), String> {
    let datasets = ["1, 2, 2, 3, 3, 4", "5, 5, 5", "9, 8, 7, 8", "7, x, 9"];

    for line in datasets {
        match describe(line) {
            Ok(report) => println!("{report}"),
            Err(err) => eprintln!("[{line}] -> skipped: {err}"),
        }
        if let Ok(Some(value)) = unique_mode(line) {
            println!("    unique mode: {value}");
        }
    }

    let pooled = pooled_modes(&datasets[..3])?;
    println!("pooled modes: {pooled:?}");
    Ok(())
}

