use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum MeasurementError {
    MissingField(&'static str),
    BadNumber(ParseFloatError),
    NonPositive { field: &'static str, value: f64 },
    NoRecords,
}

impl fmt::Display for MeasurementError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MeasurementError::MissingField(name) => write!(f, "missing field: {}", name),
            MeasurementError::BadNumber(e) => write!(f, "invalid number: {}", e),
            MeasurementError::NonPositive { field, value } => {
                write!(f, "{} must be positive, got {}", field, value)
            }
            MeasurementError::NoRecords => write!(f, "no records to summarise"),
        }
    }
}

impl From<ParseFloatError> for MeasurementError {
    fn from(e: ParseFloatError) -> Self {
        MeasurementError::BadNumber(e)
    }
}

struct Record {
    name: String,
    weight_kg: f64,
    height_m: f64,
}

fn calculate_bmi(weight_kg: f64, height_m: f64) -> f64 {
    weight_kg / (height_m * height_m)
}

fn next_number(
    parts: &mut dyn Iterator<Item = &str>,
    field: &'static str,
) -> Result<f64, MeasurementError> {
    let text = parts.next().ok_or(MeasurementError::MissingField(field))?;
    let value: f64 = text.parse()?;
    if value <= 0.0 {
        return Err(MeasurementError::NonPositive { field, value });
    }
    Ok(value)
}

fn parse_record(line: &str) -> Result<Record, MeasurementError> {
    let mut parts = line.split(',').map(str::trim);
    let name = parts.next().ok_or(MeasurementError::MissingField("name"))?;
    let name = name.to_string();
    let weight_kg = next_number(&mut parts, "weight")?;
    let height_m = next_number(&mut parts, "height")?;
    Ok(Record { name, weight_kg, height_m })
}

fn bmi_category(bmi: f64) -> &'static str {
    if bmi < 18.5 {
        "underweight"
    } else if bmi < 25.0 {
        "normal"
    } else if bmi < 30.0 {
        "overweight"
    } else {
        "obese"
    }
}

fn describe(line: &str) -> Result<String, MeasurementError> {
    let record = parse_record(line)?;
    let bmi = calculate_bmi(record.weight_kg, record.height_m);
    Ok(format!("{:<8} BMI {:.2} ({})", record.name, bmi, bmi_category(bmi)))
}

fn bmi_spread(lines: &[&str]) -> Result<f64, MeasurementError> {
    let first = lines.first().ok_or(MeasurementError::NoRecords)?;
    let start = parse_record(first)?;
    let mut lowest = calculate_bmi(start.weight_kg, start.height_m);
    let mut highest = lowest;
    for line in &lines[1..] {
        let record = parse_record(line)?;
        let bmi = calculate_bmi(record.weight_kg, record.height_m);
        lowest = lowest.min(bmi);
        highest = highest.max(bmi);
    }
    Ok(highest - lowest)
}

fn main() -> Result<(), MeasurementError> {
    let data = ["Ann, 70.0, 1.75", "Bob, 90.0, 1.80", "Cleo, 52.5, 1.68"];
    for line in &data {
        println!("{}", describe(line)?);
    }
    println!("spread: {:.2}", bmi_spread(&data)?);
    Ok(())
}

