use std::collections::BTreeSet;
use std::fmt;

#[derive(Debug)]
enum PermError {
    MissingAssignment(String),
    UnknownKey(String),
    EmptyWord,
    TooLong(usize),
    NotAlphanumeric(char),
}

/// Reads a request line of the form `word = abc` and returns the word.
fn parse_request(line: &str) -> Result<&str, PermError> {
    let (key, value) = match line
        .split_once('=')
        .ok_or_else(|| PermError::MissingAssignment(line.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    if key.trim() != "word" {
        return Err(PermError::UnknownKey(key.trim().to_string()));
    }
    Ok(value.trim())
}

fn validate(word: &str) -> Result<Vec<char>, PermError> {
    let chars: Vec<char> = word.chars().collect();
    if chars.is_empty() {
        return Err(PermError::EmptyWord);
    }
    if chars.len() > 4 {
        return Err(PermError::TooLong(chars.len()));
    }
    if let Some(&bad) = chars.iter().find(|c| !c.is_alphanumeric()) {
        return Err(PermError::NotAlphanumeric(bad));
    }
    Ok(chars)
}

fn permute(remaining: &[char], prefix: &mut String, out: &mut BTreeSet<String>) {
    if remaining.is_empty() {
        out.insert(prefix.clone());
        return;
    }
    for i in 0..remaining.len() {
        let mut rest = remaining.to_vec();
        let c = rest.remove(i);
        prefix.push(c);
        permute(&rest, prefix, out);
        prefix.pop();
    }
}

fn checked_permutations(word: &str) -> Result<Vec<String>, PermError> {
    let chars = match validate(word) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let mut out = BTreeSet::new();
    permute(&chars, &mut String::new(), &mut out);
    Ok(out.into_iter().collect())
}

pub fn string_permutations(word: &str) -> Vec<String> {
    checked_permutations(word).unwrap_or_default()
}

struct Report {
    word: String,
    perms: Vec<String>,
}

fn build_report(line: &str) -> Result<Report, PermError> {
    let word = match parse_request(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let perms = match checked_permutations(word) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(Report { word: word.to_string(), perms })
}

impl fmt::Display for Report {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match writeln!(f, "{}: {} distinct permutation(s)", self.word, self.perms.len()) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        write!(f, "  {}", self.perms.join(", "))
    }
}

fn main() -> Result<(), PermError> {
    let requests = "word = ab\nword=a\nword = aab\nword = xyz";
    for line in requests.lines() {
        let report = match build_report(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        println!("{}", report);
    }
    println!("direct call: {:?}", string_permutations("ab"));
    Ok(())
}

