/// Keeps only the `Some` values of the input, dropping every `None`.
fn flatten_options(items: Vec<Option<i32>>) -> Vec<i32> {
    items.into_iter().flatten().collect()
}

/// A cell is either a missing marker (`-` or empty) or a decimal integer.
fn parse_cell(token: &str) -> Result<Option<i32>, std::num::ParseIntError> {
    let trimmed = token.trim();
    if trimmed.is_empty() || trimmed == "-" {
        return Ok(None);
    }
    let value = trimmed.parse::<i32>()?;
    Ok(Some(value))
}

/// Parses a comma separated row into the optional values it contains.
fn parse_row(row: &str) -> Result<Vec<Option<i32>>, std::num::ParseIntError> {
    let mut cells = Vec::new();
    for token in row.split(',') {
        let cell = parse_cell(token)?;
        cells.push(cell);
    }
    Ok(cells)
}

/// The measurements of a row, with the missing cells removed.
fn row_values(row: &str) -> Result<Vec<i32>, std::num::ParseIntError> {
    let cells = parse_row(row)?;
    Ok(flatten_options(cells))
}

/// `None` when nothing survived the flattening step.
fn summarize(values: &[i32]) -> Option<String> {
    if values.is_empty() {
        return None;
    }
    let mut lo = values[0];
    let mut hi = values[0];
    let mut total: i64 = 0;
    for &value in values {
        if value < lo {
            lo = value;
        }
        if value > hi {
            hi = value;
        }
        total += value as i64;
    }
    let mean = total as f64 / values.len() as f64;
    Some(format!(
        "n={} mean={:.2} span={} peak={}",
        values.len(),
        mean,
        hi - lo,
        hi
    ))
}

fn report_line(label: &str, row: &str) -> Result<String, std::num::ParseIntError> {
    let values = row_values(row)?;
    let body = summarize(&values).unwrap_or_else(|| String::from("no data"));
    Ok(format!("{label:<10} {body}"))
}

fn report_table(rows: &[(&str, &str)]) -> Result<String, std::num::ParseIntError> {
    let mut out = String::new();
    for (label, row) in rows {
        let line = report_line(label, row)?;
        out.push_str(&line);
        out.push('\n');
    }
    Ok(out)
}

fn main() {
    println!("{:?}", flatten_options(vec![Some(1), None, Some(2)]));
    println!("{:?}", flatten_options(vec![None, None]));

    let rows = [
        ("monday", "3, -, 9, 12"),
        ("tuesday", "-, -, -"),
        ("wednesday", "-4, 0, 7,"),
    ];
    match report_table(&rows) {
        Ok(table) => print!("{table}"),
        Err(err) => eprintln!("malformed table: {err}"),
    }
}

