use std::fmt;

#[derive(Debug)]
enum DateError {
    Format(String),
    NotANumber(String),
    BadMonth(u32),
    BadDay(u32, u32, u32),
    Order,
}

impl fmt::Display for DateError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            DateError::Format(s) => write!(f, "expected YYYY-MM-DD, got {:?}", s),
            DateError::NotANumber(s) => write!(f, "{:?} is not a number", s),
            DateError::BadMonth(m) => write!(f, "month {} is out of range", m),
            DateError::BadDay(y, m, d) => write!(f, "day {} does not exist in {}-{:02}", d, y, m),
            DateError::Order => write!(f, "first date must not be after second date"),
        }
    }
}

fn parse_u32(text: &str) -> Result<u32, DateError> {
    text.trim().parse::<u32>().map_err(|_| DateError::NotANumber(text.to_string()))
}

fn parse_date(text: &str) -> Result<(u32, u32, u32), DateError> {
    let parts: Vec<&str> = text.trim().split('-').collect();
    if parts.len() != 3 {
        return Err(DateError::Format(text.to_string()));
    }
    let year = parse_u32(parts[0])?;
    let month = parse_u32(parts[1])?;
    let day = parse_u32(parts[2])?;
    Ok((year, month, day))
}

fn is_leap(year: u32) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

fn days_in_month(year: u32, month: u32) -> Result<u32, DateError> {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Ok(31),
        4 | 6 | 9 | 11 => Ok(30),
        2 if is_leap(year) => Ok(29),
        2 => Ok(28),
        other => Err(DateError::BadMonth(other)),
    }
}

fn validate(date: (u32, u32, u32)) -> Result<(), DateError> {
    let (year, month, day) = date;
    let limit = days_in_month(year, month)?;
    if day == 0 || day > limit {
        return Err(DateError::BadDay(year, month, day));
    }
    Ok(())
}

fn to_ordinal(date: (u32, u32, u32)) -> i64 {
    let (y, m, d) = (date.0 as i64, date.1 as i64, date.2 as i64);
    let y = if m <= 2 { y - 1 } else { y };
    let era = y / 400;
    let yoe = y - era * 400;
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn days_between(date1: (u32, u32, u32), date2: (u32, u32, u32)) -> i64 {
    to_ordinal(date2) - to_ordinal(date1)
}

fn days_between_checked(
    date1: (u32, u32, u32),
    date2: (u32, u32, u32),
) -> Result<i64, DateError> {
    validate(date1)?;
    validate(date2)?;
    let span = days_between(date1, date2);
    if span < 0 {
        return Err(DateError::Order);
    }
    Ok(span)
}

fn report_line(line: &str) -> Result<String, DateError> {
    let (left, right) = line.split_once("..").ok_or_else(|| DateError::Format(line.to_string()))?;
    let date1 = parse_date(left)?;
    let date2 = parse_date(right)?;
    let span = days_between_checked(date1, date2)?;
    Ok(format!("{} .. {}  =>  {} day(s)", left.trim(), right.trim(), span))
}

fn main() {
    let ranges = [
        "2023-01-01..2023-01-05",
        "2023-01-01..2023-01-01",
        "2000-02-28..2000-03-01",
        "1900-02-28..1900-03-01",
        "1970-01-01..2024-06-17",
        "2023-02-29..2023-03-01",
    ];
    for range in ranges {
        match report_line(range) {
            Ok(text) => println!("{}", text),
            Err(err) => println!("{}: error: {}", range, err),
        }
    }
}

