use std::fmt;

#[derive(Debug)]
enum ConvError {
    BadBase(u8),
    BadDigit(char),
    Overflow,
    MissingField(&'static str),
}

impl fmt::Display for ConvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConvError::BadBase(b) => write!(f, "base {} is outside 2..=16", b),
            ConvError::BadDigit(c) => write!(f, "'{}' is not a valid digit here", c),
            ConvError::Overflow => write!(f, "value does not fit in a u32"),
            ConvError::MissingField(name) => write!(f, "missing {}", name),
        }
    }
}

fn check_base(base: u8) -> Result<u32, ConvError> {
    match base {
        2..=16 => Ok(u32::from(base)),
        other => Err(ConvError::BadBase(other)),
    }
}

fn digit_char(value: u32) -> Result<char, ConvError> {
    char::from_digit(value, 16)
        .map(|c| c.to_ascii_uppercase())
        .ok_or(ConvError::BadDigit('?'))
}

fn try_convert_base(number: u32, base: u8) -> Result<String, ConvError> {
    let radix = check_base(base)?;
    let mut digits = Vec::new();
    let mut rest = number;
    loop {
        digits.push(digit_char(rest % radix)?);
        rest /= radix;
        if rest == 0 {
            break;
        }
    }
    Ok(digits.into_iter().rev().collect())
}

fn convert_base(number: u32, base: u8) -> String {
    try_convert_base(number, base).unwrap_or_else(|e| panic!("convert_base: {}", e))
}

fn parse_digit(c: char) -> Result<u32, ConvError> {
    c.to_digit(16).ok_or(ConvError::BadDigit(c))
}

fn parse_in_base(text: &str, base: u8) -> Result<u32, ConvError> {
    let radix = check_base(base)?;
    let mut value: u32 = 0;
    for c in text.chars() {
        let digit = parse_digit(c)?;
        if digit >= radix {
            return Err(ConvError::BadDigit(c));
        }
        let scaled = value.checked_mul(radix).ok_or(ConvError::Overflow)?;
        value = scaled.checked_add(digit).ok_or(ConvError::Overflow)?;
    }
    Ok(value)
}

fn parse_request(line: &str) -> Result<(u32, u8), ConvError> {
    let mut fields = line.split_whitespace();
    let number_text = fields.next().ok_or(ConvError::MissingField("number"))?;
    let base_text = fields.next().ok_or(ConvError::MissingField("base"))?;
    let base = base_text.parse::<u8>().map_err(|_| ConvError::BadBase(0))?;
    let number = parse_in_base(number_text, 10)?;
    Ok((number, base))
}

fn render(line: &str) -> Result<String, ConvError> {
    let (number, base) = parse_request(line)?;
    let digits = try_convert_base(number, base)?;
    Ok(format!("{} in base {} = {}", number, base, digits))
}

fn main() {
    for request in ["10 2", "255 16", "4095 16", "7 8", "12 20"] {
        match render(request) {
            Ok(report) => println!("{}", report),
            Err(e) => println!("{:?}: {}", request, e),
        }
    }
    println!("{} {}", convert_base(10, 2), convert_base(255, 16));
}

