use std::fmt;

#[derive(Debug, PartialEq)]
enum CardError {
    NonDigit(char),
    TooShort(usize),
}

impl fmt::Display for CardError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CardError::NonDigit(c) => write!(f, "unexpected character '{c}' in card number"),
            CardError::TooShort(n) => write!(f, "card number has only {n} digit(s)"),
        }
    }
}

fn parse_digit(c: char) -> Result<u32, CardError> {
    c.to_digit(10).ok_or(CardError::NonDigit(c))
}

/// Strips the usual grouping characters and rejects anything that is not a digit.
fn normalize(card: &str) -> Result<String, CardError> {
    let mut out = String::new();
    for c in card.chars().filter(|c| !matches!(c, ' ' | '-')) {
        let d = parse_digit(c)?;
        out.push(char::from_digit(d, 10).unwrap());
    }
    Ok(out)
}

fn digits(card: &str) -> Result<Vec<u32>, CardError> {
    let normalized = normalize(card)?;
    Ok(normalized.chars().map(|c| c as u32 - '0' as u32).collect())
}

/// Weighted checksum: every second digit from the right is doubled and folded.
fn luhn_sum(card: &str) -> Result<u32, CardError> {
    let ds = digits(card)?;
    if ds.len() < 2 {
        return Err(CardError::TooShort(ds.len()));
    }
    let sum = ds
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| if i % 2 == 1 { let x = d * 2; if x > 9 { x - 9 } else { x } } else { d })
        .sum();
    Ok(sum)
}

pub fn is_valid_luhn(card: &str) -> bool {
    luhn_sum(card).map(|s| s % 10 == 0).unwrap_or(false)
}

/// The digit that would have to be appended to `payload` to make it valid.
fn check_digit(payload: &str) -> Result<u32, CardError> {
    let ds = digits(payload)?;
    let sum: u32 = ds
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| if i % 2 == 0 { let x = d * 2; if x > 9 { x - 9 } else { x } } else { d })
        .sum();
    Ok((10 - sum % 10) % 10)
}

fn format_card(card: &str) -> Result<String, CardError> {
    let normalized = normalize(card)?;
    let groups: Vec<String> = normalized
        .as_bytes()
        .chunks(4)
        .map(|c| String::from_utf8_lossy(c).into_owned())
        .collect();
    Ok(groups.join(" "))
}

fn report(card: &str) -> Result<String, CardError> {
    let normalized = normalize(card)?;
    let sum = luhn_sum(&normalized)?;
    let pretty = format_card(&normalized)?;
    let (payload, given) = normalized.split_at(normalized.len() - 1);
    let expected = check_digit(payload)?;
    let status = if sum % 10 == 0 { "valid" } else { "invalid" };
    Ok(format!(
        "{pretty:<22} {status:<8} sum={sum:<3} check digit: given {given}, expected {expected}"
    ))
}

fn main() -> Result<(), CardError> {
    for card in ["79927398713", "12345", "4539 1488 0343 6467", "4539-1488-0343-6468"] {
        println!("{}", report(card)?);
        println!("  is_valid_luhn({card:?}) = {}", is_valid_luhn(card));
    }
    Ok(())
}

