use std::error::Error;
use std::fmt::Write as FmtWrite;

/// Number of trailing zeros in `n!`, obtained by counting the factors of five
/// contributed by 5, 25, 125, ... (factors of two are always in surplus).
fn trailing_zeros_factorial(n: u32) -> u32 {
    let mut zeros: u64 = 0;
    let mut power: u64 = 5;
    let limit = n as u64;
    while power <= limit {
        zeros += limit / power;
        power *= 5;
    }
    zeros as u32
}

/// Parse a single non-negative integer, rejecting anything else.
fn parse_count(text: &str) -> Result<u32, Box<dyn Error>> {
    let trimmed = text.trim();
    let value: u32 = trimmed.parse()?;
    Ok(value)
}

/// Parse either `"n"` or an inclusive range `"lo..hi"`.
fn parse_spec(spec: &str) -> Result<(u32, u32), Box<dyn Error>> {
    match spec.split_once("..") {
        Some((lo, hi)) => {
            let low = parse_count(lo)?;
            let high = parse_count(hi)?;
            if low > high {
                return Err(format!("range `{spec}` runs backwards").into());
            }
            Ok((low, high))
        }
        None => {
            let single = parse_count(spec)?;
            Ok((single, single))
        }
    }
}

/// Render one line per value in the spec, e.g. `10! ends with 2 zero(s)`.
fn summarize(spec: &str) -> Result<String, Box<dyn Error>> {
    let (low, high) = parse_spec(spec)?;
    let width = high.to_string().len();
    let mut out = String::new();
    for n in low..=high {
        let zeros = trailing_zeros_factorial(n);
        writeln!(out, "{n:>width$}! ends with {zeros} zero(s)")?;
    }
    Ok(out)
}

/// Sum of the trailing-zero counts over every value named by the spec.
fn total_zeros(spec: &str) -> Result<u64, Box<dyn Error>> {
    let (low, high) = parse_spec(spec)?;
    Ok((low..=high).map(|n| u64::from(trailing_zeros_factorial(n))).sum())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut specs: Vec<String> = std::env::args().skip(1).collect();
    if specs.is_empty() {
        specs = vec!["0..10".to_string(), "100".to_string(), "1000000".to_string()];
