use std::fmt;
use std::string::FromUtf8Error;

const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

#[derive(Debug)]
enum DecodeError {
    BadLength(usize),
    BadChar(char),
    NotUtf8(FromUtf8Error),
}

impl fmt::Display for DecodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DecodeError::BadLength(n) => write!(f, "length {} is not a multiple of 4", n),
            DecodeError::BadChar(c) => write!(f, "character {:?} is not in the alphabet", c),
            DecodeError::NotUtf8(e) => write!(f, "decoded bytes are not UTF-8: {}", e),
        }
    }
}

impl From<FromUtf8Error> for DecodeError {
    fn from(e: FromUtf8Error) -> Self {
        DecodeError::NotUtf8(e)
    }
}

fn char_to_sextet(c: char) -> Option<u8> {
    let byte = u8::try_from(c).ok()?;
    let position = ALPHABET.iter().position(|&a| a == byte)?;
    Some(position as u8)
}

fn decode_block(block: &[char]) -> Result<[u8; 3], DecodeError> {
    let mut packed = 0u32;
    for &c in block {
        let sextet = char_to_sextet(c).ok_or(DecodeError::BadChar(c))?;
        packed = (packed << 6) | u32::from(sextet);
    }
    Ok([(packed >> 16) as u8, (packed >> 8) as u8, packed as u8])
}

fn simple_base64_decode(text: &str) -> Result<Vec<u8>, DecodeError> {
    let chars: Vec<char> = text.chars().collect();
    if chars.len() % 4 != 0 {
        return Err(DecodeError::BadLength(chars.len()));
    }
    let mut out = Vec::with_capacity(chars.len() / 4 * 3);
    for chunk in chars.chunks_exact(4) {
        let bytes = decode_block(chunk)?;
        out.extend_from_slice(&bytes);
    }
    Ok(out)
}

fn encode_block(block: [u8; 3]) -> [char; 4] {
    let packed = (u32::from(block[0]) << 16) | (u32::from(block[1]) << 8) | u32::from(block[2]);
    [18, 12, 6, 0].map(|shift| ALPHABET[((packed >> shift) & 0x3f) as usize] as char)
}

fn simple_base64_encode(input: &[u8]) -> String {
    let mut out = String::with_capacity(input.len() / 3 * 4);
    for chunk in input.chunks_exact(3) {
        out.extend(encode_block([chunk[0], chunk[1], chunk[2]]));
    }
    out
}

fn round_trip_report(input: &[u8]) -> Result<String, DecodeError> {
    let encoded = simple_base64_encode(input);
    let decoded = simple_base64_decode(&encoded)?;
    let text = String::from_utf8(decoded)?;
    Ok(format!("{:?} -> {:?} -> {:?}", String::from_utf8_lossy(input), encoded, text))
}

fn main() -> Result<(), DecodeError> {
    for sample in [&b"Man"[..], b"", b"any carnal pleas"] {
        let report = round_trip_report(sample)?;
        println!("{}", report);
    }
    let bytes = simple_base64_decode("TWFuTWFu")?;
    let literal = String::from_utf8(bytes)?;
    println!("decoded literal: {}", literal);
    Ok(())
}

