/// Substring search helpers plus a small query-report front end.
use std::fmt;

#[derive(Debug)]
enum QueryError {
    MissingSeparator(String),
    EmptyPattern(String),
    BadIndex(String),
    NoSuchMatch { pattern: String, index: usize },
}

impl fmt::Display for QueryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueryError::MissingSeparator(line) => write!(f, "query {:?} has no '=' separator", line),
            QueryError::EmptyPattern(line) => write!(f, "query {:?} has an empty pattern", line),
            QueryError::BadIndex(raw) => write!(f, "{:?} is not a match index", raw),
            QueryError::NoSuchMatch { pattern, index } => {
                write!(f, "{:?} has no match number {}", pattern, index)
            }
        }
    }
}

struct Query<'a> {
    text: &'a str,
    pattern: &'a str,
    index: usize,
}

/// Every starting byte index at which `pattern` occurs in `text`.
fn find_all_substrings(text: &str, pattern: &str) -> Vec<usize> {
    if pattern.is_empty() || pattern.len() > text.len() {
        return Vec::new();
    }
    (0..=text.len() - pattern.len())
        .filter(|&i| text.is_char_boundary(i) && text[i..].starts_with(pattern))
        .collect()
}

/// Parses `text=pattern` or `text=pattern@n`, where `n` selects a match.
fn parse_query(line: &str) -> Result<Query<'_>, QueryError> {
    let (text, rest) = line
        .split_once('=')
        .ok_or_else(|| QueryError::MissingSeparator(line.to_string()))?;
    let (pattern, index) = match rest.split_once('@') {
        Some((p, raw)) => (
            p,
            raw.trim()
                .parse::<usize>()
                .map_err(|_| QueryError::BadIndex(raw.to_string()))?,
        ),
        None => (rest, 0),
    };
    if pattern.is_empty() {
        return Err(QueryError::EmptyPattern(line.to_string()));
    }
    Ok(Query { text, pattern, index })
}

/// Byte range covered by the `n`-th (0-based) match.
fn nth_span(text: &str, pattern: &str, n: usize) -> Option<(usize, usize)> {
    let start = *find_all_substrings(text, pattern).get(n)?;
    Some((start, start + pattern.len()))
}

/// Bytes spanned from the start of the first match to the end of the last.
fn matched_extent(text: &str, pattern: &str) -> Option<usize> {
    let hits = find_all_substrings(text, pattern);
    let first = *hits.first()?;
    let last = *hits.last()?;
    Some(last + pattern.len() - first)
}

fn span_of(q: &Query<'_>) -> Result<(usize, usize), QueryError> {
    nth_span(q.text, q.pattern, q.index).ok_or_else(|| QueryError::NoSuchMatch {
        pattern: q.pattern.to_string(),
        index: q.index,
    })
}

/// The queried text with the selected match wrapped in brackets.
fn highlight(q: &Query<'_>) -> Result<String, QueryError> {
    let (start, end) = span_of(q)?;
    let text = q.text;
    Ok(format!("{}[{}]{}", &text[..start], &text[start..end], &text[end..]))
}

fn format_report(line: &str) -> Result<String, QueryError> {
    let q = parse_query(line)?;
    let hits = find_all_substrings(q.text, q.pattern);
    let mut report = format!("{:?} in {:?} -> {:?}", q.pattern, q.text, hits);
    if hits.is_empty() {
        report.push_str(" | no match");
    } else {
        report.push_str(&format!(" | {}", highlight(&q)?));
        if let Some(extent) = matched_extent(q.text, q.pattern) {
            report.push_str(&format!(" | extent {} bytes", extent));
        }
    }
    Ok(report)
}

fn main() -> Result<(), QueryError> {
    let queries = ["banana=ana", "hello=world", "abababa=aba@1", "mississippi=issi"];
    for query in queries {
        println!("{}", format_report(query)?);
    }
    if let Err(err) = format_report("banana=a@7") {
        println!("rejected: {}", err);
    }
    Ok(())
}

