use std::fmt;

#[derive(Debug)]
enum IpError {
    WrongGroupCount(usize),
    BadOctet(String),
    OctetOutOfRange(u32),
    MissingPrefix,
    BadPrefix(String),
}

impl fmt::Display for IpError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            IpError::WrongGroupCount(n) => write!(f, "expected 4 groups, found {}", n),
            IpError::BadOctet(s) => write!(f, "malformed octet {:?}", s),
            IpError::OctetOutOfRange(v) => write!(f, "octet {} exceeds 255", v),
            IpError::MissingPrefix => write!(f, "missing '/prefix' part"),
            IpError::BadPrefix(s) => write!(f, "malformed prefix {:?}", s),
        }
    }
}

fn parse_octet(text: &str) -> Result<u8, IpError> {
    if text.is_empty() || text.len() > 3 || !text.bytes().all(|b| b.is_ascii_digit()) {
        return Err(IpError::BadOctet(text.to_string()));
    }
    if text.len() > 1 && text.starts_with('0') {
        return Err(IpError::BadOctet(text.to_string()));
    }
    let value: u32 = text.parse().map_err(|_| IpError::BadOctet(text.to_string()))?;
    if value > 255 {
        return Err(IpError::OctetOutOfRange(value));
    }
    Ok(value as u8)
}

fn parse_ipv4(text: &str) -> Result<[u8; 4], IpError> {
    let groups: Vec<&str> = text.split('.').collect();
    if groups.len() != 4 {
        return Err(IpError::WrongGroupCount(groups.len()));
    }
    let mut octets = [0u8; 4];
    for (slot, group) in octets.iter_mut().zip(groups) {
        *slot = parse_octet(group)?;
    }
    Ok(octets)
}

fn is_valid_ipv4_format(text: &str) -> bool {
    parse_ipv4(text).is_ok()
}

fn to_u32(text: &str) -> Result<u32, IpError> {
    let octets = parse_ipv4(text)?;
    Ok(u32::from_be_bytes(octets))
}

fn format_u32(bits: u32) -> String {
    let b = bits.to_be_bytes();
    format!("{}.{}.{}.{}", b[0], b[1], b[2], b[3])
}

fn parse_cidr(text: &str) -> Result<(u32, u8), IpError> {
    let (addr, prefix) = text.split_once('/').ok_or(IpError::MissingPrefix)?;
    let bits = to_u32(addr)?;
    let len: u8 = prefix.parse().map_err(|_| IpError::BadPrefix(prefix.to_string()))?;
    if len > 32 {
        return Err(IpError::BadPrefix(prefix.to_string()));
    }
    Ok((bits, len))
}

fn mask_for(len: u8) -> u32 {
    if len == 0 { 0 } else { u32::MAX << (32 - len) }
}

fn network_address(cidr: &str) -> Result<String, IpError> {
    let (bits, len) = parse_cidr(cidr)?;
    Ok(format_u32(bits & mask_for(len)))
}

fn same_network(host: &str, cidr: &str) -> Result<bool, IpError> {
    let (bits, len) = parse_cidr(cidr)?;
    let candidate = to_u32(host)?;
    let mask = mask_for(len);
    Ok(candidate & mask == bits & mask)
}

fn main() -> Result<(), IpError> {
    for sample in ["192.168.1.1", "256.0.0.1", "1.2.3", "01.2.3.4", "10.0.0.255"] {
        println!("{:<12} -> {}", sample, is_valid_ipv4_format(sample));
    }
    let cidr = "192.168.1.130/26";
    println!("network of {} is {}", cidr, network_address(cidr)?);
    println!("192.168.1.190 in {}: {}", cidr, same_network("192.168.1.190", cidr)?);
    println!("192.168.1.10 in {}: {}", cidr, same_network("192.168.1.10", cidr)?);
    if let Err(e) = network_address("10.0.0.1/40") {
        println!("rejected 10.0.0.1/40: {}", e);
    }
    Ok(())
}

