use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum StatsError {
    Parse(ParseFloatError),
    LengthMismatch(usize, usize),
    Empty,
    ZeroWeight,
}

impl From<ParseFloatError> for StatsError {
    fn from(e: ParseFloatError) -> Self {
        StatsError::Parse(e)
    }
}

impl fmt::Display for StatsError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            StatsError::Parse(e) => write!(f, "bad number: {}", e),
            StatsError::LengthMismatch(v, w) => write!(f, "{} values but {} weights", v, w),
            StatsError::Empty => write!(f, "no data points"),
            StatsError::ZeroWeight => write!(f, "weights sum to zero"),
        }
