        shared.push(x);
    }
    shared
}

fn fold_prefix(words: &Vec<String>) -> Option<String> {
    let mut iter = words.iter();
    let mut acc = iter.next()?.clone();
    for word in iter {
        acc = prefix_of_pair(&acc, word);
        if acc.is_empty() {
