#[derive(Debug, Clone, Copy)]
struct Circle {
    cx: f64,
    cy: f64,
    radius: f64,
}

impl Circle {
    fn new(cx: f64, cy: f64, radius: f64) -> Result<Circle, String> {
        if !cx.is_finite() || !cy.is_finite() || !radius.is_finite() {
            return Err("circle centre and radius must be finite numbers".to_string());
        }
        if radius < 0.0 {
            return Err(format!("radius must not be negative, got {}", radius));
        }
        Ok(Circle { cx, cy, radius })
    }
}

fn is_point_in_circle(px: f64, py: f64, cx: f64, cy: f64, radius: f64) -> bool {
    let dx = px - cx;
    let dy = py - cy;
    dx * dx + dy * dy <= radius * radius
}

fn parse_f64(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    trimmed
        .parse::<f64>()
        .map_err(|e| format!("cannot read {:?} as a number: {}", trimmed, e))
}

fn parse_point(spec: &str) -> Result<(f64, f64), String> {
    let (left, right) = spec
        .split_once(',')
        .ok_or_else(|| format!("point {:?} needs two comma-separated coordinates", spec.trim()))?;
    let px = parse_f64(left)?;
    let py = parse_f64(right)?;
    Ok((px, py))
}

fn parse_circle(spec: &str) -> Result<Circle, String> {
    let fields: Vec<&str> = spec.split(',').collect();
    if fields.len() != 3 {
        return Err(format!("circle {:?} needs cx,cy,radius", spec.trim()));
    }
    let cx = parse_f64(fields[0])?;
    let cy = parse_f64(fields[1])?;
    let radius = parse_f64(fields[2])?;
    let circle = Circle::new(cx, cy, radius)?;
    Ok(circle)
}

fn report(query: &str) -> Result<String, String> {
    let (point_part, circle_part) = query
        .split_once('|')
        .ok_or_else(|| format!("query {:?} must look like 'px,py | cx,cy,r'", query))?;
    let (px, py) = parse_point(point_part)?;
    let circle = parse_circle(circle_part)?;
    let inside = is_point_in_circle(px, py, circle.cx, circle.cy, circle.radius);
    let verdict = if inside { "inside or on" } else { "outside" };
    Ok(format!(
        "({}, {}) is {} the circle at ({}, {}) with radius {}",
        px, py, verdict, circle.cx, circle.cy, circle.radius
    ))
}

fn summarize(queries: &[&str]) -> Result<Vec<String>, String> {
    let mut lines = Vec::with_capacity(queries.len());
    for query in queries {
        lines.push(report(query)?);
    }
    Ok(lines)
}

fn main() -> Result<(), String> {
    let queries = ["1,1 | 0,0,2", "3,0 | 0,0,2", "-2,0 | 0,0,2", "4.5,-1 | 4,-1,0.5"];
    let lines = summarize(&queries)?;
    for line in lines {
        println!("{}", line);
    }
    Ok(())
}

