use std::error::Error;
use std::fs;
use std::io::{self, ErrorKind};

/// Returns the byte index of the `//` that starts a comment on this line,
/// ignoring `//` that appears inside a double-quoted string literal.
fn find_comment_start(line: &str) -> Option<usize> {
    let bytes = line.as_bytes();
    let mut in_string = false;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if in_string {
            if c == b'\\' {
                i += 1;
            } else if c == b'"' {
                in_string = false;
            }
        } else if c == b'"' {
            in_string = true;
        } else if c == b'/' && bytes.get(i + 1) == Some(&b'/') {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Removes every single-line (`//`) comment, keeping the code before it.
pub fn remove_single_line_comments(code: &str) -> String {
    let mut out = String::with_capacity(code.len());
    for (index, line) in code.lines().enumerate() {
        if index > 0 {
            out.push('\n');
        }
        match find_comment_start(line) {
            Some(pos) => out.push_str(&line[..pos]),
            None => out.push_str(line),
        }
    }
    out
}

/// Parses a `let NAME = INTEGER;` statement that has already been decommented.
fn parse_declaration(line: &str) -> Option<(String, i64)> {
    let body = line.trim().strip_prefix("let ")?;
    let (name, rest) = body.split_once('=')?;
    let literal = rest.trim().strip_suffix(';')?;
    let value = literal.trim().parse().ok()?;
    Some((name.trim().to_string(), value))
}

fn summarize(cleaned: &str) -> Option<String> {
    let first = cleaned.lines().find(|line| !line.trim().is_empty())?;
    let (name, value) = parse_declaration(first)?;
    Some(format!("first declaration: {} = {}", name, value))
}

fn clean_file(path: &str) -> Result<String, Box<dyn Error>> {
    let source = fs::read_to_string(path)?;
    Ok(remove_single_line_comments(&source))
}

fn report(path: &str) -> Result<String, Box<dyn Error>> {
    let cleaned = clean_file(path)?;
    let code_lines = cleaned.lines().filter(|line| !line.trim().is_empty()).count();
    let summary = summarize(&cleaned)
        .ok_or_else(|| io::Error::new(ErrorKind::InvalidData, "no integer declaration found"))?;
    Ok(format!("{}: {} code lines, {}", path, code_lines, summary))
}

fn write_cleaned(input: &str, output: &str) -> Result<usize, Box<dyn Error>> {
    let cleaned = clean_file(input)?;
    fs::write(output, cleaned.as_bytes())?;
    Ok(cleaned.len())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut args = std::env::args().skip(1);
    let input = args
        .next()
        .ok_or_else(|| io::Error::new(ErrorKind::InvalidInput, "usage: decomment <input> [output]"))?;
    println!("{}", report(&input)?);
    if let Some(output) = args.next() {
        let written = write_cleaned(&input, &output)?;
        println!("wrote {} bytes to {}", written, output);
    }
    Ok(())
}

