use std::num::ParseIntError;

fn calculate_lcm(a: u32, b: u32) -> u32 {
    a / gcd(a, b) * b
}

fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn parse_positive(text: &str) -> Result<u32, String> {
    let value: u32 = text
        .trim()
        .parse()
        .map_err(|e: ParseIntError| format!("'{}' is not a number: {}", text.trim(), e))?;
    if value == 0 {
        return Err("value must be a positive integer".to_string());
    }
    Ok(value)
}

fn parse_pair(line: &str) -> Result<(u32, u32), String> {
    let mut parts = line.split_whitespace();
    let left = parts.next().ok_or_else(|| "missing first operand".to_string())?;
    let right = parts.next().ok_or_else(|| "missing second operand".to_string())?;
    if parts.next().is_some() {
        return Err("expected exactly two operands".to_string());
    }
    let a = parse_positive(left)?;
    let b = parse_positive(right)?;
    Ok((a, b))
}

fn lcm_of_line(line: &str) -> Result<u32, String> {
    let (a, b) = parse_pair(line)?;
    Ok(calculate_lcm(a, b))
}

fn lcm_of_list(values: &[&str]) -> Result<u32, String> {
    let mut iter = values.iter();
    let first = iter.next().ok_or_else(|| "empty list".to_string())?;
    let mut acc = parse_positive(first)?;
    for item in iter {
        acc = calculate_lcm(acc, parse_positive(item)?);
    }
    Ok(acc)
}

fn report(line: &str) -> String {
    match lcm_of_line(line) {
        Ok(value) => format!("lcm({}) = {}", line.trim(), value),
        Err(message) => format!("lcm({}) failed: {}", line.trim(), message),
    }
}

fn main() {
    for line in ["4 6", "7 3", "12 18", "5", "0 9", "8 x"] {
        println!("{}", report(line));
    }

    let batch = ["4", "6", "10"];
    match lcm_of_list(&batch) {
        Ok(value) => println!("lcm of {:?} = {}", batch, value),
        Err(message) => println!("batch failed: {}", message),
    }
}

