const DENOMS: [(u32, &str); 6] = [
    (500, "5 note"),
    (200, "2 coin"),
    (100, "1 coin"),
    (25, "25c"),
    (10, "10c"),
    (5, "5c"),
];

fn can_afford_and_change(item_price: u32, amount_paid: u32) -> Option<u32> {
    amount_paid.checked_sub(item_price)
}

fn parse_amount(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    let (whole_text, cent_text) = match trimmed.split_once('.') {
        Some(parts) => parts,
        None => (trimmed, ""),
    };
    if cent_text.len() > 2 {
        return Err(format!("too many decimals in {:?}", trimmed));
    }
    let units: u32 = whole_text
        .parse()
        .map_err(|_| format!("bad whole part in {:?}", trimmed))?;
    let cents: u32 = format!("{:0<2}", cent_text)
        .parse()
        .map_err(|_| format!("bad fraction in {:?}", trimmed))?;
    units
        .checked_mul(100)
        .and_then(|u| u.checked_add(cents))
        .ok_or_else(|| format!("amount out of range: {:?}", trimmed))
}

fn parse_transaction(line: &str) -> Result<(u32, u32), String> {
    let (price_text, paid_text) = line
        .split_once(',')
        .ok_or_else(|| format!("expected 'price,paid' but got {:?}", line))?;
    let price = parse_amount(price_text)?;
    let paid = parse_amount(paid_text)?;
    Ok((price, paid))
}

fn format_money(cents: u32) -> String {
    format!("{}.{:02}", cents / 100, cents % 100)
}

fn describe_change(change: u32) -> String {
    let mut remaining = change;
    let mut pieces = Vec::new();
    for (value, name) in DENOMS {
        let count = remaining / value;
        if count > 0 {
            pieces.push(format!("{} x {}", count, name));
            remaining %= value;
        }
    }
    if remaining > 0 {
        pieces.push(format!("{}c loose", remaining));
    }
    if pieces.is_empty() {
        "exact payment".to_string()
    } else {
        pieces.join(", ")
    }
}

fn receipt_line(line: &str) -> Result<String, String> {
    let (price, paid) = parse_transaction(line)?;
    let change = can_afford_and_change(price, paid)
        .ok_or_else(|| format!("declined: {} short", format_money(price - paid)))?;
    Ok(format!(
        "price {} paid {} -> change {} ({})",
        format_money(price),
        format_money(paid),
        format_money(change),
        describe_change(change)
    ))
}

fn total_change(lines: &[&str]) -> Result<u32, String> {
    let mut total = 0;
    for line in lines {
        let (price, paid) = parse_transaction(line)?;
        total += can_afford_and_change(price, paid).unwrap_or(0);
    }
    Ok(total)
}

fn main() {
    println!("{:?}", can_afford_and_change(100, 150));
    println!("{:?}", can_afford_and_change(100, 80));

    let sales = ["1.00,1.50", "1.00,0.80", "12.35,20", "3.50,3.50"];
    for line in sales {
        match receipt_line(line) {
            Ok(report) => println!("{}", report),
            Err(problem) => println!("{}: {}", line, problem),
        }
    }
    match total_change(&sales) {
        Ok(total) => println!("change handed out: {}", format_money(total)),
        Err(problem) => println!("cannot total sales: {}", problem),
    }
}

