use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub enum ArgError {
    MissingPrefix(String),
    MissingEquals(String),
    EmptyKey(String),
    Duplicate(String),
    MissingKey(String),
    NotANumber(String, String),
}

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ArgError::MissingPrefix(a) => write!(f, "argument `{}` does not start with `--`", a),
            ArgError::MissingEquals(a) => write!(f, "argument `{}` has no `=` separator", a),
            ArgError::EmptyKey(a) => write!(f, "argument `{}` has an empty key", a),
            ArgError::Duplicate(k) => write!(f, "key `{}` given more than once", k),
            ArgError::MissingKey(k) => write!(f, "required key `{}` is missing", k),
            ArgError::NotANumber(k, v) => write!(f, "value `{}` of key `{}` is not a number", v, k),
        }
    }
}

fn split_arg(arg: &str) -> Result<(String, String), ArgError> {
    let body = arg
        .strip_prefix("--")
        .ok_or_else(|| ArgError::MissingPrefix(arg.to_string()))?;
    let (key, value) = body
        .split_once('=')
        .ok_or_else(|| ArgError::MissingEquals(arg.to_string()))?;
    if key.is_empty() {
        return Err(ArgError::EmptyKey(arg.to_string()));
    }
    Ok((key.to_string(), value.to_string()))
}

pub fn try_parse_args(args: Vec<String>) -> Result<HashMap<String, String>, ArgError> {
    let mut map = HashMap::new();
    for arg in &args {
        let (key, value) = split_arg(arg)?;
        if map.contains_key(&key) {
            return Err(ArgError::Duplicate(key));
        }
        map.insert(key, value);
    }
    Ok(map)
}

pub fn parse_args(args: Vec<String>) -> HashMap<String, String> {
    match try_parse_args(args) {
        Ok(map) => map,
        Err(err) => panic!("invalid argument: {}", err),
    }
}

fn require<'a>(map: &'a HashMap<String, String>, key: &str) -> Result<&'a String, ArgError> {
    map.get(key).ok_or_else(|| ArgError::MissingKey(key.to_string()))
}

struct Profile {
    name: String,
    age: u32,
    city: String,
}

fn build_profile(args: Vec<String>) -> Result<Profile, ArgError> {
    let map = try_parse_args(args)?;
    let name = require(&map, "name")?.clone();
    let raw_age = require(&map, "age")?;
    let age = raw_age
        .parse::<u32>()
        .map_err(|_| ArgError::NotANumber("age".to_string(), raw_age.clone()))?;
    let city = require(&map, "city")?.clone();
    Ok(Profile { name, age, city })
}

fn main() {
    let cli: Vec<String> = std::env::args().skip(1).collect();
    let args = if cli.is_empty() {
        vec![
            "--name=Alice".to_string(),
            "--age=30".to_string(),
            "--city=New York".to_string(),
        ]
    } else {
        cli
    };

    match build_profile(args) {
        Ok(p) => println!("{} ({}) lives in {}", p.name, p.age, p.city),
        Err(err) => eprintln!("error: {}", err),
    }
}

