fn parse_vector(spec: &str) -> Result<Vec<f64>, String> {
    let mut values = Vec::new();
    for token in spec.split(',') {
        let trimmed = token.trim();
        let value = trimmed
            .parse::<f64>()
            .map_err(|e| format!("bad number {:?}: {}", trimmed, e))?;
        values.push(value);
    }
    if values.is_empty() {
        return Err(format!("no components in {:?}", spec));
    }
    Ok(values)
}

fn parse_pair(line: &str) -> Result<(Vec<f64>, Vec<f64>), String> {
    let (left, right) = line
        .split_once(';')
        .ok_or_else(|| format!("expected two vectors separated by ';' in {:?}", line))?;
    let a = parse_vector(left)?;
    let b = parse_vector(right)?;
    Ok((a, b))
}

fn dot_product(a: Vec<f64>, b: Vec<f64>) -> f64 {
    if a.len() != b.len() {
        return 0.0;
    }
    a.iter().zip(b.iter()).map(|(x, y)| x * y).sum()
}

fn checked_dot(a: Vec<f64>, b: Vec<f64>) -> Result<f64, String> {
    if a.len() != b.len() {
        return Err(format!("length mismatch: {} vs {}", a.len(), b.len()));
    }
    Ok(dot_product(a, b))
}

fn norm(v: &[f64]) -> Result<f64, String> {
    let squared = checked_dot(v.to_vec(), v.to_vec())?;
    Ok(squared.sqrt())
}

fn cosine_similarity(a: &[f64], b: &[f64]) -> Result<f64, String> {
    let numerator = checked_dot(a.to_vec(), b.to_vec())?;
    let na = norm(a)?;
    let nb = norm(b)?;
    if na == 0.0 || nb == 0.0 {
        return Err("cosine similarity undefined for a zero vector".to_string());
    }
    Ok(numerator / (na * nb))
}

fn describe(line: &str) -> Result<String, String> {
    let (a, b) = parse_pair(line)?;
    let plain = dot_product(a.clone(), b.clone());
    let exact = checked_dot(a.clone(), b.clone())?;
    let cos = cosine_similarity(&a, &b)?;
    Ok(format!(
        "dot_product = {:.1} (checked {:.1}), cosine = {:.4}",
        plain, exact, cos
    ))
}

fn main() {
    let inputs = [
        "1, 2, 3; 4, 5, 6",
        "1, 2; 3, 4, 5",
        "0.5, -1.5, 2.0; 2.0, 2.0, 2.0",
        "1, x; 2, 3",
    ];
    for line in inputs {
        match describe(line) {
            Ok(report) => println!("{:<28} -> {}", line, report),
            Err(err) => println!(
                "{:<28} -> error: {}; dot_product falls back to {:.1}",
                line,
                err,
                match parse_pair(line) {
                    Ok((a, b)) => dot_product(a, b),
                    Err(_) => 0.0,
                }
            ),
        }
    }
}

