use std::error::Error;
use std::fmt;
use std::io::{self, Read};

#[derive(Debug)]
enum InputError {
    MissingValue(String),
    NotNumeric(String),
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::MissingValue(line) => write!(f, "record has no `= value` part: {:?}", line),
            InputError::NotNumeric(tok) => write!(f, "not a non-negative integer: {:?}", tok),
        }
    }
}

impl Error for InputError {}

pub fn is_power_of_two(n: u32) -> bool {
    n != 0 && n & (n - 1) == 0
}

fn log2_exact(n: u32) -> Option<u32> {
    if is_power_of_two(n) {
        Some(n.trailing_zeros())
    } else {
        None
    }
}

fn previous_power_of_two(n: u32) -> Option<u32> {
    let exponent = log2_exact(n)?;
    exponent.checked_sub(1).map(|e| 1u32 << e)
}

fn parse_number(token: &str) -> Result<u32, InputError> {
    let trimmed = token.trim();
    let value = trimmed
        .parse::<u32>()
        .map_err(|_| InputError::NotNumeric(trimmed.to_string()))?;
    Ok(value)
}

fn parse_record(line: &str) -> Result<(String, u32), InputError> {
    let mut parts = line.splitn(2, '=');
    let label = parts.next().ok_or_else(|| InputError::MissingValue(line.to_string()))?;
    let raw = parts.next().ok_or_else(|| InputError::MissingValue(line.to_string()))?;
    let value = parse_number(raw)?;
    Ok((label.trim().to_string(), value))
}

fn format_entry(label: &str, value: u32) -> String {
    match log2_exact(value) {
        Some(exponent) => {
            let prev = previous_power_of_two(value)
                .map(|p| p.to_string())
                .unwrap_or_else(|| "none".to_string());
            format!("{}: {} = 2^{} (power of two, previous: {})\n", label, value, exponent, prev)
        }
        None => format!("{}: {} is not a power of two\n", label, value),
    }
}

fn report(records: &[&str]) -> Result<String, InputError> {
    let mut out = String::new();
    for record in records {
        let (label, value) = parse_record(record)?;
        out.push_str(&format_entry(&label, value));
    }
    Ok(out)
}

fn highest_exponent(records: &[&str]) -> Result<Option<u32>, InputError> {
    let mut best = None;
    for record in records {
        let (_, value) = parse_record(record)?;
        best = best.max(log2_exact(value));
    }
    Ok(best)
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let records: Vec<&str> = input.lines().filter(|l| !l.trim().is_empty()).collect();
    print!("{}", report(&records)?);
    if let Some(exponent) = highest_exponent(&records)? {
        println!("highest exponent seen: {}", exponent);
    }
    Ok(())
}

