use std::collections::HashMap;
use std::fmt::{self, Write};

#[derive(Debug)]
enum ParseError {
    Malformed(String),
    EmptyKey(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Malformed(line) => write!(f, "missing '=' in line: {}", line),
            ParseError::EmptyKey(line) => write!(f, "empty key in line: {}", line),
        }
    }
}

fn escape_into(out: &mut String, s: &str) -> fmt::Result {
    out.write_char('"')?;
    for c in s.chars() {
        match c {
            '"' => out.write_str("\\\"")?,
            '\\' => out.write_str("\\\\")?,
            '\n' => out.write_str("\\n")?,
            '\r' => out.write_str("\\r")?,
            '\t' => out.write_str("\\t")?,
            c if (c as u32) < 0x20 => write!(out, "\\u{:04x}", c as u32)?,
            c => out.write_char(c)?,
        }
    }
    out.write_char('"')
}

fn write_member(out: &mut String, key: &str, value: &str) -> fmt::Result {
    escape_into(out, key)?;
    out.write_char(':')?;
    escape_into(out, value)
}

fn stringify_into(out: &mut String, map: &HashMap<String, String>) -> fmt::Result {
    out.write_char('{')?;
    let mut first = true;
    for (key, value) in map {
        if !first {
            out.write_char(',')?;
        }
        first = false;
        write_member(out, key, value)?;
    }
    out.write_char('}')
}

fn json_stringify_map(map: HashMap<String, String>) -> String {
    let mut out = String::new();
    stringify_into(&mut out, &map).expect("writing into a String never fails");
    out
}

fn parse_pair(line: &str) -> Result<(String, String), ParseError> {
    let (raw_key, raw_value) = line
        .split_once('=')
