use std::collections::HashMap;
use std::fmt::{self, Write};

#[derive(Debug)]
enum ParseError {
    Malformed(String),
    EmptyKey(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Malformed(line) => write!(f, "missing '=' in line: {}", line),
            ParseError::EmptyKey(line) => write!(f, "empty key in line: {}", line),
        }
    }
}

fn escape_into(out: &mut String, s: &str) -> fmt::Result {
    match out.write_char('"') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    for c in s.chars() {
        match c {
            '"' => match out.write_str("\\\"") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            '\\' => match out.write_str("\\\\") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            '\n' => match out.write_str("\\n") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            '\r' => match out.write_str("\\r") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            '\t' => match out.write_str("\\t") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            c if (c as u32) < 0x20 => match write!(out, "\\u{:04x}", c as u32) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
            c => match out.write_char(c) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            },
        }
    }
    out.write_char('"')
}

fn write_member(out: &mut String, key: &str, value: &str) -> fmt::Result {
    match escape_into(out, key) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    match out.write_char(':') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    escape_into(out, value)
}

fn stringify_into(out: &mut String, map: &HashMap<String, String>) -> fmt::Result {
    match out.write_char('{') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let mut first = true;
    for (key, value) in map {
        if !first {
            match out.write_char(',') {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
        }
        first = false;
        match write_member(out, key, value) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    out.write_char('}')
}

fn json_stringify_map(map: HashMap<String, String>) -> String {
    let mut out = String::new();
    stringify_into(&mut out, &map).expect("writing into a String never fails");
    out
}

fn parse_pair(line: &str) -> Result<(String, String), ParseError> {
    let (raw_key, raw_value) = match line
        .split_once('=')
        .ok_or_else(|| ParseError::Malformed(line.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let key = raw_key.trim();
    if key.is_empty() {
        return Err(ParseError::EmptyKey(line.to_string()));
    }
    Ok((key.to_string(), raw_value.trim().to_string()))
}

fn parse_object(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        let (key, value) = match parse_pair(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        map.insert(key, value);
    }
    Ok(map)
}

fn json_from_config(input: &str) -> Result<String, ParseError> {
    let map = match parse_object(input) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(json_stringify_map(map))
}

fn main() -> Result<(), ParseError> {
    let single: HashMap<String, String> = vec![("name".to_string(), "Alice".to_string())]
        .into_iter()
        .collect();
    println!("{}", json_stringify_map(single));

    let config = "city = London\npopulation = 8M\n";
    println!("{}", match json_from_config(config) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
