use std::num::ParseIntError;

/// Returns the longest string in `words`, or `None` when the vector is empty.
fn find_longest_string(words: Vec<String>) -> Option<String> {
    let longest = words
        .into_iter()
        .max_by_key(|word| word.chars().count())?;
    Some(longest)
}

/// A word is usable only if it carries at least one non-space character.
fn validate_word(token: &str) -> Result<String, String> {
    let trimmed = token.trim();
    if trimmed.is_empty() {
        return Err(format!("empty word in {token:?}"));
    }
    Ok(trimmed.to_string())
}

/// Splits a comma separated line into validated words.
fn parse_words(line: &str) -> Result<Vec<String>, String> {
    let mut words = Vec::new();
    for token in line.split(',') {
        let word = validate_word(token)?;
        words.push(word);
    }
    Ok(words)
}

/// Parses a `width=N` configuration entry used to align the report.
fn parse_width(spec: &str) -> Result<usize, String> {
    let (key, value) = spec
        .split_once('=')
        .ok_or_else(|| format!("missing '=' in {spec:?}"))?;
    if key.trim() != "width" {
        return Err(format!("unknown setting {:?}", key.trim()));
    }
    let width = value
        .trim()
        .parse::<usize>()
        .map_err(|error: ParseIntError| error.to_string())?;
    Ok(width)
}

fn longest_in_line(line: &str) -> Result<String, String> {
    let words = parse_words(line)?;
    find_longest_string(words).ok_or_else(|| format!("no words in {line:?}"))
}

fn format_row(line: &str, width: usize) -> Result<String, String> {
    let longest = longest_in_line(line)?;
    let length = longest.chars().count();
    Ok(format!("{longest:<width$} {length}"))
}

fn build_report(spec: &str, lines: &[&str]) -> Result<String, String> {
    let width = parse_width(spec)?;
    let mut report = String::new();
    for line in lines {
        let row = format_row(line, width)?;
        report.push_str(&row);
        report.push('\n');
    }
    Ok(report)
}

fn summarize(words: Vec<String>) -> String {
    match find_longest_string(words) {
        Some(longest) => format!("longest: {longest}"),
        None => "longest: (none)".to_string(),
    }
}

fn main() -> Result<(), String> {
    let fruit = vec![
        "apple".to_string(),
        "banana".to_string(),
        "kiwi".to_string(),
    ];
    println!("{}", summarize(fruit));
    println!("{}", summarize(Vec::new()));

    let lines = ["apple, banana, kiwi", "rust, go", "elephantine, ox"];
    let report = build_report("width = 12", &lines)?;
    print!("{report}");
    Ok(())
}

