use std::f64::consts::PI;
use std::num::ParseFloatError;

#[derive(Debug)]
enum CircleError {
    Parse(ParseFloatError),
    NegativeRadius(f64),
    MissingField(&'static str),
    InnerLargerThanOuter { outer: f64, inner: f64 },
}

impl From<ParseFloatError> for CircleError {
    fn from(e: ParseFloatError) -> Self {
        CircleError::Parse(e)
    }
}

fn circle_area(radius: f64) -> f64 {
    PI * radius * radius
}

fn parse_radius(text: &str) -> Result<f64, CircleError> {
    let radius: f64 = text.trim().parse()?;
    if radius < 0.0 {
        return Err(CircleError::NegativeRadius(radius));
    }
    Ok(radius)
}

fn area_of_text(text: &str) -> Result<f64, CircleError> {
    let radius = parse_radius(text)?;
    Ok(circle_area(radius))
}

struct Ring {
    outer: f64,
    inner: f64,
}

impl Ring {
    fn area(&self) -> f64 {
        circle_area(self.outer) - circle_area(self.inner)
    }
}

fn field<'a>(record: &'a str, index: usize, name: &'static str) -> Result<&'a str, CircleError> {
    record
        .split(',')
        .nth(index)
        .ok_or(CircleError::MissingField(name))
}

fn parse_ring(record: &str) -> Result<Ring, CircleError> {
    let outer_text = field(record, 0, "outer radius")?;
    let inner_text = field(record, 1, "inner radius")?;
    let outer = parse_radius(outer_text)?;
    let inner = parse_radius(inner_text)?;
    if inner > outer {
        return Err(CircleError::InnerLargerThanOuter { outer, inner });
    }
    Ok(Ring { outer, inner })
}

fn describe(record: &str) -> Result<String, CircleError> {
    let ring = parse_ring(record)?;
    Ok(format!(
        "ring with outer radius {} covers {:.6} of the {:.6} disc",
        ring.outer,
        ring.area(),
        circle_area(ring.outer)
    ))
}

fn total_area(records: &[&str]) -> Result<f64, CircleError> {
    let mut sum = 0.0;
    for record in records {
        sum += parse_ring(record)?.area();
    }
    Ok(sum)
}

fn main() -> Result<(), CircleError> {
    for radius_text in ["1.0", " 2.0 "] {
        let area = area_of_text(radius_text)?;
        println!("radius {} -> area {}", radius_text.trim(), area);
    }
    let records = ["3,1", "2.5,0.5"];
    for record in records {
        println!("{}", describe(record)?);
    }
    let total = total_area(&records)?;
    println!("total ring area {total:.6}");
    Ok(())
}

