    EmptySpec,
    BadDigits(String, ParseIntError),
}

impl fmt::Display for BitError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BitError::EmptySpec => write!(f, "empty number specification"),
            BitError::BadDigits(spec, err) => write!(f, "cannot parse {:?}: {}", spec, err),
        }
    }
}

impl std::error::Error for BitError {}

/// Number of set bits (1s) in the binary representation of `n`.
fn count_set_bits(mut n: u32) -> u32 {
    let mut count = 0;
    while n != 0 {
        n &= n - 1;
        count += 1;
    }
    count
}

/// Accepts plain decimal, `0b...` binary and `0x...` hexadecimal literals.
fn parse_number(spec: &str) -> Result<u32, BitError> {
    let lower = spec.trim().to_ascii_lowercase();
    let (digits, radix) = match lower.strip_prefix("0b") {
        Some(rest) => (rest, 2),
        None => match lower.strip_prefix("0x") {
            Some(rest) => (rest, 16),
            None => (lower.as_str(), 10),
        },
    };
    if digits.is_empty() {
        return Err(BitError::EmptySpec);
    }
    let value =
        u32::from_str_radix(digits, radix).map_err(|e| BitError::BadDigits(lower.clone(), e))?;
    Ok(value)
}

fn format_line(value: u32, bits: u32) -> String {
    format!("{:>10} = 0b{:032b} -> {} set bit(s)", value, value, bits)
}

fn describe(spec: &str) -> Result<String, BitError> {
    let value = parse_number(spec)?;
    Ok(format_line(value, count_set_bits(value)))
}

/// Bits that differ between two numbers given as literals.
fn hamming_distance(a: &str, b: &str) -> Result<u32, BitError> {
    let left = parse_number(a)?;
    let right = parse_number(b)?;
    Ok(count_set_bits(left ^ right))
}

fn report(specs: &[&str]) -> Result<String, BitError> {
    let mut out = String::new();
    let mut total = 0;
    for spec in specs {
        let value = parse_number(spec)?;
        let bits = count_set_bits(value);
        total += bits;
        out.push_str(&format_line(value, bits));
        out.push('\n');
    }
    out.push_str(&format!("total set bits: {}\n", total));
    Ok(out)
}

