use std::num::ParseIntError;

#[derive(Debug)]
enum ParseError {
    MissingSeparator(String),
    NotNumeric(String),
    BadNumber(ParseIntError),
    Overflow,
    UnknownItem(String),
}

impl From<ParseIntError> for ParseError {
    fn from(err: ParseIntError) -> Self {
        ParseError::BadNumber(err)
    }
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::MissingSeparator(line) => write!(f, "no ',' in line {:?}", line),
            ParseError::NotNumeric(field) => write!(f, "field {:?} is not all digits", field),
            ParseError::BadNumber(err) => write!(f, "invalid number: {}", err),
            ParseError::Overflow => write!(f, "total does not fit in u64"),
            ParseError::UnknownItem(name) => write!(f, "no item named {:?}", name),
        }
    }
}

#[derive(Debug)]
struct Record {
    name: String,
    count: u64,
}

fn is_numeric_string(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

fn parse_count(field: &str) -> Result<u64, ParseError> {
    if !is_numeric_string(field) {
        return Err(ParseError::NotNumeric(field.to_string()));
    }
    let value = field.parse::<u64>()?;
    Ok(value)
}

fn parse_record(line: &str) -> Result<Record, ParseError> {
    let (name, count) = line
        .split_once(',')
        .ok_or_else(|| ParseError::MissingSeparator(line.to_string()))?;
    let count = parse_count(count.trim())?;
    Ok(Record { name: name.trim().to_string(), count })
}

fn parse_inventory(text: &str) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        records.push(parse_record(line)?);
    }
    Ok(records)
}

fn checked_total(records: &[Record]) -> Result<u64, ParseError> {
    let mut total: u64 = 0;
    for record in records {
        total = total.checked_add(record.count).ok_or(ParseError::Overflow)?;
    }
    Ok(total)
}

fn format_report(text: &str) -> Result<String, ParseError> {
    let records = parse_inventory(text)?;
    let total = checked_total(&records)?;
    let mut out = String::new();
    for record in &records {
        out.push_str(&format!("{:<10} {:>6}\n", record.name, record.count));
    }
    out.push_str(&format!("{:<10} {:>6}\n", "TOTAL", total));
    Ok(out)
}

fn describe(text: &str, name: &str) -> Result<String, ParseError> {
    let records = parse_inventory(text)?;
    let found = records
        .into_iter()
        .find(|r| r.name == name)
        .ok_or_else(|| ParseError::UnknownItem(name.to_string()))?;
    Ok(format!("{} holds {} units", found.name, found.count))
}

fn main() {
    for sample in ["12345", "12a34", ""] {
        println!("is_numeric_string({:?}) = {}", sample, is_numeric_string(sample));
    }

    let data = "bolts, 12345\nnuts, 640\nwashers, 78";
    match format_report(data) {
        Ok(report) => print!("{}", report),
        Err(err) => eprintln!("error: {}", err),
    }
    match describe(data, "nuts") {
        Ok(line) => println!("{}", line),
        Err(err) => eprintln!("error: {}", err),
    }

    if let Err(err) = format_report("screws, 12a34") {
        println!("rejected: {}", err);
    }
}

