use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum GeomError {
    BadNumber(String, ParseFloatError),
    NotPositive(f64),
    MissingSeparator(String),
    NotAHypotenuse { c: f64, a: f64 },
}

impl fmt::Display for GeomError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GeomError::BadNumber(text, err) => write!(f, "cannot read {:?} as a length: {}", text, err),
            GeomError::NotPositive(v) => write!(f, "a side must be positive, got {}", v),
            GeomError::MissingSeparator(spec) => write!(f, "expected \"a,b\", got {:?}", spec),
            GeomError::NotAHypotenuse { c, a } => write!(f, "hypotenuse {} is not longer than leg {}", c, a),
        }
    }
}

fn hypotenuse(a: f64, b: f64) -> f64 {
    a.hypot(b)
}

fn parse_side(text: &str) -> Result<f64, GeomError> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|e| GeomError::BadNumber(trimmed.to_string(), e))?;
    if value <= 0.0 || !value.is_finite() {
        return Err(GeomError::NotPositive(value));
    }
    Ok(value)
}

fn parse_pair(spec: &str) -> Result<(f64, f64), GeomError> {
    let (left, right) = spec
        .split_once(',')
        .ok_or_else(|| GeomError::MissingSeparator(spec.to_string()))?;
    let a = parse_side(left)?;
    let b = parse_side(right)?;
    Ok((a, b))
}

fn perimeter(a: f64, b: f64) -> f64 {
    a + b + hypotenuse(a, b)
}

fn area(a: f64, b: f64) -> f64 {
    a * b / 2.0
}

fn missing_leg(c: f64, a: f64) -> Result<f64, GeomError> {
    if c <= a {
        return Err(GeomError::NotAHypotenuse { c, a });
    }
    Ok((c * c - a * a).sqrt())
}

fn describe(spec: &str) -> Result<String, GeomError> {
    let (a, b) = parse_pair(spec)?;
    Ok(format!(
        "legs {} and {}: hypotenuse {}, perimeter {}, area {}",
        a,
        b,
        hypotenuse(a, b),
        perimeter(a, b),
        area(a, b)
    ))
}

fn recover(spec: &str) -> Result<String, GeomError> {
    let (a, b) = parse_pair(spec)?;
    let other = missing_leg(hypotenuse(a, b), a)?;
    Ok(format!("from leg {} and its hypotenuse we recover leg {}", a, other))
}

fn main() -> Result<(), GeomError> {
    for spec in ["3,4", "5,12", "8, 15", "1.5,2.0"] {
        println!("{}", describe(spec)?);
    }
    println!("{}", recover("9,40")?);
    println!("leg = {}", missing_leg(13.0, 5.0)?);
    match describe("4,-3") {
        Ok(line) => println!("{}", line),
        Err(e) => println!("rejected: {}", e),
    }
    Ok(())
}

