const ABSOLUTE_ZERO_F: f64 = -459.67;

pub fn fahrenheit_to_celsius(f: f64) -> f64 {
    (f - 32.0) * 5.0 / 9.0
}

fn parse_fahrenheit(text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|e| format!("{:?} is not a temperature: {}", trimmed, e))?;
    if value < ABSOLUTE_ZERO_F {
        return Err(format!("{} °F is below absolute zero", value));
    }
    Ok(value)
}

fn split_entry(line: &str) -> Result<(&str, &str), String> {
    let (label, raw) = line
        .split_once('=')
        .ok_or_else(|| format!("expected 'label=value', got {:?}", line))?;
    let label = label.trim();
    if label.is_empty() {
        return Err(format!("empty label in {:?}", line));
    }
    Ok((label, raw))
}

fn convert_entry(line: &str) -> Result<(String, f64), String> {
    let (label, raw) = split_entry(line)?;
    let fahrenheit = parse_fahrenheit(raw)?;
    Ok((label.to_string(), fahrenheit_to_celsius(fahrenheit)))
}

fn format_entry(line: &str) -> Result<String, String> {
    let (label, celsius) = convert_entry(line)?;
    Ok(format!("{:<10} {:>8.2} C", label, celsius))
}

fn build_report(lines: &[&str]) -> Result<String, String> {
    let mut report = String::new();
    for line in lines {
        report.push_str(&format_entry(line)?);
        report.push('\n');
    }
    Ok(report)
}

fn coldest(lines: &[&str]) -> Result<(String, f64), String> {
    let first = lines.first().ok_or("no readings supplied")?;
    let mut best = convert_entry(first)?;
    for line in &lines[1..] {
        let candidate = convert_entry(line)?;
        if candidate.1 < best.1 {
            best = candidate;
        }
    }
    Ok(best)
}

fn main() -> Result<(), String> {
    let readings = [
        "freezing=32.0",
        "boiling=212.0",
        "body=98.6",
        "arctic=-40",
    ];
    print!("{}", build_report(&readings)?);
    let (label, celsius) = coldest(&readings)?;
    println!("coldest reading: {} at {:.2} C", label, celsius);
    let room = parse_fahrenheit(" 68.0 ")?;
    println!("room temperature: {:.2} C", fahrenheit_to_celsius(room));
    Ok(())
}

