use std::fmt;

#[derive(Debug)]
enum CsvError {
    Empty,
    MissingColumn(String),
    ShortRow { column: String, index: usize },
    BadNumber { column: String, value: String },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Empty => write!(f, "no data rows"),
            CsvError::MissingColumn(c) => write!(f, "missing column `{}`", c),
            CsvError::ShortRow { column, index } => {
                write!(f, "row too short: `{}` expected at index {}", column, index)
            }
            CsvError::BadNumber { column, value } => {
                write!(f, "column `{}` holds a non-numeric value `{}`", column, value)
            }
        }
    }
}

struct Reading {
    station: String,
    temp: f64,
    samples: u32,
}

fn parse_csv_row(row: &str, delimiter: char) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut quoted = false;
    let mut chars = row.chars().peekable();
    while let Some(c) = chars.next() {
        if quoted {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    quoted = false;
                }
            } else {
                current.push(c);
            }
        } else if c == '"' {
            quoted = true;
        } else if c == delimiter {
            fields.push(std::mem::take(&mut current));
        } else {
            current.push(c);
        }
    }
    fields.push(current);
    fields
}

fn field<'a>(header: &[String], cells: &'a [String], name: &str) -> Result<&'a str, CsvError> {
    let index = header
        .iter()
        .position(|h| h.trim() == name)
        .ok_or_else(|| CsvError::MissingColumn(name.to_string()))?;
    let cell = cells.get(index).ok_or_else(|| CsvError::ShortRow {
        column: name.to_string(),
        index,
    })?;
    Ok(cell.trim())
}

fn parse_record(header: &[String], line: &str, delimiter: char) -> Result<Reading, CsvError> {
    let cells = parse_csv_row(line, delimiter);
    let station = field(header, &cells, "station")?;
    let temp_text = field(header, &cells, "temp")?;
    let temp = temp_text.parse::<f64>().map_err(|_| CsvError::BadNumber {
        column: "temp".to_string(),
        value: temp_text.to_string(),
    })?;
    let samples_text = field(header, &cells, "samples")?;
    let samples = samples_text.parse::<u32>().map_err(|_| CsvError::BadNumber {
        column: "samples".to_string(),
        value: samples_text.to_string(),
    })?;
    Ok(Reading { station: station.to_string(), temp, samples })
}

fn parse_table(text: &str, delimiter: char) -> Result<Vec<Reading>, CsvError> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let header_line = lines.next().ok_or(CsvError::Empty)?;
    let header = parse_csv_row(header_line, delimiter);
    let mut readings = Vec::new();
    for line in lines {
        readings.push(parse_record(&header, line, delimiter)?);
    }
    Ok(readings)
}

fn summarize(readings: &[Reading]) -> Result<String, CsvError> {
    let hottest = readings
        .iter()
        .max_by(|a, b| a.temp.total_cmp(&b.temp))
        .ok_or(CsvError::Empty)?;
    let samples: u32 = readings.iter().map(|r| r.samples).sum();
    let mean = readings.iter().map(|r| r.temp).sum::<f64>() / readings.len() as f64;
    Ok(format!(
        "{} stations, {} samples, mean {:.2}, hottest {} at {:.1}",
        readings.len(),
        samples,
        mean,
        hottest.station,
        hottest.temp
    ))
}

fn main() -> Result<(), CsvError> {
    println!("{:?}", parse_csv_row("a,b,c", ','));
    println!("{:?}", parse_csv_row("field1;;field3", ';'));

    let data = "station;temp;samples\n\
                Oslo;-3.5;120\n\
                \"Rio de Janeiro\";31.2;87\n\
                ;18.0;5\n";
    let readings = parse_table(data, ';')?;
    for r in &readings {
        println!("{:<16} {:>6.1} ({} samples)", r.station, r.temp, r.samples);
    }
    println!("{}", summarize(&readings)?);
    Ok(())
}

