use std::cell::Cell;
use std::collections::hash_map::RandomState;
use std::env;
use std::fmt;
use std::hash::{BuildHasher, Hasher};
use std::num::ParseIntError;

#[derive(Debug)]
enum DiceError {
    Format(String),
    Number(ParseIntError),
    Sides,
}

impl fmt::Display for DiceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DiceError::Format(s) => write!(f, "malformed dice spec: {s}"),
            DiceError::Number(e) => write!(f, "bad number in dice spec: {e}"),
            DiceError::Sides => write!(f, "a die needs at least one side"),
        }
    }
}

impl From<ParseIntError> for DiceError {
    fn from(e: ParseIntError) -> Self {
        DiceError::Number(e)
    }
}

struct Spec {
    count: u8,
    sides: u8,
    modifier: i32,
}

thread_local! {
    static STATE: Cell<u64> = const { Cell::new(0) };
}

fn roll_dice(sides: u8) -> u8 {
    STATE.with(|cell| {
        let mut x = cell.get();
        if x == 0 {
            x = RandomState::new().build_hasher().finish() | 1;
        }
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        cell.set(x);
        (x % u64::from(sides)) as u8 + 1
    })
}

fn parse_sides(text: &str) -> Result<u8, DiceError> {
    let n: u8 = text.trim().parse()?;
    if n == 0 {
        return Err(DiceError::Sides);
    }
    Ok(n)
}

fn split_sides_modifier(text: &str) -> Result<(u8, i32), DiceError> {
    match text.find(['+', '-']) {
        Some(i) => {
            let sides = parse_sides(&text[..i])?;
            let modifier: i32 = text[i..].trim().parse()?;
            Ok((sides, modifier))
        }
        None => Ok((parse_sides(text)?, 0)),
    }
}

fn parse_spec(spec: &str) -> Result<Spec, DiceError> {
    let lowered = spec.trim().to_ascii_lowercase();
    let (head, tail) = lowered
        .split_once('d')
        .ok_or_else(|| DiceError::Format(spec.to_string()))?;
    let count = if head.is_empty() { 1 } else { head.trim().parse()? };
    let (sides, modifier) = split_sides_modifier(tail)?;
    Ok(Spec { count, sides, modifier })
}

fn roll_spec(spec: &str) -> Result<i32, DiceError> {
    let parsed = parse_spec(spec)?;
    let mut total = parsed.modifier;
    for _ in 0..parsed.count {
        total += i32::from(roll_dice(parsed.sides));
    }
    Ok(total)
}

fn format_roll(spec: &str) -> Result<String, DiceError> {
    let total = roll_spec(spec)?;
    Ok(format!("{spec:>8} => {total}"))
}

fn check_success(spec: &str, target: i32) -> Result<bool, DiceError> {
    Ok(roll_spec(spec)? >= target)
}

fn summarize(specs: &[&str]) -> Result<String, DiceError> {
    let mut lines = Vec::with_capacity(specs.len());
    for spec in specs {
        lines.push(format_roll(spec)?);
    }
    Ok(lines.join("\n"))
}

fn main() -> Result<(), DiceError> {
    println!("single d6:  {}", roll_dice(6));
    println!("single d20: {}", roll_dice(20));

    let args: Vec<String> = env::args().skip(1).collect();
    let specs: Vec<&str> = if args.is_empty() {
        vec!["1d6", "3d6+2", "d20", "2d10-1"]
    } else {
        args.iter().map(String::as_str).collect()
    };
    println!("{}", summarize(&specs)?);

    let target = 15;
    if check_success("1d20+5", target)? {
        println!("attack vs {target}: hit");
    } else {
        println!("attack vs {target}: miss");
    }
    Ok(())
}

